import React from 'react';
import { cn } from '@/lib/utils';

export default function HolographicCard({ 
  children, 
  className,
  glowColor = 'cyan',
  intensity = 'medium',
  animated = true,
  variant = 'default'
}) {
  const glowColors = {
    cyan: {
      border: 'border-cyan-500/30',
      glow: 'shadow-cyan-500/20',
      bg: 'from-cyan-500/5 to-transparent',
      accent: 'bg-cyan-500'
    },
    green: {
      border: 'border-green-500/30',
      glow: 'shadow-green-500/20',
      bg: 'from-green-500/5 to-transparent',
      accent: 'bg-green-500'
    },
    purple: {
      border: 'border-purple-500/30',
      glow: 'shadow-purple-500/20',
      bg: 'from-purple-500/5 to-transparent',
      accent: 'bg-purple-500'
    },
    red: {
      border: 'border-red-500/30',
      glow: 'shadow-red-500/20',
      bg: 'from-red-500/5 to-transparent',
      accent: 'bg-red-500'
    },
    orange: {
      border: 'border-orange-500/30',
      glow: 'shadow-orange-500/20',
      bg: 'from-orange-500/5 to-transparent',
      accent: 'bg-orange-500'
    }
  };

  const intensities = {
    low: 'shadow-lg',
    medium: 'shadow-xl',
    high: 'shadow-2xl'
  };

  const colors = glowColors[glowColor] || glowColors.cyan;

  return (
    <div 
      className={cn(
        // Base styles
        'relative rounded-xl overflow-hidden',
        'bg-slate-950/80 backdrop-blur-xl',
        'border',
        colors.border,
        intensities[intensity],
        colors.glow,
        // Animation
        animated && 'transition-all duration-500 hover:scale-[1.01]',
        className
      )}
    >
      {/* Holographic gradient overlay */}
      <div 
        className={cn(
          'absolute inset-0 bg-gradient-to-br opacity-50 pointer-events-none',
          colors.bg
        )}
      />

      {/* Scan line effect */}
      {animated && (
        <div 
          className="absolute inset-0 pointer-events-none overflow-hidden"
          style={{
            background: `repeating-linear-gradient(
              0deg,
              transparent,
              transparent 2px,
              rgba(255,255,255,0.03) 2px,
              rgba(255,255,255,0.03) 4px
            )`
          }}
        />
      )}

      {/* Corner accents */}
      <div className={cn('absolute top-0 left-0 w-6 h-6 border-l-2 border-t-2 rounded-tl-xl', colors.border)} />
      <div className={cn('absolute top-0 right-0 w-6 h-6 border-r-2 border-t-2 rounded-tr-xl', colors.border)} />
      <div className={cn('absolute bottom-0 left-0 w-6 h-6 border-l-2 border-b-2 rounded-bl-xl', colors.border)} />
      <div className={cn('absolute bottom-0 right-0 w-6 h-6 border-r-2 border-b-2 rounded-br-xl', colors.border)} />

      {/* Corner dots */}
      <div className={cn('absolute top-2 left-2 w-1.5 h-1.5 rounded-full', colors.accent, animated && 'animate-pulse')} />
      <div className={cn('absolute top-2 right-2 w-1.5 h-1.5 rounded-full', colors.accent, animated && 'animate-pulse')} />
      <div className={cn('absolute bottom-2 left-2 w-1.5 h-1.5 rounded-full', colors.accent, animated && 'animate-pulse')} />
      <div className={cn('absolute bottom-2 right-2 w-1.5 h-1.5 rounded-full', colors.accent, animated && 'animate-pulse')} />

      {/* Animated border glow */}
      {animated && (
        <div 
          className="absolute inset-0 rounded-xl pointer-events-none"
          style={{
            background: `linear-gradient(90deg, transparent, ${glowColor === 'cyan' ? 'rgba(6, 182, 212, 0.1)' : glowColor === 'green' ? 'rgba(34, 197, 94, 0.1)' : glowColor === 'purple' ? 'rgba(168, 85, 247, 0.1)' : glowColor === 'red' ? 'rgba(239, 68, 68, 0.1)' : 'rgba(249, 115, 22, 0.1)'}, transparent)`,
            animation: 'holographic-sweep 3s ease-in-out infinite'
          }}
        />
      )}

      {/* Content */}
      <div className="relative z-10">
        {children}
      </div>

      <style>{`
        @keyframes holographic-sweep {
          0%, 100% {
            transform: translateX(-100%);
            opacity: 0;
          }
          50% {
            transform: translateX(100%);
            opacity: 1;
          }
        }
      `}</style>
    </div>
  );
}

// Holographic Button variant
export function HolographicButton({ 
  children, 
  className,
  glowColor = 'cyan',
  onClick,
  disabled
}) {
  const glowColors = {
    cyan: 'border-cyan-500/50 text-cyan-400 hover:bg-cyan-500/20 hover:shadow-cyan-500/30',
    green: 'border-green-500/50 text-green-400 hover:bg-green-500/20 hover:shadow-green-500/30',
    purple: 'border-purple-500/50 text-purple-400 hover:bg-purple-500/20 hover:shadow-purple-500/30',
    red: 'border-red-500/50 text-red-400 hover:bg-red-500/20 hover:shadow-red-500/30',
    orange: 'border-orange-500/50 text-orange-400 hover:bg-orange-500/20 hover:shadow-orange-500/30'
  };

  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={cn(
        'relative px-6 py-3 rounded-lg',
        'bg-slate-950/50 backdrop-blur-sm',
        'border-2',
        'font-mono font-bold',
        'transition-all duration-300',
        'hover:shadow-lg hover:scale-105',
        'disabled:opacity-50 disabled:cursor-not-allowed disabled:hover:scale-100',
        glowColors[glowColor],
        className
      )}
    >
      {/* Glow effect */}
      <div className="absolute inset-0 rounded-lg bg-gradient-to-r from-transparent via-white/5 to-transparent opacity-0 hover:opacity-100 transition-opacity" />

      <span className="relative z-10">{children}</span>
    </button>
  );
}

// Holographic Panel for data display
export function HolographicPanel({ 
  title, 
  children, 
  className,
  glowColor = 'cyan',
  icon: Icon
}) {
  const titleColors = {
    cyan: 'text-cyan-400',
    green: 'text-green-400',
    purple: 'text-purple-400',
    red: 'text-red-400',
    orange: 'text-orange-400'
  };

  return (
    <HolographicCard glowColor={glowColor} className={cn('p-6', className)}>
      {title && (
        <div className="flex items-center gap-3 mb-4">
          {Icon && (
            <div className={cn('p-2 rounded-lg bg-slate-900/50 border', `border-${glowColor}-500/30`)}>
              <Icon className={cn('w-5 h-5', titleColors[glowColor])} />
            </div>
          )}
          <h3 className={cn('text-lg font-bold font-mono glow-text', titleColors[glowColor])}>
            {title}
          </h3>
        </div>
      )}
      {children}
    </HolographicCard>
  );
}

src/components/ai/AIOpponentSystem.jsx:
import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Slider } from '@/components/ui/slider';
import { Badge } from '@/components/ui/badge';
import { Bot, Loader2, Zap, Target, Shield } from 'lucide-react';

export default function AIOpponentSystem({ onOpponentGenerated }) {
  const [opponentParams, setOpponentParams] = useState({
    name: '',
    aggression: 50,
    technological_focus: 50,
    diplomatic_approach: 50,
    economic_strategy: 50,
    military_doctrine: 'balanced'
  });

  const generateOpponentMutation = useMutation({
    mutationFn: async (params) => {
      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `Generate a detailed AI opponent for a war simulation with the following parameters:

Name: ${params.name || 'Unnamed Opponent'}
Aggression Level: ${params.aggression}/100
Technological Focus: ${params.technological_focus}/100
Diplomatic Approach: ${params.diplomatic_approach}/100 (0=hostile, 100=cooperative)
Economic Strategy: ${params.economic_strategy}/100 (0=isolationist, 100=free trade)
Military Doctrine: ${params.military_doctrine}

Create a comprehensive AI opponent profile that will dynamically adapt its strategy based on:
1. User actions and decisions
2. Resource availability
3. Battlefield conditions
4. Diplomatic relations
5. Economic factors

The AI should have clear strategic goals, decision-making patterns, and response protocols.`,
        response_json_schema: {
          type: "object",
          properties: {
            name: { type: "string" },
            description: { type: "string" },
            strategic_goals: { type: "array", items: { type: "string" } },
            strengths: { type: "array", items: { type: "string" } },
            weaknesses: { type: "array", items: { type: "string" } },
            decision_patterns: {
              type: "object",
              properties: {
                offensive_triggers: { type: "array", items: { type: "string" } },
                defensive_triggers: { type: "array", items: { type: "string" } },
                diplomatic_conditions: { type: "array", items: { type: "string" } },
                economic_priorities: { type: "array", items: { type: "string" } }
              }
            },
            adaptation_rules: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  condition: { type: "string" },
                  response: { type: "string" },
                  priority: { type: "string" }
                }
              }
            },
            starting_resources: {
              type: "object",
              properties: {
                military: { type: "number" },
                economic: { type: "number" },
                technological: { type: "number" },
                diplomatic: { type: "number" }
              }
            },
            personality_traits: { type: "array", items: { type: "string" } }
          }
        }
      });

      return result;
    },
    onSuccess: (data) => {
      if (onOpponentGenerated) onOpponentGenerated(data);
    }
  });

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-center gap-3 mb-6">
        <Bot className="w-8 h-8 text-cyan-400" />
        <div>
          <h3 className="text-2xl font-bold text-cyan-400 glow-text font-mono">
            AI OPPONENT GENERATOR
          </h3>
          <p className="text-slate-400 font-mono text-sm">
            Create adaptive AI adversaries with custom parameters
          </p>
        </div>
      </div>

      <div className="space-y-6">
        <div className="space-y-2">
          <Label className="text-green-400 font-mono">Opponent Name</Label>
          <Input
            value={opponentParams.name}
            onChange={(e) => setOpponentParams({...opponentParams, name: e.target.value})}
            placeholder="e.g., Red Empire, Coalition Forces..."
            className="bg-slate-900/50 border-green-500/30 text-green-400 font-mono"
          />
        </div>

        <div className="grid md:grid-cols-2 gap-6">
          <div className="space-y-4">
            <div>
              <Label className="text-cyan-400 font-mono mb-2 block">
                Aggression: {opponentParams.aggression}%
              </Label>
              <Slider
                value={[opponentParams.aggression]}
                onValueChange={(v) => setOpponentParams({...opponentParams, aggression: v[0]})}
                max={100}
                step={1}
                className="py-4"
              />
              <p className="text-xs text-slate-500 font-mono mt-1">
                {opponentParams.aggression < 30 ? 'Defensive' : opponentParams.aggression < 70 ? 'Balanced' : 'Aggressive'}
              </p>
            </div>

            <div>
              <Label className="text-purple-400 font-mono mb-2 block">
                Technological Focus: {opponentParams.technological_focus}%
              </Label>
              <Slider
                value={[opponentParams.technological_focus]}
                onValueChange={(v) => setOpponentParams({...opponentParams, technological_focus: v[0]})}
                max={100}
                step={1}
                className="py-4"
              />
              <p className="text-xs text-slate-500 font-mono mt-1">
                {opponentParams.technological_focus < 30 ? 'Traditional' : opponentParams.technological_focus < 70 ? 'Moderate' : 'Advanced'}
              </p>
            </div>
          </div>

          <div className="space-y-4">
            <div>
              <Label className="text-yellow-400 font-mono mb-2 block">
                Diplomatic Approach: {opponentParams.diplomatic_approach}%
              </Label>
              <Slider
                value={[opponentParams.diplomatic_approach]}
                onValueChange={(v) => setOpponentParams({...opponentParams, diplomatic_approach: v[0]})}
                max={100}
                step={1}
                className="py-4"
              />
              <p className="text-xs text-slate-500 font-mono mt-1">
                {opponentParams.diplomatic_approach < 30 ? 'Hostile' : opponentParams.diplomatic_approach < 70 ? 'Neutral' : 'Cooperative'}
              </p>
            </div>

            <div>
              <Label className="text-orange-400 font-mono mb-2 block">
                Economic Strategy: {opponentParams.economic_strategy}%
              </Label>
              <Slider
                value={[opponentParams.economic_strategy]}
                onValueChange={(v) => setOpponentParams({...opponentParams, economic_strategy: v[0]})}
                max={100}
                step={1}
                className="py-4"
              />
              <p className="text-xs text-slate-500 font-mono mt-1">
                {opponentParams.economic_strategy < 30 ? 'Isolationist' : opponentParams.economic_strategy < 70 ? 'Mixed' : 'Free Trade'}
              </p>
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <Label className="text-red-400 font-mono">Military Doctrine</Label>
          <div className="grid grid-cols-3 gap-2">
            {['offensive', 'balanced', 'defensive'].map((doctrine) => (
              <Button
                key={doctrine}
                onClick={() => setOpponentParams({...opponentParams, military_doctrine: doctrine})}
                variant={opponentParams.military_doctrine === doctrine ? 'default' : 'outline'}
                className={`font-mono ${
                  opponentParams.military_doctrine === doctrine
                    ? 'bg-red-500/20 text-red-400 border-red-500/50'
                    : 'border-slate-500/30'
                }`}
              >
                {doctrine.toUpperCase()}
              </Button>
            ))}
          </div>
        </div>

        <Button
          onClick={() => generateOpponentMutation.mutate(opponentParams)}
          disabled={generateOpponentMutation.isPending || !opponentParams.name}
          className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-mono py-6"
        >
          {generateOpponentMutation.isPending ? (
            <>
              <Loader2 className="w-5 h-5 mr-2 animate-spin" />
              GENERATING AI OPPONENT...
            </>
          ) : (
            <>
              <Zap className="w-5 h-5 mr-2" />
              GENERATE OPPONENT
            </>
          )}
        </Button>

        {generateOpponentMutation.data && (
          <Card className="bg-gradient-to-br from-cyan-950/50 to-purple-950/50 cyber-border p-6 mt-6">
            <div className="flex items-center gap-3 mb-4">
              <Bot className="w-6 h-6 text-cyan-400" />
              <h4 className="text-xl font-bold text-cyan-400 font-mono">
                {generateOpponentMutation.data.name}
              </h4>
            </div>
            <p className="text-slate-300 font-mono text-sm mb-4">
              {generateOpponentMutation.data.description}
            </p>

            <div className="grid md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <h5 className="text-sm font-bold text-green-400 font-mono">STRENGTHS</h5>
                <ul className="space-y-1">
                  {generateOpponentMutation.data.strengths?.map((s, i) => (
                    <li key={i} className="text-slate-400 font-mono text-xs">✓ {s}</li>
                  ))}
                </ul>
              </div>
              <div className="space-y-2">
                <h5 className="text-sm font-bold text-red-400 font-mono">WEAKNESSES</h5>
                <ul className="space-y-1">
                  {generateOpponentMutation.data.weaknesses?.map((w, i) => (
                    <li key={i} className="text-slate-400 font-mono text-xs">× {w}</li>
                  ))}
                </ul>
              </div>
            </div>
          </Card>
        )}
      </div>
    </Card>
  );
}

import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Sparkles, Loader2, BookOpen } from 'lucide-react';

export default function FictionalWarGenerator({ onScenarioGenerated }) {
  const [prompt, setPrompt] = useState('');

  const generateScenarioMutation = useMutation({
    mutationFn: async (userPrompt) => {
      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `Generate a detailed fictional historical war scenario based on this prompt: "${userPrompt}"

Create a compelling, realistic alternative history war scenario with:
1. Unique narrative and historical context
2. Believable nations/factions with distinct characteristics
3. Clear causes and motivations
4. Strategic challenges and dilemmas
5. Key historical figures (fictional or reimagined)
6. Technological and tactical considerations
7. Multiple potential outcomes
8. Moral and ethical dimensions

Make it engaging, historically plausible (even if fictional), and strategically interesting.`,
        response_json_schema: {
          type: "object",
          properties: {
            title: { type: "string" },
            era: { type: "string" },
            year: { type: "string" },
            narrative: { type: "string" },
            historical_context: { type: "string" },
            factions: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  name: { type: "string" },
                  description: { type: "string" },
                  leader: { type: "string" },
                  strengths: { type: "array", items: { type: "string" } },
                  weaknesses: { type: "array", items: { type: "string" } },
                  motivations: { type: "string" },
                  military_strength: { type: "number" }
                }
              }
            },
            causes: { type: "array", items: { type: "string" } },
            key_events: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  event: { type: "string" },
                  date: { type: "string" },
                  significance: { type: "string" }
                }
              }
            },
            strategic_challenges: { type: "array", items: { type: "string" } },
            technology_level: { type: "string" },
            potential_outcomes: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  outcome: { type: "string" },
                  probability: { type: "number" },
                  consequences: { type: "string" }
                }
              }
            },
            moral_dimensions: { type: "array", items: { type: "string" } }
          }
        }
      });

      return result;
    },
    onSuccess: (data) => {
      if (onScenarioGenerated) onScenarioGenerated(data);
    }
  });

  const quickPrompts = [
    "Victorian-era steam-powered colonial war",
    "1960s alternate Cold War turning hot",
    "Medieval crusade with advanced siege technology",
    "Ancient Rome vs advanced Carthaginian navy",
    "1920s global economic war with military intervention"
  ];

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-center gap-3 mb-6">
        <Sparkles className="w-8 h-8 text-purple-400" />
        <div>
          <h3 className="text-2xl font-bold text-purple-400 glow-text font-mono">
            FICTIONAL WAR GENERATOR
          </h3>
          <p className="text-slate-400 font-mono text-sm">
            Create unique alternative history war scenarios
          </p>
        </div>
      </div>

      <div className="space-y-4">
        <div className="space-y-2">
          <label className="text-sm font-bold text-cyan-400 font-mono">
            Scenario Prompt
          </label>
          <Textarea
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            placeholder="e.g., A steampunk war between airship empires in 1880s Asia..."
            className="bg-slate-900/50 border-cyan-500/30 text-cyan-400 font-mono min-h-[100px]"
          />
        </div>

        <div className="space-y-2">
          <label className="text-xs text-slate-500 font-mono">Quick Prompts:</label>
          <div className="flex flex-wrap gap-2">
            {quickPrompts.map((qp, idx) => (
              <Button
                key={idx}
                onClick={() => setPrompt(qp)}
                variant="outline"
                className="border-purple-500/30 text-purple-400 hover:bg-purple-500/10 font-mono text-xs"
              >
                {qp}
              </Button>
            ))}
          </div>
        </div>

        <Button
          onClick={() => generateScenarioMutation.mutate(prompt)}
          disabled={generateScenarioMutation.isPending || !prompt.trim()}
          className="w-full bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white font-mono py-6"
        >
          {generateScenarioMutation.isPending ? (
            <>
              <Loader2 className="w-5 h-5 mr-2 animate-spin" />
              GENERATING SCENARIO...
            </>
          ) : (
            <>
              <Sparkles className="w-5 h-5 mr-2" />
              GENERATE FICTIONAL WAR
            </>
          )}
        </Button>

        {generateScenarioMutation.data && (
          <div className="space-y-4 mt-6 animate-in fade-in duration-500">
            <Card className="bg-gradient-to-br from-purple-950/50 to-pink-950/50 cyber-border p-6">
              <div className="flex items-center gap-3 mb-3">
                <BookOpen className="w-6 h-6 text-purple-400" />
                <h4 className="text-2xl font-bold text-purple-400 font-mono">
                  {generateScenarioMutation.data.title}
                </h4>
              </div>
              <div className="flex gap-2 mb-4">
                <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 font-mono">
                  {generateScenarioMutation.data.era}
                </Badge>
                <Badge className="bg-purple-500/20 text-purple-400 border-purple-500/30 font-mono">
                  {generateScenarioMutation.data.year}
                </Badge>
              </div>
              <p className="text-slate-300 font-mono text-sm leading-relaxed mb-4">
                {generateScenarioMutation.data.narrative}
              </p>
              <div className="p-4 bg-slate-900/50 cyber-border rounded">
                <h5 className="text-sm font-bold text-yellow-400 font-mono mb-2">HISTORICAL CONTEXT</h5>
                <p className="text-slate-400 font-mono text-xs">
                  {generateScenarioMutation.data.historical_context}
                </p>
              </div>
            </Card>

            {generateScenarioMutation.data.factions?.length > 0 && (
              <Card className="bg-slate-950/80 cyber-border p-6">
                <h4 className="text-xl font-bold text-green-400 font-mono mb-4">FACTIONS</h4>
                <div className="grid md:grid-cols-2 gap-4">
                  {generateScenarioMutation.data.factions.map((faction, idx) => (
                    <div key={idx} className="bg-slate-900/50 cyber-border rounded p-4">
                      <h5 className="text-lg font-bold text-cyan-400 font-mono mb-1">{faction.name}</h5>
                      <p className="text-xs text-purple-400 font-mono mb-2">Led by {faction.leader}</p>
                      <p className="text-slate-400 font-mono text-xs mb-3">{faction.description}</p>
                      <div className="text-xs font-mono text-slate-500 mb-2">
                        Military Strength: <span className="text-orange-400 font-bold">{faction.military_strength}/100</span>
                      </div>
                    </div>
                  ))}
                </div>
              </Card>
            )}
          </div>
        )}
      </div>
    </Card>
  );
}

src/components/ai/PolicyRecommendationEn:
import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Progress } from '@/components/ui/progress';
import { 
  Brain, Loader2, Shield, Globe, DollarSign, Users,
  ChevronRight, AlertTriangle, CheckCircle, TrendingUp,
  Clock, Target, Zap
} from 'lucide-react';
import { toast } from 'sonner';
import { RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip } from 'recharts';

export default function PolicyRecommendationEngine({ threatData, simulationData }) {
  const [customContext, setCustomContext] = useState('');
  const [recommendations, setRecommendations] = useState(null);

  const generateRecommendationsMutation = useMutation({
    mutationFn: async () => {
      const context = customContext || JSON.stringify(threatData || simulationData || {});

      const response = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a senior policy advisor with expertise in conflict resolution, international relations, and crisis management. Based on the following threat assessment or simulation data, generate comprehensive policy recommendations.

CONTEXT:
${context}

Generate detailed policy recommendations across these domains:

1. DIPLOMATIC OPTIONS
   - Bilateral negotiations
   - Multilateral frameworks
   - UN/regional organization involvement
   - Track II diplomacy options

2. ECONOMIC MEASURES
   - Sanctions packages (targeted vs broad)
   - Economic incentives
   - Trade policy adjustments
   - Financial assistance programs

3. MILITARY POSTURE
   - Deterrence options
   - Alliance coordination
   - Force positioning
   - Rules of engagement recommendations

4. HUMANITARIAN INTERVENTIONS
   - Refugee assistance
   - Medical aid deployment
   - Food security programs
   - Civilian protection measures

For each recommendation provide:
- Success probability with confidence interval
- Resource cost estimate
- Timeline to implementation
- Potential side effects and risks
- Prerequisites and dependencies`,
        response_json_schema: {
          type: 'object',
          properties: {
            executive_summary: { type: 'string' },
            overall_situation_assessment: { type: 'string' },
            diplomatic_recommendations: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  title: { type: 'string' },
                  description: { type: 'string' },
                  success_probability: { type: 'number' },
                  confidence_interval: { type: 'string' },
                  resource_cost: { type: 'string' },
                  timeline: { type: 'string' },
                  key_actions: { type: 'array', items: { type: 'string' } },
                  risks: { type: 'array', items: { type: 'string' } },
                  prerequisites: { type: 'array', items: { type: 'string' } }
                }
              }
            },
            economic_recommendations: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  title: { type: 'string' },
                  description: { type: 'string' },
                  success_probability: { type: 'number' },
                  confidence_interval: { type: 'string' },
                  resource_cost: { type: 'string' },
                  economic_impact: { type: 'string' },
                  timeline: { type: 'string' },
                  key_actions: { type: 'array', items: { type: 'string' } },
                  side_effects: { type: 'array', items: { type: 'string' } }
                }
              }
            },
            military_recommendations: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  title: { type: 'string' },
                  description: { type: 'string' },
                  success_probability: { type: 'number' },
                  confidence_interval: { type: 'string' },
                  resource_cost: { type: 'string' },
                  escalation_risk: { type: 'number' },
                  timeline: { type: 'string' },
                  key_actions: { type: 'array', items: { type: 'string' } },
                  risks: { type: 'array', items: { type: 'string' } }
                }
              }
            },
            humanitarian_recommendations: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  title: { type: 'string' },
                  description: { type: 'string' },
                  success_probability: { type: 'number' },
                  resource_cost: { type: 'string' },
                  beneficiaries_estimate: { type: 'number' },
                  timeline: { type: 'string' },
                  key_actions: { type: 'array', items: { type: 'string' } },
                  coordination_needs: { type: 'array', items: { type: 'string' } }
                }
              }
            },
            integrated_strategy: {
              type: 'object',
              properties: {
                recommended_approach: { type: 'string' },
                sequencing: { type: 'array', items: { type: 'string' } },
                total_cost_estimate: { type: 'string' },
                overall_success_probability: { type: 'number' },
                critical_success_factors: { type: 'array', items: { type: 'string' } }
              }
            },
            risk_assessment: {
              type: 'object',
              properties: {
                inaction_risk: { type: 'string' },
                escalation_scenarios: { type: 'array', items: { type: 'string' } },
                mitigation_strategies: { type: 'array', items: { type: 'string' } }
              }
            }
          }
        },
        add_context_from_internet: true
      });

      return response;
    },
    onSuccess: (data) => {
      setRecommendations(data);
      toast.success('Policy recommendations generated');
    }
  });

  const getCategoryIcon = (category) => {
    const icons = {
      diplomatic: Globe,
      economic: DollarSign,
      military: Shield,
      humanitarian: Users
    };
    return icons[category] || Brain;
  };

  const prepareRadarData = () => {
    if (!recommendations) return [];
    return [
      { domain: 'Diplomatic', value: recommendations.diplomatic_recommendations?.[0]?.success_probability || 0 },
      { domain: 'Economic', value: recommendations.economic_recommendations?.[0]?.success_probability || 0 },
      { domain: 'Military', value: recommendations.military_recommendations?.[0]?.success_probability || 0 },
      { domain: 'Humanitarian', value: recommendations.humanitarian_recommendations?.[0]?.success_probability || 0 }
    ];
  };

  const RecommendationCard = ({ rec, category }) => {
    const Icon = getCategoryIcon(category);
    const colorMap = {
      diplomatic: 'blue',
      economic: 'yellow',
      military: 'red',
      humanitarian: 'green'
    };
    const color = colorMap[category] || 'cyan';

    return (
      <div className={`bg-${color}-500/10 border border-${color}-500/30 rounded-lg p-4`}>
        <div className="flex items-start justify-between mb-3">
          <div className="flex items-center gap-2">
            <Icon className={`w-5 h-5 text-${color}-400`} />
            <h5 className={`text-${color}-400 font-mono font-bold text-sm`}>{rec.title}</h5>
          </div>
          <Badge className={`bg-${color}-500/20 text-${color}-400 font-mono text-xs`}>
            {rec.success_probability}% success
          </Badge>
        </div>

        <p className="text-slate-400 font-mono text-xs mb-3">{rec.description}</p>

        <div className="grid grid-cols-3 gap-2 mb-3">
          <div className="bg-slate-800/50 rounded p-2">
            <div className="text-[10px] text-slate-500 font-mono">COST</div>
            <div className={`text-${color}-400 font-mono text-xs`}>{rec.resource_cost}</div>
          </div>
          <div className="bg-slate-800/50 rounded p-2">
            <div className="text-[10px] text-slate-500 font-mono">TIMELINE</div>
            <div className={`text-${color}-400 font-mono text-xs`}>{rec.timeline}</div>
          </div>
          <div className="bg-slate-800/50 rounded p-2">
            <div className="text-[10px] text-slate-500 font-mono">CONFIDENCE</div>
            <div className={`text-${color}-400 font-mono text-xs`}>{rec.confidence_interval}</div>
          </div>
        </div>

        {rec.key_actions?.length > 0 && (
          <div className="mb-3">
            <div className="text-[10px] text-slate-500 font-mono mb-1">KEY ACTIONS</div>
            <ul className="space-y-1">
              {rec.key_actions.slice(0, 3).map((action, i) => (
                <li key={i} className="text-slate-300 font-mono text-[10px] flex items-start gap-1">
                  <CheckCircle className="w-3 h-3 mt-0.5 text-green-400 flex-shrink-0" />
                  {action}
                </li>
              ))}
            </ul>
          </div>
        )}

        {rec.risks?.length > 0 && (
          <div>
            <div className="text-[10px] text-red-400 font-mono mb-1">RISKS</div>
            <div className="flex flex-wrap gap-1">
              {rec.risks.slice(0, 3).map((risk, i) => (
                <Badge key={i} variant="outline" className="border-red-500/30 text-red-400 font-mono text-[10px]">
                  {risk}
                </Badge>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl border border-sky-900/40 p-6">
      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 rounded-lg bg-green-500/20 border border-green-500/30">
          <Brain className="w-6 h-6 text-green-400" />
        </div>
        <div>
          <h3 className="text-xl font-bold text-green-400 glow-text font-mono">
            AI POLICY RECOMMENDATION ENGINE
          </h3>
          <p className="text-xs text-slate-400 font-mono">AI-generated diplomatic, economic, military & humanitarian recommendations</p>
        </div>
      </div>

      <div className="space-y-4">
        {/* Custom Context */}
        <div>
          <label className="text-green-400 font-mono text-xs mb-1 block">CONTEXT (Optional - uses threat/simulation data if empty)</label>
          <Textarea
            value={customContext}
            onChange={(e) => setCustomContext(e.target.value)}
            placeholder="Describe the situation requiring policy recommendations..."
            className="bg-slate-900/50 border-green-500/30 text-slate-200 font-mono h-20"
          />
        </div>

        <Button
          onClick={() => generateRecommendationsMutation.mutate()}
          disabled={generateRecommendationsMutation.isPending}
          className="w-full bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-600 hover:to-emerald-600 text-white font-mono"
        >
          {generateRecommendationsMutation.isPending ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              GENERATING RECOMMENDATIONS...
            </>
          ) : (
            <>
              <Brain className="w-4 h-4 mr-2" />
              GENERATE POLICY RECOMMENDATIONS
            </>
          )}
        </Button>

        {recommendations && (
          <Tabs defaultValue="overview" className="space-y-4">
            <TabsList className="grid grid-cols-5 bg-slate-900/50">
              <TabsTrigger value="overview" className="font-mono text-[10px]">OVERVIEW</TabsTrigger>
              <TabsTrigger value="diplomatic" className="font-mono text-[10px]">DIPLOMATIC</TabsTrigger>
              <TabsTrigger value="economic" className="font-mono text-[10px]">ECONOMIC</TabsTrigger>
              <TabsTrigger value="military" className="font-mono text-[10px]">MILITARY</TabsTrigger>
              <TabsTrigger value="humanitarian" className="font-mono text-[10px]">HUMANITARIAN</TabsTrigger>
            </TabsList>

            <TabsContent value="overview" className="space-y-4">
              {/* Executive Summary */}
              <Card className="bg-green-500/10 border border-green-500/30 p-4">
                <h4 className="text-green-400 font-mono font-bold text-sm mb-2">EXECUTIVE SUMMARY</h4>
                <p className="text-slate-300 font-mono text-sm">{recommendations.executive_summary}</p>
              </Card>

              {/* Radar Chart */}
              <Card className="bg-slate-900/50 border border-sky-800/30 p-4">
                <h4 className="text-cyan-400 font-mono font-bold text-sm mb-4">SUCCESS PROBABILITY BY DOMAIN</h4>
                <div className="h-[250px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <RadarChart data={prepareRadarData()}>
                      <PolarGrid stroke="#334155" />
                      <PolarAngleAxis dataKey="domain" stroke="#94a3b8" style={{ fontSize: '11px', fontFamily: 'monospace' }} />
                      <PolarRadiusAxis domain={[0, 100]} stroke="#64748b" />
                      <Radar name="Success %" dataKey="value" stroke="#22c55e" fill="#22c55e" fillOpacity={0.5} />
                    </RadarChart>
                  </ResponsiveContainer>
                </div>
              </Card>

              {/* Integrated Strategy */}
              {recommendations.integrated_strategy && (
                <Card className="bg-purple-500/10 border border-purple-500/30 p-4">
                  <h4 className="text-purple-400 font-mono font-bold text-sm mb-3 flex items-center gap-2">
                    <Target className="w-4 h-4" />
                    INTEGRATED STRATEGY
                  </h4>
                  <p className="text-slate-300 font-mono text-sm mb-3">{recommendations.integrated_strategy.recommended_approach}</p>

                  <div className="grid grid-cols-2 gap-4 mb-3">
                    <div className="bg-slate-800/50 rounded p-2">
                      <div className="text-[10px] text-slate-500 font-mono">TOTAL COST</div>
                      <div className="text-purple-400 font-mono text-sm">{recommendations.integrated_strategy.total_cost_estimate}</div>
                    </div>
                    <div className="bg-slate-800/50 rounded p-2">
                      <div className="text-[10px] text-slate-500 font-mono">OVERALL SUCCESS</div>
                      <div className="text-green-400 font-mono text-sm">{recommendations.integrated_strategy.overall_success_probability}%</div>
                    </div>
                  </div>

                  {recommendations.integrated_strategy.sequencing?.length > 0 && (
                    <div>
                      <div className="text-[10px] text-purple-400 font-mono mb-2">RECOMMENDED SEQUENCING</div>
                      <ol className="space-y-1">
                        {recommendations.integrated_strategy.sequencing.map((step, i) => (
                          <li key={i} className="text-slate-300 font-mono text-xs flex items-start gap-2">
                            <span className="text-purple-400 font-bold">{i + 1}.</span>
                            {step}
                          </li>
                        ))}
                      </ol>
                    </div>
                  )}
                </Card>
              )}
            </TabsContent>

            <TabsContent value="diplomatic" className="space-y-4">
              {recommendations.diplomatic_recommendations?.map((rec, i) => (
                <RecommendationCard key={i} rec={rec} category="diplomatic" />
              ))}
            </TabsContent>

            <TabsContent value="economic" className="space-y-4">
              {recommendations.economic_recommendations?.map((rec, i) => (
                <RecommendationCard key={i} rec={rec} category="economic" />
              ))}
            </TabsContent>

            <TabsContent value="military" className="space-y-4">
              {recommendations.military_recommendations?.map((rec, i) => (
                <RecommendationCard key={i} rec={rec} category="military" />
              ))}
            </TabsContent>

            <TabsContent value="humanitarian" className="space-y-4">
              {recommendations.humanitarian_recommendations?.map((rec, i) => (
                <RecommendationCard key={i} rec={rec} category="humanitarian" />
              ))}
            </TabsContent>
          </Tabs>
        )}
      </div>
    </Card>
  );
}

src/components/ai/ThreatAssessmentEngine:
import React, { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Shield, Loader2, AlertTriangle, TrendingUp, Eye, 
  Radio, Globe, Zap, ChevronRight, Clock, Target,
  Search, FileText, Crosshair, CheckCircle, Info,
  TrendingDown, Activity, Users, Swords, Brain
} from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area } from 'recharts';

export default function ThreatAssessmentEngine({ onThreatDetected }) {
  const [threats, setThreats] = useState(null);
  const [isScanning, setIsScanning] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  const [selectedThreat, setSelectedThreat] = useState(null);

  const scanThreatsMutation = useMutation({
    mutationFn: async () => {
      setIsScanning(true);
      setScanProgress(0);

      const progressInterval = setInterval(() => {
        setScanProgress(prev => Math.min(prev + 6, 90));
      }, 500);

      const response = await base44.integrations.Core.InvokeLLM({
        prompt: `You are an advanced geopolitical threat assessment AI with deep analytical capabilities. Perform a comprehensive global threat scan with IN-DEPTH ANALYSIS for each threat.

Analyze all current global conditions and identify emerging threats BEFORE they fully develop.

For each identified threat, provide EXTENSIVE DETAIL including:

1. BASIC THREAT INFO:
   - Threat name, type, and geographic region
   - Current threat level (1-100)
   - Probability of escalation within 30 days
   - Key indicators and early warning signs
   - Potential cascade effects

2. ROOT CAUSE ANALYSIS (CRITICAL - Be thorough):
   - Underlying geopolitical factors driving this threat
   - Economic factors contributing to instability
   - Social/demographic factors at play
   - Historical grievances or unresolved disputes
   - External actors and their interests
   - Resource competition aspects
   - Ideological or religious dimensions

3. PREDICTIVE TREND ANALYSIS (NEW - Critical):
   - Project threat level trajectory over next 30, 60, 90 days
   - Identify key inflection points that could accelerate escalation
   - Model probability curves for different escalation scenarios
   - Factor in seasonal, political, and economic cycles
   - Provide data points for visualization (10 time periods)

4. COUNTER-STRATEGIES WITH AI SCENARIO MODELING:
   - For each strategy, simulate potential outcomes
   - Model effectiveness under different conditions
   - Estimate probability of success with confidence intervals
   - Identify potential failure modes and their likelihood
   - Recommend optimal timing for intervention

5. RED TEAM ASSESSMENT (NEW - Critical):
   - Challenge the primary threat assessment
   - Present alternative interpretations of the data
   - Identify blind spots and assumptions in the analysis
   - Propose "devil's advocate" scenarios
   - Rate confidence in the primary assessment vs alternatives
   - Highlight what could make the assessment wrong

6. INFORMATION CONFIDENCE SCORE:
   - Overall confidence in assessment (0-100)
   - Data quality score
   - Source reliability assessment
   - Key uncertainties and intelligence gaps

Identify 5-7 emerging threats with this comprehensive analysis.`,
        response_json_schema: {
          type: 'object',
          properties: {
            scan_timestamp: { type: 'string' },
            global_threat_index: { type: 'number' },
            threats: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  id: { type: 'number' },
                  name: { type: 'string' },
                  type: { type: 'string' },
                  region: { type: 'string' },
                  threat_level: { type: 'number' },
                  escalation_probability: { type: 'number' },
                  timeframe: { type: 'string' },
                  indicators: { type: 'array', items: { type: 'string' } },
                  early_warnings: { type: 'array', items: { type: 'string' } },
                  monitoring_priorities: { type: 'array', items: { type: 'string' } },
                  cascade_effects: { type: 'array', items: { type: 'string' } },
                  root_cause_analysis: {
                    type: 'object',
                    properties: {
                      geopolitical_factors: { type: 'array', items: { type: 'string' } },
                      economic_factors: { type: 'array', items: { type: 'string' } },
                      social_factors: { type: 'array', items: { type: 'string' } },
                      historical_grievances: { type: 'array', items: { type: 'string' } },
                      external_actors: { type: 'array', items: { type: 'object', properties: { actor: { type: 'string' }, interest: { type: 'string' } } } },
                      resource_competition: { type: 'string' },
                      ideological_dimensions: { type: 'string' },
                      summary: { type: 'string' }
                    }
                  },
                  predictive_trends: {
                    type: 'object',
                    properties: {
                      trend_summary: { type: 'string' },
                      projection_30_days: { type: 'number' },
                      projection_60_days: { type: 'number' },
                      projection_90_days: { type: 'number' },
                      trend_direction: { type: 'string' },
                      key_inflection_points: { type: 'array', items: { type: 'object', properties: { timeframe: { type: 'string' }, event: { type: 'string' }, impact: { type: 'string' } } } },
                      escalation_scenarios: { type: 'array', items: { type: 'object', properties: { scenario: { type: 'string' }, probability: { type: 'number' }, trigger: { type: 'string' } } } },
                      trend_data: { type: 'array', items: { type: 'object', properties: { period: { type: 'string' }, threat_level: { type: 'number' }, escalation_risk: { type: 'number' } } } }
                    }
                  },
                  counter_strategies: {
                    type: 'array',
                    items: {
                      type: 'object',
                      properties: {
                        strategy_type: { type: 'string' },
                        strategy_name: { type: 'string' },
                        description: { type: 'string' },
                        key_actions: { type: 'array', items: { type: 'string' } },
                        success_probability: { type: 'number' },
                        risks: { type: 'array', items: { type: 'string' } },
                        timeline: { type: 'string' },
                        resources_required: { type: 'string' },
                        scenario_modeling: {
                          type: 'object',
                          properties: {
                            best_case_outcome: { type: 'string' },
                            best_case_probability: { type: 'number' },
                            worst_case_outcome: { type: 'string' },
                            worst_case_probability: { type: 'number' },
                            most_likely_outcome: { type: 'string' },
                            most_likely_probability: { type: 'number' },
                            failure_modes: { type: 'array', items: { type: 'object', properties: { mode: { type: 'string' }, probability: { type: 'number' } } } },
                            optimal_timing: { type: 'string' }
                          }
                        }
                      }
                    }
                  },
                  red_team_assessment: {
                    type: 'object',
                    properties: {
                      primary_assessment_confidence: { type: 'number' },
                      challenge_summary: { type: 'string' },
                      alternative_interpretations: { type: 'array', items: { type: 'object', properties: { interpretation: { type: 'string' }, plausibility: { type: 'number' }, supporting_evidence: { type: 'string' } } } },
                      blind_spots: { type: 'array', items: { type: 'string' } },
                      key_assumptions: { type: 'array', items: { type: 'object', properties: { assumption: { type: 'string' }, confidence: { type: 'number' }, what_if_wrong: { type: 'string' } } } },
                      devils_advocate_scenarios: { type: 'array', items: { type: 'object', properties: { scenario: { type: 'string' }, probability: { type: 'number' }, implications: { type: 'string' } } } },
                      overall_assessment_reliability: { type: 'string' }
                    }
                  },
                  confidence_assessment: {
                    type: 'object',
                    properties: {
                      overall_confidence: { type: 'number' },
                      data_quality_score: { type: 'number' },
                      source_reliability: { type: 'string' },
                      key_uncertainties: { type: 'array', items: { type: 'string' } },
                      intelligence_gaps: { type: 'array', items: { type: 'string' } },
                      confidence_rationale: { type: 'string' }
                    }
                  }
                }
              }
            },
            summary: { type: 'string' }
          }
        },
        add_context_from_internet: true
      });

      clearInterval(progressInterval);
      setScanProgress(100);
      setIsScanning(false);
      return response;
    },
    onSuccess: (data) => {
      setThreats(data);
      if (data.threats?.length > 0) {
        setSelectedThreat(data.threats[0]);
      }
      if (onThreatDetected) {
        onThreatDetected(data.threats);
      }
    }
