import React, { useEffect, useState, useRef } from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { toast } from 'sonner';
import { AlertTriangle, Bell, Activity, DollarSign, Users } from 'lucide-react';

export default function AlertNotificationSystem() {
  const lastThresholdCheck = useRef({});
  const [currentMetrics, setCurrentMetrics] = useState({
    threatLevel: 0,
    activeConflicts: 0,
    economicImpact: 0,
    casualties: 0
  });

  const { data: alerts } = useQuery({
    queryKey: ['active-alerts'],
    queryFn: async () => {
      try {
        const user = await base44.auth.me();
        return base44.entities.Alert.filter({ created_by: user.email, is_active: true });
      } catch {
        return [];
      }
    },
    initialData: [],
    refetchInterval: 60000
  });

  const { data: currentWars } = useQuery({
    queryKey: ['wars', 'current'],
    queryFn: () => base44.entities.War.filter({ era: 'current', status: 'ongoing' }),
    initialData: [],
    refetchInterval: 60000
  });

  const { data: userProfile } = useQuery({
    queryKey: ['userProfile-alerts'],
    queryFn: async () => {
      try {
        const user = await base44.auth.me();
        const profiles = await base44.entities.UserProfile.filter({ created_by: user.email });
        return profiles[0] || null;
      } catch {
        return null;
      }
    },
    initialData: null,
    refetchInterval: 60000
  });

  // Simulate current metrics (in production, these would come from real data feeds)
  useEffect(() => {
    const updateMetrics = () => {
      setCurrentMetrics({
        threatLevel: 50 + Math.random() * 40,
        activeConflicts: currentWars.length || Math.floor(8 + Math.random() * 8),
        economicImpact: 150 + Math.random() * 100,
        casualties: 8000 + Math.random() * 10000
      });
    };

    updateMetrics();
    const interval = setInterval(updateMetrics, 30000);
    return () => clearInterval(interval);
  }, [currentWars.length]);

  // Check dashboard alert thresholds
  useEffect(() => {
    const thresholds = userProfile?.dashboard_alert_thresholds;
    if (!thresholds?.enabled) return;

    const now = Date.now();
    const COOLDOWN = 300000; // 5 minute cooldown between same alerts

    // Threat Level Check
    if (thresholds.threat_level_threshold && currentMetrics.threatLevel >= thresholds.threat_level_threshold) {
      if (!lastThresholdCheck.current.threatLevel || now - lastThresholdCheck.current.threatLevel > COOLDOWN) {
        lastThresholdCheck.current.threatLevel = now;
        toast.error(
          <div className="flex items-start gap-2">
            <Activity className="w-5 h-5 text-red-400 flex-shrink-0 mt-0.5" />
            <div>
              <div className="font-bold text-sm">Threat Level Threshold Exceeded</div>
              <div className="text-xs mt-1">Current: {currentMetrics.threatLevel.toFixed(0)}%</div>
              <div className="text-xs text-slate-400 mt-1">Threshold: {thresholds.threat_level_threshold}%</div>
            </div>
          </div>,
          { duration: 10000, position: 'top-right' }
        );
      }
    }

    // Active Conflicts Check
    if (thresholds.active_conflicts_threshold && currentMetrics.activeConflicts >= thresholds.active_conflicts_threshold) {
      if (!lastThresholdCheck.current.activeConflicts || now - lastThresholdCheck.current.activeConflicts > COOLDOWN) {
        lastThresholdCheck.current.activeConflicts = now;
        toast.warning(
          <div className="flex items-start gap-2">
            <AlertTriangle className="w-5 h-5 text-orange-400 flex-shrink-0 mt-0.5" />
            <div>
              <div className="font-bold text-sm">Active Conflicts Threshold Exceeded</div>
              <div className="text-xs mt-1">Current: {currentMetrics.activeConflicts} conflicts</div>
              <div className="text-xs text-slate-400 mt-1">Threshold: {thresholds.active_conflicts_threshold}</div>
            </div>
          </div>,
          { duration: 10000, position: 'top-right' }
        );
      }
    }

    // Economic Impact Check
    if (thresholds.economic_impact_threshold && currentMetrics.economicImpact >= thresholds.economic_impact_threshold) {
      if (!lastThresholdCheck.current.economicImpact || now - lastThresholdCheck.current.economicImpact > COOLDOWN) {
        lastThresholdCheck.current.economicImpact = now;
        toast.warning(
          <div className="flex items-start gap-2">
            <DollarSign className="w-5 h-5 text-yellow-400 flex-shrink-0 mt-0.5" />
            <div>
              <div className="font-bold text-sm">Economic Impact Threshold Exceeded</div>
              <div className="text-xs mt-1">Current: ${currentMetrics.economicImpact.toFixed(1)}B</div>
              <div className="text-xs text-slate-400 mt-1">Threshold: ${thresholds.economic_impact_threshold}B</div>
            </div>
          </div>,
          { duration: 10000, position: 'top-right' }
        );
      }
    }

    // Casualty Check
    if (thresholds.casualty_threshold && currentMetrics.casualties >= thresholds.casualty_threshold) {
      if (!lastThresholdCheck.current.casualties || now - lastThresholdCheck.current.casualties > COOLDOWN) {
        lastThresholdCheck.current.casualties = now;
        toast.error(
          <div className="flex items-start gap-2">
            <Users className="w-5 h-5 text-purple-400 flex-shrink-0 mt-0.5" />
            <div>
              <div className="font-bold text-sm">Casualty Threshold Exceeded</div>
              <div className="text-xs mt-1">Current: {(currentMetrics.casualties / 1000).toFixed(1)}K</div>
              <div className="text-xs text-slate-400 mt-1">Threshold: {(thresholds.casualty_threshold / 1000).toFixed(0)}K</div>
            </div>
          </div>,
          { duration: 10000, position: 'top-right' }
        );
      }
    }
  }, [currentMetrics, userProfile?.dashboard_alert_thresholds]);

  // Original alert checking logic
  useEffect(() => {
    if (!alerts.length || !currentWars.length) return;

    alerts.forEach(alert => {
      const matchingWars = currentWars.filter(war => {
        const regionMatch = !alert.regions?.length || 
          alert.regions.some(region => war.name?.toLowerCase().includes(region.toLowerCase()));

        const typeMatch = !alert.conflict_types?.length || 
          alert.conflict_types.includes(war.type);

        const probabilityMatch = !alert.probability_threshold || 
          (war.probability || 100) >= alert.probability_threshold;

        return regionMatch && typeMatch && probabilityMatch;
      });

      if (matchingWars.length > 0) {
        matchingWars.forEach(war => {
          if (alert.notification_methods?.includes('in_app')) {
            toast.warning(
              <div className="flex items-start gap-2">
                <AlertTriangle className="w-5 h-5 text-orange-400 flex-shrink-0 mt-0.5" />
                <div>
                  <div className="font-bold text-sm">{alert.alert_name}</div>
                  <div className="text-xs mt-1">{war.name}</div>
                  <div className="text-xs text-slate-400 mt-1">
                    Type: {war.type} • Severity: {alert.severity_threshold}
                  </div>
                </div>
              </div>,
              {
                duration: 8000,
                position: 'top-right'
              }
            );
          }

          if (alert.notification_methods?.includes('email')) {
            base44.integrations.Core.SendEmail({
              to: alert.created_by,
              subject: `Alert Triggered: ${alert.alert_name}`,
              body: `Your custom alert "${alert.alert_name}" has been triggered.\n\nConflict: ${war.name}\nType: ${war.type}\nDescription: ${war.description}\n\nView details in War Matrix: ${window.location.origin}`
            }).catch(() => {});
          }
        });

        base44.entities.Alert.update(alert.id, {
          trigger_count: (alert.trigger_count || 0) + matchingWars.length,
          last_triggered: new Date().toISOString()
        }).catch(() => {});
      }
    });
  }, [alerts, currentWars]);

  return null;
}

src/components/alerts/NaturalLanguageAle:
import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { 
  Bell, Loader2, Sparkles, Plus, Trash2, Check,
  AlertTriangle, Brain, ChevronRight, Zap
} from 'lucide-react';
import { toast } from 'sonner';

export default function NaturalLanguageAlertBuilder() {
  const queryClient = useQueryClient();
  const [naturalLanguageQuery, setNaturalLanguageQuery] = useState('');
  const [parsedRule, setParsedRule] = useState(null);
  const [savedRules, setSavedRules] = useState(() => {
    const saved = localStorage.getItem('warMatrixNLAlertRules');
    return saved ? JSON.parse(saved) : [];
  });

  const { data: user } = useQuery({
    queryKey: ['currentUser'],
    queryFn: () => base44.auth.me(),
  });

  const parseNaturalLanguageMutation = useMutation({
    mutationFn: async (query) => {
      const response = await base44.integrations.Core.InvokeLLM({
        prompt: `You are an alert rule parser. Convert the following natural language alert request into a structured alert rule.

USER REQUEST: "${query}"

Parse this into a structured alert rule with:
1. Conditions (what triggers the alert)
2. Thresholds (numeric values)
3. Regions/entities to monitor
4. Logical operators (AND/OR)
5. Alert priority
6. Suggested notification methods

Examples of valid inputs:
- "Alert me if threat level in Middle East exceeds 80%"
- "Notify when economic instability > 70 AND military buildup detected"
- "Watch for conflicts in Asia with confidence below 60%"
- "Alert on any critical threats in Europe or Africa"`,
        response_json_schema: {
          type: 'object',
          properties: {
            rule_name: { type: 'string' },
            natural_language_summary: { type: 'string' },
            conditions: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  metric: { type: 'string' },
                  operator: { type: 'string' },
                  value: { type: 'number' },
                  region: { type: 'string' },
                  entity_type: { type: 'string' }
                }
              }
            },
            logic_operator: { type: 'string' },
            priority: { type: 'string' },
            suggested_actions: { type: 'array', items: { type: 'string' } },
            notification_methods: { type: 'array', items: { type: 'string' } },
            is_valid: { type: 'boolean' },
            validation_notes: { type: 'string' }
          }
        }
      });

      return response;
    },
    onSuccess: (data) => {
      setParsedRule(data);
      if (data.is_valid) {
        toast.success('Alert rule parsed successfully');
      } else {
        toast.warning('Rule parsed with warnings - please review');
      }
    }
  });

  const saveRule = () => {
    if (!parsedRule) return;

    const newRule = {
      id: Date.now().toString(),
      ...parsedRule,
      originalQuery: naturalLanguageQuery,
      is_active: true,
      created_at: new Date().toISOString(),
      trigger_count: 0
    };

    const updated = [...savedRules, newRule];
    setSavedRules(updated);
    localStorage.setItem('warMatrixNLAlertRules', JSON.stringify(updated));

    setNaturalLanguageQuery('');
    setParsedRule(null);
    toast.success('Alert rule saved');
  };

  const deleteRule = (ruleId) => {
    const updated = savedRules.filter(r => r.id !== ruleId);
    setSavedRules(updated);
    localStorage.setItem('warMatrixNLAlertRules', JSON.stringify(updated));
    toast.success('Rule deleted');
  };

  const toggleRule = (ruleId) => {
    const updated = savedRules.map(r => 
      r.id === ruleId ? { ...r, is_active: !r.is_active } : r
    );
    setSavedRules(updated);
    localStorage.setItem('warMatrixNLAlertRules', JSON.stringify(updated));
  };

  const getOperatorSymbol = (op) => {
    const symbols = {
      'greater_than': '>',
      'less_than': '<',
      'equals': '=',
      'greater_than_or_equal': '≥',
      'less_than_or_equal': '≤',
      'not_equals': '≠'
    };
    return symbols[op] || op;
  };

  const getPriorityColor = (priority) => {
    const colors = {
      'CRITICAL': 'bg-red-500/20 text-red-400 border-red-500/30',
      'HIGH': 'bg-orange-500/20 text-orange-400 border-orange-500/30',
      'MEDIUM': 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
      'LOW': 'bg-green-500/20 text-green-400 border-green-500/30'
    };
    return colors[priority] || 'bg-slate-500/20 text-slate-400 border-slate-500/30';
  };

  const exampleQueries = [
    "Alert me if threat level in Middle East exceeds 80%",
    "Notify when any conflict has escalation probability above 70%",
    "Watch for economic instability greater than 60 in Asia",
    "Alert on military buildups in Eastern Europe with high confidence",
    "Monitor refugee flows exceeding 100,000 in any region"
  ];

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl border border-sky-900/40 p-6">
      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 rounded-lg bg-purple-500/20 border border-purple-500/30">
          <Brain className="w-6 h-6 text-purple-400" />
        </div>
        <div>
          <h3 className="text-xl font-bold text-purple-400 glow-text font-mono">
            NATURAL LANGUAGE ALERT BUILDER
          </h3>
          <p className="text-xs text-slate-400 font-mono">Create alerts using plain English</p>
        </div>
      </div>

      <div className="space-y-4">
        {/* Natural Language Input */}
        <div>
          <label className="text-purple-400 font-mono text-xs mb-1 block">DESCRIBE YOUR ALERT</label>
          <Textarea
            value={naturalLanguageQuery}
            onChange={(e) => setNaturalLanguageQuery(e.target.value)}
            placeholder="e.g., Alert me if threat level in Middle East exceeds 80% AND AI confidence is below 60%"
            className="bg-slate-900/50 border-purple-500/30 text-slate-200 font-mono h-20"
          />
        </div>

        {/* Example Queries */}
        <div>
          <div className="text-xs text-slate-500 font-mono mb-2">EXAMPLES (click to use)</div>
          <div className="flex flex-wrap gap-2">
            {exampleQueries.map((query, i) => (
              <Button
                key={i}
                size="sm"
                variant="outline"
                onClick={() => setNaturalLanguageQuery(query)}
                className="border-purple-500/30 text-purple-400 hover:bg-purple-500/10 font-mono text-[10px]"
              >
                {query.slice(0, 40)}...
              </Button>
            ))}
          </div>
        </div>

        <Button
          onClick={() => parseNaturalLanguageMutation.mutate(naturalLanguageQuery)}
          disabled={parseNaturalLanguageMutation.isPending || !naturalLanguageQuery.trim()}
          className="w-full bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white font-mono"
        >
          {parseNaturalLanguageMutation.isPending ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              PARSING...
            </>
          ) : (
            <>
              <Sparkles className="w-4 h-4 mr-2" />
              PARSE ALERT RULE
            </>
          )}
        </Button>

        {/* Parsed Rule Preview */}
        {parsedRule && (
          <Card className="bg-purple-500/10 border border-purple-500/30 p-4 space-y-4">
            <div className="flex items-start justify-between">
              <div>
                <h4 className="text-lg font-bold text-purple-400 font-mono">{parsedRule.rule_name}</h4>
                <p className="text-slate-400 font-mono text-xs">{parsedRule.natural_language_summary}</p>
              </div>
              <Badge className={getPriorityColor(parsedRule.priority)}>
                {parsedRule.priority}
              </Badge>
            </div>

            {/* Conditions */}
            <div>
              <div className="text-xs text-purple-400 font-mono mb-2">CONDITIONS</div>
              <div className="space-y-2">
                {parsedRule.conditions?.map((cond, i) => (
                  <div key={i} className="flex items-center gap-2">
                    {i > 0 && (
                      <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 font-mono text-[10px]">
                        {parsedRule.logic_operator}
                      </Badge>
                    )}
                    <div className="bg-slate-800/50 rounded px-3 py-2 flex items-center gap-2">
                      <span className="text-slate-400 font-mono text-xs">{cond.metric}</span>
                      <span className="text-purple-400 font-mono font-bold">{getOperatorSymbol(cond.operator)}</span>
                      <span className="text-green-400 font-mono text-xs">{cond.value}</span>
                      {cond.region && (
                        <Badge variant="outline" className="border-slate-500/30 text-slate-400 font-mono text-[10px]">
                          {cond.region}
                        </Badge>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Validation */}
            <div className={`rounded p-3 ${parsedRule.is_valid ? 'bg-green-500/10 border border-green-500/30' : 'bg-yellow-500/10 border border-yellow-500/30'}`}>
              <div className="flex items-center gap-2">
                {parsedRule.is_valid ? (
                  <Check className="w-4 h-4 text-green-400" />
                ) : (
                  <AlertTriangle className="w-4 h-4 text-yellow-400" />
                )}
                <span className={`font-mono text-xs ${parsedRule.is_valid ? 'text-green-400' : 'text-yellow-400'}`}>
                  {parsedRule.validation_notes}
                </span>
              </div>
            </div>

            {/* Notification Methods */}
            {parsedRule.notification_methods?.length > 0 && (
              <div>
                <div className="text-xs text-slate-500 font-mono mb-1">NOTIFICATION METHODS</div>
                <div className="flex gap-2">
                  {parsedRule.notification_methods.map((method, i) => (
                    <Badge key={i} className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 font-mono text-xs">
                      {method}
                    </Badge>
                  ))}
                </div>
              </div>
            )}

            <Button
              onClick={saveRule}
              className="w-full bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-600 hover:to-emerald-600 text-white font-mono"
            >
              <Plus className="w-4 h-4 mr-2" />
              SAVE ALERT RULE
            </Button>
          </Card>
        )}

        {/* Saved Rules */}
        {savedRules.length > 0 && (
          <div className="space-y-3">
            <h4 className="text-cyan-400 font-mono font-bold text-sm">SAVED ALERT RULES ({savedRules.length})</h4>
            {savedRules.map((rule) => (
              <div
                key={rule.id}
                className={`bg-slate-900/50 border rounded-lg p-4 ${
                  rule.is_active ? 'border-cyan-500/30' : 'border-slate-700/30 opacity-60'
                }`}
              >
                <div className="flex items-start justify-between">
                  <div>
                    <div className="flex items-center gap-2">
                      <h5 className="text-green-400 font-mono font-bold text-sm">{rule.rule_name}</h5>
                      <Badge className={getPriorityColor(rule.priority)}>
                        {rule.priority}
                      </Badge>
                    </div>
                    <p className="text-slate-500 font-mono text-xs mt-1">{rule.originalQuery}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <Switch
                      checked={rule.is_active}
                      onCheckedChange={() => toggleRule(rule.id)}
                    />
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => deleteRule(rule.id)}
                      className="text-red-400 hover:text-red-300 hover:bg-red-500/10"
                    >
                      <Trash2 className="w-3 h-3" />
                    </Button>
                  </div>
                </div>

                <div className="mt-3 flex flex-wrap gap-1">
                  {rule.conditions?.map((cond, i) => (
                    <Badge key={i} variant="outline" className="border-purple-500/30 text-purple-400 font-mono text-[10px]">
                      {cond.metric} {getOperatorSymbol(cond.operator)} {cond.value}
                    </Badge>
                  ))}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </Card>
  );
}

src/components/alerts/RecentAlertsWidget:
import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { base44 } from '@/api/base44Client';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Bell, AlertTriangle } from 'lucide-react';
import { Link } from 'react-router-dom';
import { createPageUrl } from '@/utils';

export default function RecentAlertsWidget({ limit = 5 }) {
  const { data: alerts } = useQuery({
    queryKey: ['recent-alerts'],
    queryFn: async () => {
      const allAlerts = await base44.entities.Alert.list('-updated_date', limit * 2);
      return allAlerts.filter(a => a.is_active && (a.trigger_count || 0) > 0).slice(0, limit);
    },
    initialData: [],
    refetchInterval: 30000
  });

  const getSeverityColor = (severity) => {
    const colors = {
      low: 'bg-green-500/20 text-green-400 border-green-500/30',
      medium: 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30',
      high: 'bg-orange-500/20 text-orange-400 border-orange-500/30',
      critical: 'bg-red-500/20 text-red-400 border-red-500/30'
    };
    return colors[severity] || colors.medium;
  };

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-2">
          <Bell className="w-5 h-5 text-cyan-400 animate-pulse" />
          <h3 className="text-lg font-bold text-cyan-400 font-mono">RECENT ALERTS</h3>
        </div>
        <Link 
          to={createPageUrl('AlertsManagement')}
          className="text-xs text-cyan-400 hover:text-cyan-300 font-mono"
        >
          MANAGE →
        </Link>
      </div>

      {alerts.length === 0 ? (
        <div className="text-center py-4">
          <AlertTriangle className="w-8 h-8 text-slate-600 mx-auto mb-2" />
          <p className="text-slate-400 font-mono text-xs">No recent alerts triggered</p>
        </div>
      ) : (
        <div className="space-y-2">
          {alerts.map((alert) => (
            <div 
              key={alert.id} 
              className="bg-slate-900/50 cyber-border rounded p-3 hover:bg-slate-900/70 transition-colors"
            >
              <div className="flex items-start justify-between mb-1">
                <h4 className="text-sm font-bold text-green-400 font-mono">{alert.alert_name}</h4>
                <Badge className={`${getSeverityColor(alert.severity_threshold)} font-mono text-xs`}>
                  {alert.severity_threshold}
                </Badge>
              </div>
              <div className="text-xs text-slate-400 font-mono">
                Triggered: {alert.trigger_count || 0}x
              </div>
              {alert.last_triggered && (
                <div className="text-xs text-slate-500 font-mono mt-1">
                  Last: {new Date(alert.last_triggered).toLocaleString()}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

src/components/alerts/VisualAlertRuleBui:
import React, { useState } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Slider } from '@/components/ui/slider';
import { Badge } from '@/components/ui/badge';
import { Plus, X, Trash2, GitBranch, Zap } from 'lucide-react';

export default function VisualAlertRuleBuilder({ onSave }) {
  const [ruleName, setRuleName] = useState('');
  const [conditions, setConditions] = useState([{
    id: 1,
    type: 'region',
    operator: 'equals',
    value: '',
    weight: 50
  }]);
  const [logic, setLogic] = useState('AND'); // AND or OR
  const [notificationMethods, setNotificationMethods] = useState(['in_app']);

  const conditionTypes = [
    { value: 'region', label: 'Region' },
    { value: 'conflict_type', label: 'Conflict Type' },
    { value: 'probability', label: 'Probability' },
    { value: 'severity', label: 'Severity Level' },
    { value: 'keyword', label: 'Keyword Mention' },
    { value: 'casualties', label: 'Casualty Count' },
    { value: 'economic_impact', label: 'Economic Impact' }
  ];

  const operators = {
    region: ['equals', 'contains'],
    conflict_type: ['equals', 'contains'],
    probability: ['greater_than', 'less_than', 'equals'],
    severity: ['equals', 'greater_than_or_equal'],
    keyword: ['contains', 'equals'],
    casualties: ['greater_than', 'less_than'],
    economic_impact: ['greater_than', 'less_than']
  };

  const addCondition = () => {
    setConditions([...conditions, {
      id: Date.now(),
      type: 'region',
      operator: 'equals',
      value: '',
      weight: 50
    }]);
  };

  const removeCondition = (id) => {
    if (conditions.length > 1) {
      setConditions(conditions.filter(c => c.id !== id));
    }
  };

  const updateCondition = (id, field, value) => {
    setConditions(conditions.map(c => 
      c.id === id ? { ...c, [field]: value } : c
    ));
  };

  const calculateTotalScore = () => {
    return conditions.reduce((sum, c) => sum + c.weight, 0);
  };

  const handleSave = () => {
    const rule = {
      name: ruleName,
      conditions,
      logic,
      notification_methods: notificationMethods,
      total_score: calculateTotalScore()
    };
    onSave(rule);
  };

  const getWeightColor = (weight) => {
    if (weight >= 70) return 'text-red-400';
    if (weight >= 40) return 'text-yellow-400';
    return 'text-green-400';
  };

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-center gap-3 mb-6">
        <GitBranch className="w-6 h-6 text-cyan-400" />
        <h3 className="text-xl font-bold text-cyan-400 glow-text font-mono">
          VISUAL ALERT RULE BUILDER
        </h3>
      </div>

      <div className="space-y-6">
        {/* Rule Name */}
        <div className="space-y-2">
          <Label className="text-cyan-400 font-mono">Alert Rule Name</Label>
          <Input
            value={ruleName}
            onChange={(e) => setRuleName(e.target.value)}
            placeholder="e.g., High-Risk Middle East Escalation"
            className="bg-slate-900/50 border-green-500/30 text-green-400 font-mono"
          />
        </div>

        {/* Logic Selector */}
        <div className="space-y-2">
          <Label className="text-cyan-400 font-mono">Condition Logic</Label>
          <div className="flex gap-2">
            <Button
              variant={logic === 'AND' ? 'default' : 'outline'}
              onClick={() => setLogic('AND')}
              className={logic === 'AND' ? 'bg-purple-500/20 text-purple-400 border-purple-500/30' : ''}
            >
              ALL Conditions (AND)
            </Button>
            <Button
              variant={logic === 'OR' ? 'default' : 'outline'}
              onClick={() => setLogic('OR')}
              className={logic === 'OR' ? 'bg-blue-500/20 text-blue-400 border-blue-500/30' : ''}
            >
              ANY Condition (OR)
            </Button>
          </div>
        </div>

        {/* Conditions Builder */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <Label className="text-cyan-400 font-mono">Conditions & Weights</Label>
            <Badge className="bg-purple-500/20 text-purple-400 border-purple-500/30 font-mono">
              Total Score: {calculateTotalScore()}
            </Badge>
          </div>

          {conditions.map((condition, idx) => (
            <div key={condition.id} className="relative">
              {idx > 0 && (
                <div className="absolute -top-3 left-4 bg-slate-950 px-2">
                  <Badge 
                    variant="outline" 
                    className={`text-xs font-mono ${logic === 'AND' ? 'border-purple-500/30 text-purple-400' : 'border-blue-500/30 text-blue-400'}`}
                  >
                    {logic}
                  </Badge>
                </div>
              )}

              <Card className="bg-slate-900/50 cyber-border p-4">
                <div className="grid md:grid-cols-4 gap-3 mb-3">
                  <div className="space-y-2">
                    <Label className="text-xs text-slate-400 font-mono">Condition Type</Label>
                    <Select
                      value={condition.type}
                      onValueChange={(value) => updateCondition(condition.id, 'type', value)}
                    >
                      <SelectTrigger className="bg-slate-950 border-cyan-500/30 text-green-400 font-mono text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="bg-slate-900 border-cyan-500/30">
                        {conditionTypes.map(type => (
                          <SelectItem key={type.value} value={type.value} className="text-green-400 font-mono">
                            {type.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label className="text-xs text-slate-400 font-mono">Operator</Label>
                    <Select
                      value={condition.operator}
                      onValueChange={(value) => updateCondition(condition.id, 'operator', value)}
                    >
                      <SelectTrigger className="bg-slate-950 border-cyan-500/30 text-green-400 font-mono text-xs">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent className="bg-slate-900 border-cyan-500/30">
                        {operators[condition.type]?.map(op => (
                          <SelectItem key={op} value={op} className="text-green-400 font-mono">
                            {op.replace('_', ' ')}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label className="text-xs text-slate-400 font-mono">Value</Label>
                    <Input
                      value={condition.value}
                      onChange={(e) => updateCondition(condition.id, 'value', e.target.value)}
                      placeholder="Enter value..."
                      className="bg-slate-950 border-cyan-500/30 text-green-400 font-mono text-xs"
                    />
                  </div>

                  <div className="flex items-end">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => removeCondition(condition.id)}
                      disabled={conditions.length === 1}
                      className="w-full border-red-500/30 text-red-400 hover:bg-red-500/10"
                    >
                      <Trash2 className="w-4 h-4" />
                    </Button>
                  </div>
                </div>

                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <Label className="text-xs text-slate-400 font-mono">Priority Weight</Label>
                    <span className={`text-sm font-bold font-mono ${getWeightColor(condition.weight)}`}>
                      {condition.weight}
                    </span>
                  </div>
                  <Slider
                    value={[condition.weight]}
                    onValueChange={(value) => updateCondition(condition.id, 'weight', value[0])}
                    min={0}
                    max={100}
                    step={5}
                    className="cursor-pointer"
                  />
                  <div className="flex justify-between text-xs text-slate-500 font-mono">
                    <span>Low Priority</span>
                    <span>High Priority</span>
                  </div>
                </div>
              </Card>
            </div>
          ))}

          <Button
            onClick={addCondition}
            variant="outline"
            className="w-full border-green-500/30 text-green-400 hover:bg-green-500/10 font-mono"
          >
            <Plus className="w-4 h-4 mr-2" />
            Add Condition
          </Button>
        </div>

        {/* Notification Methods */}
        <div className="space-y-2">
          <Label className="text-cyan-400 font-mono">Notification Methods</Label>
          <div className="flex gap-2">
            {['in_app', 'email'].map(method => (
              <Button
                key={method}
                variant={notificationMethods.includes(method) ? 'default' : 'outline'}
                onClick={() => {
                  if (notificationMethods.includes(method)) {
                    setNotificationMethods(notificationMethods.filter(m => m !== method));
                  } else {
                    setNotificationMethods([...notificationMethods, method]);
                  }
                }}
                className={notificationMethods.includes(method) ? 'bg-cyan-500/20 text-cyan-400 border-cyan-500/30' : ''}
              >
                {method === 'in_app' ? 'In-App' : 'Email'}
              </Button>
            ))}
          </div>
        </div>

        {/* Visual Flow Preview */}
        <Card className="bg-slate-900/50 cyber-border p-4">
          <Label className="text-yellow-400 font-mono text-xs mb-3 block">RULE FLOW PREVIEW</Label>
          <div className="space-y-2">
            {conditions.map((condition, idx) => (
              <div key={condition.id} className="flex items-center gap-2 text-xs font-mono">
                <Badge variant="outline" className="border-cyan-500/30 text-cyan-400">
                  {condition.type}
                </Badge>
                <span className="text-slate-400">{condition.operator}</span>
                <Badge variant="outline" className="border-green-500/30 text-green-400">
                  {condition.value || '???'}
                </Badge>
                <span className={`ml-auto ${getWeightColor(condition.weight)}`}>
                  Weight: {condition.weight}
                </span>
                {idx < conditions.length - 1 && (
                  <Badge className={`${logic === 'AND' ? 'bg-purple-500/20 text-purple-400' : 'bg-blue-500/20 text-blue-400'}`}>
                    {logic}
                  </Badge>
                )}
              </div>
            ))}
          </div>
        </Card>

        {/* Save Button */}
        <Button
          onClick={handleSave}
          disabled={!ruleName || conditions.some(c => !c.value)}
          className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-mono text-lg py-6"
        >
          <Zap className="w-5 h-5 mr-2" />
          SAVE ALERT RULE
        </Button>
      </div>
    </Card>
  );
}

src/components/analysis/AdvancedAnalysis:
import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Slider } from '@/components/ui/slider';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';
import { Brain, TrendingUp, AlertTriangle, Zap, FileText, Loader2, Bell, Activity } from 'lucide-react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import TrendForecastingModule from './TrendForecastingModule';
import WhatIfScenarioBuilder from './WhatIfScenarioBuilder';
import KeyEventPredictor from './KeyEventPredictor';

export default function AdvancedAnalysisSection() {
  const [activeTab, setActiveTab] = useState('escalation');
  const [escalationParams, setEscalationParams] = useState({
    region: '',
    timeframe: 30,
    factors: '',
    sensitivity: 50
  });
  const [anomalyParams, setAnomalyParams] = useState({
    dataSource: 'news',
    threshold: 70,
    lookbackDays: 7
  });
  const [simulationParams, setSimulationParams] = useState({
    scenario: '',
    variables: '',
    iterations: 100
  });
  const [results, setResults] = useState({
    escalation: null,
    anomaly: null,
    simulation: null
  });

  const escalationMutation = useMutation({
    mutationFn: async () => {
      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `You are an advanced AI predictive model for conflict escalation. Analyze and predict conflict escalation patterns.

PARAMETERS:
- Region: ${escalationParams.region || 'Global'}
- Timeframe: ${escalationParams.timeframe} days
- Key Factors: ${escalationParams.factors || 'All factors'}
- Sensitivity: ${escalationParams.sensitivity}/100

Provide comprehensive escalation prediction including:
1. Escalation probability curve over time
2. Key trigger events that could accelerate escalation
3. De-escalation opportunities and windows
4. Confidence intervals for predictions
5. Similar historical escalation patterns
6. Risk factors ranked by impact`,
        response_json_schema: {
          type: "object",
          properties: {
            overall_probability: { type: "number" },
            confidence_level: { type: "number" },
            escalation_timeline: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  day: { type: "number" },
                  probability: { type: "number" },
                  confidence_low: { type: "number" },
                  confidence_high: { type: "number" }
                }
              }
            },
            trigger_events: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  event: { type: "string" },
                  impact_score: { type: "number" },
                  timeframe: { type: "string" }
                }
              }
            },
            deescalation_windows: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  period: { type: "string" },
                  opportunity: { type: "string" },
                  success_probability: { type: "number" }
                }
              }
            },
            risk_factors: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  factor: { type: "string" },
                  impact: { type: "number" },
                  trend: { type: "string" }
                }
              }
            },
            recommendations: { type: "array", items: { type: "string" } }
          }
        },
        add_context_from_internet: true
      });
      setResults(prev => ({ ...prev, escalation: result }));
      return result;
    }
  });

  const anomalyMutation = useMutation({
    mutationFn: async () => {
      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `You are an AI anomaly detection system for geopolitical events. Detect unusual patterns and anomalies.

PARAMETERS:
- Data Source: ${anomalyParams.dataSource}
- Detection Threshold: ${anomalyParams.threshold}%
- Lookback Period: ${anomalyParams.lookbackDays} days

Identify and analyze anomalies including:
1. Statistical deviations from normal patterns
2. Unusual activity clusters
3. Breaking patterns vs historical norms
4. Potential causes of anomalies
5. Severity and urgency assessment
6. Recommended immediate actions`,
        response_json_schema: {
          type: "object",
          properties: {
            anomalies_detected: { type: "number" },
            severity_distribution: {
              type: "object",
              properties: {
                critical: { type: "number" },
                high: { type: "number" },
                medium: { type: "number" },
                low: { type: "number" }
              }
            },
            detected_anomalies: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  type: { type: "string" },
                  description: { type: "string" },
                  severity: { type: "string" },
                  deviation_score: { type: "number" },
                  location: { type: "string" },
                  detected_at: { type: "string" },
                  potential_cause: { type: "string" }
                }
              }
            },
            pattern_analysis: { type: "string" },
            immediate_actions: { type: "array", items: { type: "string" } }
          }
        },
        add_context_from_internet: true
      });
      setResults(prev => ({ ...prev, anomaly: result }));
      return result;
    }
  });

  const simulationMutation = useMutation({
    mutationFn: async () => {
      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `You are an advanced scenario simulation AI. Run detailed what-if analysis.

SCENARIO:
${simulationParams.scenario}

VARIABLES TO TEST:
${simulationParams.variables}

NUMBER OF ITERATIONS: ${simulationParams.iterations}

Provide comprehensive simulation results including:
1. Outcome distribution across iterations
2. Most likely scenarios with probabilities
3. Best and worst case scenarios
4. Key decision points that alter outcomes
5. Sensitivity analysis for each variable
6. Strategic recommendations based on results`,
        response_json_schema: {
          type: "object",
          properties: {
            simulation_summary: { type: "string" },
            outcome_distribution: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  outcome: { type: "string" },
                  probability: { type: "number" },
                  iterations: { type: "number" }
                }
              }
            },
            scenarios: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  name: { type: "string" },
                  probability: { type: "number" },
                  description: { type: "string" },
                  impact_score: { type: "number" }
                }
              }
            },
            decision_points: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  decision: { type: "string" },
                  impact_on_outcome: { type: "string" },
                  optimal_choice: { type: "string" }
                }
              }
            },
            sensitivity_analysis: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  variable: { type: "string" },
                  sensitivity_score: { type: "number" },
                  effect: { type: "string" }
                }
              }
            },
            recommendations: { type: "array", items: { type: "string" } }
          }
        },
        add_context_from_internet: true
      });
      setResults(prev => ({ ...prev, simulation: result }));
      return result;
    }
  });

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-center gap-3 mb-6">
        <Brain className="w-8 h-8 text-purple-400" />
        <div>
          <h2 className="text-2xl font-bold text-purple-400 glow-text font-mono">
            ADVANCED AI ANALYSIS
          </h2>
          <p className="text-slate-400 text-sm font-mono mt-1">
            Predictive modeling • Anomaly detection • Scenario simulation
          </p>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid w-full grid-cols-6 bg-slate-950/80 border border-purple-500/30">
          <TabsTrigger value="escalation" className="data-[state=active]:bg-red-500/20 data-[state=active]:text-red-400 font-mono text-xs">
            <TrendingUp className="w-4 h-4 mr-1" />
            ESCALATION
          </TabsTrigger>
          <TabsTrigger value="anomaly" className="data-[state=active]:bg-orange-500/20 data-[state=active]:text-orange-400 font-mono text-xs">
            <AlertTriangle className="w-4 h-4 mr-1" />
            ANOMALY
          </TabsTrigger>
          <TabsTrigger value="simulation" className="data-[state=active]:bg-cyan-500/20 data-[state=active]:text-cyan-400 font-mono text-xs">
            <Zap className="w-4 h-4 mr-1" />
            SIMULATION
          </TabsTrigger>
          <TabsTrigger value="forecasting" className="data-[state=active]:bg-purple-500/20 data-[state=active]:text-purple-400 font-mono text-xs">
            <Activity className="w-4 h-4 mr-1" />
            FORECAST
          </TabsTrigger>
          <TabsTrigger value="whatif" className="data-[state=active]:bg-yellow-500/20 data-[state=active]:text-yellow-400 font-mono text-xs">
            <Zap className="w-4 h-4 mr-1" />
            WHAT-IF
          </TabsTrigger>
          <TabsTrigger value="predictor" className="data-[state=active]:bg-red-500/20 data-[state=active]:text-red-400 font-mono text-xs">
            <Bell className="w-4 h-4 mr-1" />
            PREDICTOR
          </TabsTrigger>
        </TabsList>

        <TabsContent value="escalation" className="mt-6 space-y-6">
          <Card className="bg-slate-900/50 cyber-border p-4">
            <h3 className="text-lg font-bold text-red-400 font-mono mb-4">ESCALATION PREDICTION</h3>
            <div className="space-y-4">
              <div>
                <Label className="text-slate-300 font-mono text-sm">Region/Conflict</Label>
                <Input
                  value={escalationParams.region}
                  onChange={(e) => setEscalationParams({ ...escalationParams, region: e.target.value })}
                  placeholder="e.g., Middle East, Ukraine"
                  className="bg-slate-950/50 border-red-500/30 text-red-400 font-mono"
                />
              </div>
              <div>
                <Label className="text-slate-300 font-mono text-sm">
                  Prediction Timeframe: {escalationParams.timeframe} days
                </Label>
                <Slider
                  value={[escalationParams.timeframe]}
                  onValueChange={(v) => setEscalationParams({ ...escalationParams, timeframe: v[0] })}
                  min={7}
                  max={180}
                  step={1}
                />
              </div>
              <div>
                <Label className="text-slate-300 font-mono text-sm">Key Factors to Consider</Label>
                <Textarea
                  value={escalationParams.factors}
                  onChange={(e) => setEscalationParams({ ...escalationParams, factors: e.target.value })}
                  placeholder="e.g., military build-up, diplomatic tensions, economic sanctions"
                  className="bg-slate-950/50 border-red-500/30 text-red-400 font-mono"
                />
              </div>
              <Button
                onClick={() => escalationMutation.mutate()}
                disabled={escalationMutation.isPending}
                className="w-full bg-gradient-to-r from-red-500 to-orange-500 hover:from-red-600 hover:to-orange-600 text-white font-mono"
              >
                {escalationMutation.isPending ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    ANALYZING...
                  </>
                ) : (
                  <>
                    <Brain className="w-4 h-4 mr-2" />
                    RUN PREDICTION
                  </>
                )}
              </Button>
            </div>
          </Card>

          {results.escalation && (
            <div className="space-y-4">
              <Card className="bg-gradient-to-br from-red-950/50 to-orange-950/50 cyber-border p-6">
                <div className="flex items-center justify-between mb-4">
                  <h4 className="text-xl font-bold text-red-400 font-mono">PREDICTION RESULTS</h4>
                  <Badge className="bg-red-500/20 text-red-400 border-red-500/30 font-mono">
                    {results.escalation.overall_probability}% PROBABILITY
                  </Badge>
                </div>
                <div className="h-[300px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <LineChart data={results.escalation.escalation_timeline}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                      <XAxis dataKey="day" stroke="#64748b" style={{ fontSize: '10px', fontFamily: 'monospace' }} />
                      <YAxis stroke="#64748b" style={{ fontSize: '10px', fontFamily: 'monospace' }} />
                      <Tooltip />
                      <Legend wrapperStyle={{ fontFamily: 'monospace', fontSize: '11px' }} />
                      <Line type="monotone" dataKey="probability" stroke="#ef4444" strokeWidth={2} name="Probability" />
                      <Line type="monotone" dataKey="confidence_high" stroke="#f97316" strokeWidth={1} strokeDasharray="5 5" name="Upper Bound" />
                      <Line type="monotone" dataKey="confidence_low" stroke="#fb923c" strokeWidth={1} strokeDasharray="5 5" name="Lower Bound" />
                    </LineChart>
                  </ResponsiveContainer>
                </div>
              </Card>

              <Card className="bg-slate-900/50 cyber-border p-6">
                <h4 className="text-lg font-bold text-orange-400 font-mono mb-4">TRIGGER EVENTS</h4>
                <div className="space-y-2">
                  {results.escalation.trigger_events?.map((event, idx) => (
                    <div key={idx} className="bg-slate-950/50 cyber-border rounded p-3">
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-yellow-400 font-mono text-sm font-bold">{event.event}</span>
                        <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/30 font-mono text-xs">
                          Impact: {event.impact_score}/100
                        </Badge>
                      </div>
                      <div className="text-xs text-slate-400 font-mono">Timeframe: {event.timeframe}</div>
                    </div>
                  ))}
                </div>
              </Card>

              <Card className="bg-slate-900/50 cyber-border p-6">
                <h4 className="text-lg font-bold text-green-400 font-mono mb-4">RECOMMENDATIONS</h4>
                <ul className="space-y-2">
                  {results.escalation.recommendations?.map((rec, idx) => (
                    <li key={idx} className="flex items-start gap-2 text-slate-300 font-mono text-sm">
                      <span className="text-green-400 font-bold">{idx + 1}.</span>
                      {rec}
                    </li>
                  ))}
                </ul>
              </Card>
            </div>
          )}
        </TabsContent>

        <TabsContent value="anomaly" className="mt-6 space-y-6">
          <Card className="bg-slate-900/50 cyber-border p-4">
            <h3 className="text-lg font-bold text-orange-400 font-mono mb-4">ANOMALY DETECTION</h3>
            <div className="space-y-4">
              <div>
                <Label className="text-slate-300 font-mono text-sm">Detection Threshold: {anomalyParams.threshold}%</Label>
                <Slider
                  value={[anomalyParams.threshold]}
                  onValueChange={(v) => setAnomalyParams({ ...anomalyParams, threshold: v[0] })}
                  min={50}
                  max={95}
                  step={5}
                />
              </div>
              <div>
                <Label className="text-slate-300 font-mono text-sm">Lookback Period: {anomalyParams.lookbackDays} days</Label>
                <Slider
                  value={[anomalyParams.lookbackDays]}
                  onValueChange={(v) => setAnomalyParams({ ...anomalyParams, lookbackDays: v[0] })}
                  min={1}
                  max={30}
                  step={1}
                />
              </div>
              <Button
                onClick={() => anomalyMutation.mutate()}
                disabled={anomalyMutation.isPending}
                className="w-full bg-gradient-to-r from-orange-500 to-yellow-500 hover:from-orange-600 hover:to-yellow-600 text-white font-mono"
              >
                {anomalyMutation.isPending ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    DETECTING...
                  </>
                ) : (
                  <>
                    <AlertTriangle className="w-4 h-4 mr-2" />
                    DETECT ANOMALIES
                  </>
                )}
              </Button>
            </div>
          </Card>

          {results.anomaly && (
            <div className="space-y-4">
              <Card className="bg-gradient-to-br from-orange-950/50 to-yellow-950/50 cyber-border p-6">
                <div className="flex items-center justify-between mb-4">
                  <h4 className="text-xl font-bold text-orange-400 font-mono">DETECTED ANOMALIES</h4>
                  <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/30 font-mono">
                    {results.anomaly.anomalies_detected} FOUND
                  </Badge>
                </div>
                <div className="space-y-3">
                  {results.anomaly.detected_anomalies?.map((anomaly, idx) => (
                    <div key={idx} className="bg-slate-950/50 cyber-border rounded p-4 border-l-4 border-orange-500">
                      <div className="flex items-start justify-between mb-2">
                        <h5 className="text-md font-bold text-yellow-400 font-mono">{anomaly.type}</h5>
                        <Badge className={`font-mono text-xs ${
                          anomaly.severity === 'critical' ? 'bg-red-500/20 text-red-400 border-red-500/30' :
                          anomaly.severity === 'high' ? 'bg-orange-500/20 text-orange-400 border-orange-500/30' :
                          'bg-yellow-500/20 text-yellow-400 border-yellow-500/30'
                        }`}>
                          {anomaly.severity.toUpperCase()}
                        </Badge>
                      </div>
                      <p className="text-slate-300 font-mono text-sm mb-2">{anomaly.description}</p>
                      <div className="grid grid-cols-2 gap-2 text-xs font-mono">
                        <div>
                          <span className="text-slate-500">Location:</span>
                          <span className="text-cyan-400 ml-1">{anomaly.location}</span>
                        </div>
                        <div>
                          <span className="text-slate-500">Deviation:</span>
                          <span className="text-red-400 ml-1">{anomaly.deviation_score}/100</span>
                        </div>
                      </div>
                      <div className="mt-2 pt-2 border-t border-slate-700/30">
                        <span className="text-xs text-slate-500 font-mono">Potential Cause: </span>
                        <span className="text-xs text-slate-300 font-mono">{anomaly.potential_cause}</span>
                      </div>
                    </div>
                  ))}
                </div>
              </Card>

              <Card className="bg-slate-900/50 cyber-border p-6">
                <h4 className="text-lg font-bold text-red-400 font-mono mb-4">IMMEDIATE ACTIONS</h4>
                <ul className="space-y-2">
                  {results.anomaly.immediate_actions?.map((action, idx) => (
                    <li key={idx} className="flex items-start gap-2 text-slate-300 font-mono text-sm">
                      <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
                      {action}
                    </li>
                  ))}
                </ul>
              </Card>
            </div>
          )}
        </TabsContent>

        <TabsContent value="simulation" className="mt-6 space-y-6">
          <Card className="bg-slate-900/50 cyber-border p-4">
            <h3 className="text-lg font-bold text-cyan-400 font-mono mb-4">SCENARIO SIMULATION</h3>
            <div className="space-y-4">
              <div>
                <Label className="text-slate-300 font-mono text-sm">Scenario Description</Label>
                <Textarea
                  value={simulationParams.scenario}
                  onChange={(e) => setSimulationParams({ ...simulationParams, scenario: e.target.value })}
                  placeholder="Describe the scenario to simulate..."
                  className="bg-slate-950/50 border-cyan-500/30 text-cyan-400 font-mono min-h-[100px]"
                />
              </div>
              <div>
                <Label className="text-slate-300 font-mono text-sm">Variables to Test</Label>
                <Textarea
                  value={simulationParams.variables}
                  onChange={(e) => setSimulationParams({ ...simulationParams, variables: e.target.value })}
                  placeholder="e.g., diplomatic pressure, economic sanctions, military response"
                  className="bg-slate-950/50 border-cyan-500/30 text-cyan-400 font-mono"
                />
              </div>
              <div>
                <Label className="text-slate-300 font-mono text-sm">
                  Iterations: {simulationParams.iterations}
                </Label>
                <Slider
                  value={[simulationParams.iterations]}
                  onValueChange={(v) => setSimulationParams({ ...simulationParams, iterations: v[0] })}
                  min={50}
                  max={1000}
                  step={50}
                />
              </div>
              <Button
                onClick={() => simulationMutation.mutate()}
                disabled={simulationMutation.isPending}
                className="w-full bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-mono"
              >
                {simulationMutation.isPending ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    SIMULATING...
                  </>
                ) : (
                  <>
                    <Zap className="w-4 h-4 mr-2" />
                    RUN SIMULATION
                  </>
                )}
              </Button>
            </div>
          </Card>

          {results.simulation && (
            <div className="space-y-4">
              <Card className="bg-gradient-to-br from-cyan-950/50 to-blue-950/50 cyber-border p-6">
                <h4 className="text-xl font-bold text-cyan-400 font-mono mb-4">SIMULATION RESULTS</h4>
                <p className="text-slate-300 font-mono text-sm mb-4">{results.simulation.simulation_summary}</p>
                <div className="h-[300px]">
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={results.simulation.outcome_distribution}>
                      <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                      <XAxis dataKey="outcome" stroke="#64748b" style={{ fontSize: '10px', fontFamily: 'monospace' }} />
                      <YAxis stroke="#64748b" style={{ fontSize: '10px', fontFamily: 'monospace' }} />
                      <Tooltip />
                      <Legend wrapperStyle={{ fontFamily: 'monospace', fontSize: '11px' }} />
                      <Bar dataKey="probability" fill="#06b6d4" name="Probability %" />
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              </Card>

              <Card className="bg-slate-900/50 cyber-border p-6">
                <h4 className="text-lg font-bold text-purple-400 font-mono mb-4">KEY SCENARIOS</h4>
                <div className="space-y-3">
                  {results.simulation.scenarios?.map((scenario, idx) => (
                    <div key={idx} className="bg-slate-950/50 cyber-border rounded p-4">
                      <div className="flex items-center justify-between mb-2">
                        <h5 className="text-md font-bold text-green-400 font-mono">{scenario.name}</h5>
                        <Badge className="bg-purple-500/20 text-purple-400 border-purple-500/30 font-mono">
                          {scenario.probability}%
                        </Badge>
                      </div>
                      <p className="text-slate-300 font-mono text-sm mb-2">{scenario.description}</p>
                      <div className="text-xs text-slate-400 font-mono">
                        Impact Score: <span className="text-orange-400">{scenario.impact_score}/100</span>
                      </div>
                    </div>
                  ))}
                </div>
              </Card>

              <Card className="bg-slate-900/50 cyber-border p-6">
                <h4 className="text-lg font-bold text-green-400 font-mono mb-4">STRATEGIC RECOMMENDATIONS</h4>
                <ul className="space-y-2">
                  {results.simulation.recommendations?.map((rec, idx) => (
                    <li key={idx} className="flex items-start gap-2 text-slate-300 font-mono text-sm">
                      <FileText className="w-4 h-4 text-green-400 flex-shrink-0 mt-0.5" />
                      {rec}
                    </li>
                  ))}
                </ul>
              </Card>
            </div>
          )}
        </TabsContent>

        {/* Trend Forecasting Tab */}
        <TabsContent value="forecasting" className="mt-6">
          <TrendForecastingModule />
        </TabsContent>

        {/* What-If Scenario Builder Tab */}
        <TabsContent value="whatif" className="mt-6">
          <WhatIfScenarioBuilder />
        </TabsContent>

        {/* Key Event Predictor Tab */}
        <TabsContent value="predictor" className="mt-6">
          <KeyEventPredictor />
        </TabsContent>
      </Tabs>
    </Card>
  );
}

src/components/analysis/ComparativeWarAn:
import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Loader2, TrendingUp, Users, DollarSign, Target, AlertTriangle } from 'lucide-react';
import { LineChart, Line, BarChart, Bar, ScatterChart, Scatter, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

export default function ComparativeWarAnalysis({ selectedWars }) {
  const [analysis, setAnalysis] = useState(null);

  const generateComparativeAnalysisMutation = useMutation({
    mutationFn: async () => {
      const warsData = selectedWars.map(w => ({
        name: w.name,
        start_date: w.start_date,
        end_date: w.end_date,
        type: w.type,
        description: w.description,
        casualties: w.casualties,
        economic_impact: w.economic_impact,
        outcome: w.outcome,
        consequences: w.consequences,
        countries_involved: w.countries_data?.map(c => c.country_name)
      }));

      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a military historian conducting comparative analysis of ${selectedWars.length} historical conflicts.

WARS TO ANALYZE:
${warsData.map(w => `- ${w.name} (${w.start_date} to ${w.end_date}): ${w.description}`).join('\n')}

Provide comprehensive comparative analysis:

1. COMMON CAUSES & TRIGGERS
   - Identify shared root causes
   - Compare triggering events
   - Analyze similarities in conditions that led to conflict

2. CASUALTY & ECONOMIC TRENDS
   - Compare casualty rates (military vs civilian)
   - Analyze economic impact trends over time
   - Identify patterns in destruction/recovery

3. MILITARY STRATEGIES & DIPLOMATIC EFFECTIVENESS
   - Compare tactical approaches
   - Evaluate success of diplomatic interventions
   - Assess effectiveness of different strategies

4. LONG-TERM GEOPOLITICAL CONSEQUENCES
   - Border changes and territorial impact
   - Power shifts and alliance formations
   - Cultural and societal impacts
   - Lessons learned and policy changes

5. COMPARATIVE METRICS
   - Duration comparison
   - Intensity (casualties per day/month)
   - Economic cost per casualty
   - Post-war recovery periods

Be specific, use actual data, identify patterns and outliers.`,
        response_json_schema: {
          type: "object",
          properties: {
            executive_summary: { type: "string" },
            common_causes: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  cause: { type: "string" },
                  wars_affected: { type: "array", items: { type: "string" } },
                  analysis: { type: "string" }
                }
              }
            },
            casualty_trends: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  war_name: { type: "string" },
                  year: { type: "number" },
                  military_casualties: { type: "number" },
                  civilian_casualties: { type: "number" },
                  casualty_rate_per_day: { type: "number" }
                }
              }
            },
            economic_analysis: {
              type: "object",
              properties: {
                comparative_costs: {
                  type: "array",
                  items: {
                    type: "object",
                    properties: {
                      war_name: { type: "string" },
                      total_cost_billions: { type: "number" },
                      cost_per_casualty: { type: "number" },
                      gdp_impact_percent: { type: "number" }
                    }
                  }
                },
                trend_analysis: { type: "string" }
              }
            },
            strategy_effectiveness: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  strategy_type: { type: "string" },
                  wars_used: { type: "array", items: { type: "string" } },
                  success_rate: { type: "number" },
                  effectiveness_analysis: { type: "string" }
                }
              }
            },
            diplomatic_interventions: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  intervention_type: { type: "string" },
                  war_name: { type: "string" },
                  outcome: { type: "string" },
                  effectiveness_score: { type: "number" }
                }
              }
            },
            geopolitical_consequences: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  consequence_type: { type: "string" },
                  wars_involved: { type: "array", items: { type: "string" } },
                  long_term_impact: { type: "string" },
                  modern_relevance: { type: "string" }
                }
              }
            },
            comparative_metrics: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  war_name: { type: "string" },
                  duration_days: { type: "number" },
                  intensity_score: { type: "number" },
                  recovery_period_years: { type: "number" }
                }
              }
            },
            key_insights: { type: "array", items: { type: "string" } },
            historical_patterns: { type: "array", items: { type: "string" } }
          }
        },
        add_context_from_internet: true
      });

      setAnalysis(result);
      return result;
    }
  });

  if (!selectedWars || selectedWars.length < 2) {
    return (
      <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
        <div className="text-center py-8">
          <AlertTriangle className="w-12 h-12 text-yellow-400 mx-auto mb-3" />
          <p className="text-yellow-400 font-mono text-sm">
            Select at least 2 wars to perform comparative analysis
          </p>
        </div>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {!analysis && (
        <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
          <div className="text-center space-y-4">
            <h3 className="text-xl font-bold text-cyan-400 glow-text font-mono">
              COMPARATIVE ANALYSIS
            </h3>
            <p className="text-slate-400 font-mono text-sm">
              Analyzing {selectedWars.length} conflicts: {selectedWars.map(w => w.name).join(', ')}
            </p>
            <Button
              onClick={() => generateComparativeAnalysisMutation.mutate()}
              disabled={generateComparativeAnalysisMutation.isPending}
              className="bg-gradient-to-r from-cyan-500 to-blue-500 hover:from-cyan-600 hover:to-blue-600 text-white font-mono"
            >
              {generateComparativeAnalysisMutation.isPending ? (
                <>
                  <Loader2 className="w-5 h-5 mr-2 animate-spin" />
                  ANALYZING...
                </>
              ) : (
                'GENERATE ANALYSIS'
              )}
            </Button>
          </div>
        </Card>
      )}

      {analysis && (
        <>
          <Card className="bg-gradient-to-br from-cyan-950/50 to-blue-950/50 backdrop-blur-xl cyber-border p-6">
            <h3 className="text-2xl font-bold text-cyan-400 glow-text font-mono mb-3">
              EXECUTIVE SUMMARY
            </h3>
            <p className="text-slate-300 font-mono text-sm">{analysis.executive_summary}</p>
          </Card>

          {/* Common Causes */}
          <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
            <h3 className="text-xl font-bold text-purple-400 glow-text font-mono mb-4">
              COMMON CAUSES & TRIGGERS
            </h3>
            <div className="space-y-3">
              {analysis.common_causes?.map((cause, idx) => (
                <div key={idx} className="bg-slate-900/50 cyber-border rounded p-4">
                  <h4 className="text-md font-bold text-yellow-400 font-mono mb-2">{cause.cause}</h4>
                  <div className="mb-2">
                    <span className="text-xs text-slate-500 font-mono">Affected Wars: </span>
                    <div className="flex flex-wrap gap-1 mt-1">
                      {cause.wars_affected?.map((war, i) => (
                        <Badge key={i} variant="outline" className="border-purple-500/30 text-purple-400 font-mono text-xs">
                          {war}
                        </Badge>
                      ))}
                    </div>
                  </div>
                  <p className="text-slate-400 font-mono text-xs">{cause.analysis}</p>
                </div>
              ))}
            </div>
          </Card>

          {/* Casualty Trends Chart */}
          {analysis.casualty_trends?.length > 0 && (
            <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
              <h3 className="text-xl font-bold text-red-400 glow-text font-mono mb-4 flex items-center gap-2">
                <Users className="w-6 h-6" />
                CASUALTY TRENDS OVER TIME
              </h3>
              <div className="h-[400px]">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={analysis.casualty_trends}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis dataKey="year" stroke="#94a3b8" style={{ fontFamily: 'monospace', fontSize: '11px' }} />
                    <YAxis stroke="#94a3b8" style={{ fontFamily: 'monospace', fontSize: '11px' }} />
                    <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155' }} />
                    <Legend wrapperStyle={{ fontFamily: 'monospace' }} />
                    <Line type="monotone" dataKey="military_casualties" stroke="#ef4444" name="Military" />
                    <Line type="monotone" dataKey="civilian_casualties" stroke="#f97316" name="Civilian" />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </Card>
          )}

          {/* Economic Analysis */}
          {analysis.economic_analysis?.comparative_costs && (
            <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
              <h3 className="text-xl font-bold text-yellow-400 glow-text font-mono mb-4 flex items-center gap-2">
                <DollarSign className="w-6 h-6" />
                ECONOMIC IMPACT COMPARISON
              </h3>
              <div className="h-[350px] mb-4">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={analysis.economic_analysis.comparative_costs}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
                    <XAxis dataKey="war_name" stroke="#94a3b8" style={{ fontFamily: 'monospace', fontSize: '10px' }} angle={-15} textAnchor="end" height={80} />
                    <YAxis stroke="#94a3b8" style={{ fontFamily: 'monospace', fontSize: '11px' }} />
                    <Tooltip contentStyle={{ backgroundColor: '#0f172a', border: '1px solid #334155' }} />
                    <Legend wrapperStyle={{ fontFamily: 'monospace' }} />
                    <Bar dataKey="total_cost_billions" fill="#fbbf24" name="Total Cost (Billions)" />
                  </BarChart>
                </ResponsiveContainer>
              </div>
              <div className="p-3 bg-yellow-950/20 cyber-border rounded">
                <p className="text-slate-300 font-mono text-sm">{analysis.economic_analysis.trend_analysis}</p>
              </div>
            </Card>
          )}

          {/* Strategy Effectiveness */}
          {analysis.strategy_effectiveness?.length > 0 && (
            <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
              <h3 className="text-xl font-bold text-green-400 glow-text font-mono mb-4 flex items-center gap-2">
                <Target className="w-6 h-6" />
                MILITARY STRATEGY EFFECTIVENESS
              </h3>
              <div className="space-y-3">
                {analysis.strategy_effectiveness.map((strategy, idx) => (
                  <div key={idx} className="bg-slate-900/50 cyber-border rounded p-4">
                    <div className="flex items-start justify-between mb-2">
                      <h4 className="text-md font-bold text-cyan-400 font-mono">{strategy.strategy_type}</h4>
                      <Badge className={`${strategy.success_rate > 70 ? 'bg-green-500/20 text-green-400 border-green-500/30' : strategy.success_rate > 40 ? 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30' : 'bg-red-500/20 text-red-400 border-red-500/30'} font-mono`}>
                        {strategy.success_rate}% Success
                      </Badge>
                    </div>
                    <div className="mb-2">
                      <span className="text-xs text-slate-500 font-mono">Used in: </span>
                      <div className="flex flex-wrap gap-1 mt-1">
                        {strategy.wars_used?.map((war, i) => (
                          <Badge key={i} variant="outline" className="border-green-500/30 text-green-400 font-mono text-xs">
                            {war}
                          </Badge>
                        ))}
                      </div>
                    </div>
                    <p className="text-slate-400 font-mono text-xs">{strategy.effectiveness_analysis}</p>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {/* Geopolitical Consequences */}
          {analysis.geopolitical_consequences?.length > 0 && (
            <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
              <h3 className="text-xl font-bold text-purple-400 glow-text font-mono mb-4 flex items-center gap-2">
                <TrendingUp className="w-6 h-6" />
                LONG-TERM GEOPOLITICAL CONSEQUENCES
              </h3>
              <div className="space-y-3">
                {analysis.geopolitical_consequences.map((consequence, idx) => (
                  <div key={idx} className="bg-slate-900/50 cyber-border rounded p-4">
                    <h4 className="text-md font-bold text-purple-400 font-mono mb-2">{consequence.consequence_type}</h4>
                    <div className="mb-2">
                      <span className="text-xs text-slate-500 font-mono">Wars Involved: </span>
                      <div className="flex flex-wrap gap-1 mt-1">
                        {consequence.wars_involved?.map((war, i) => (
                          <Badge key={i} variant="outline" className="border-purple-500/30 text-purple-400 font-mono text-xs">
                            {war}
                          </Badge>
                        ))}
                      </div>
                    </div>
                    <div className="mb-2">
                      <div className="text-xs text-slate-500 font-mono mb-1">Long-term Impact:</div>
                      <p className="text-slate-400 font-mono text-xs">{consequence.long_term_impact}</p>
                    </div>
                    <div>
                      <div className="text-xs text-slate-500 font-mono mb-1">Modern Relevance:</div>
                      <p className="text-cyan-400 font-mono text-xs">{consequence.modern_relevance}</p>
                    </div>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {/* Key Insights */}
          <Card className="bg-gradient-to-br from-green-950/50 to-cyan-950/50 backdrop-blur-xl cyber-border p-6">
            <h3 className="text-xl font-bold text-green-400 glow-text font-mono mb-4">
              KEY INSIGHTS & PATTERNS
            </h3>
            <div className="grid md:grid-cols-2 gap-3">
              <div>
                <h4 className="text-sm font-bold text-cyan-400 font-mono mb-2">Key Insights</h4>
                <ul className="space-y-1">
                  {analysis.key_insights?.map((insight, idx) => (
                    <li key={idx} className="text-slate-300 font-mono text-xs flex items-start gap-2">
                      <span className="text-green-400">▸</span>
                      {insight}
                    </li>
                  ))}
                </ul>
              </div>
              <div>
                <h4 className="text-sm font-bold text-purple-400 font-mono mb-2">Historical Patterns</h4>
                <ul className="space-y-1">
                  {analysis.historical_patterns?.map((pattern, idx) => (
                    <li key={idx} className="text-slate-300 font-mono text-xs flex items-start gap-2">
                      <span className="text-purple-400">▸</span>
                      {pattern}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </Card>
        </>
      )}
    </div>
  );
}

