import React, { useState, useEffect } from 'react';

export default function GlitchOverlay({ 
  enabled = true, 
  intensity = 'low', // 'low', 'medium', 'high'
  scanlines = true 
}) {
  const [glitchActive, setGlitchActive] = useState(false);

  useEffect(() => {
    if (!enabled) return;

    const intensityConfig = {
      low: { frequency: 15000, duration: 150 },
      medium: { frequency: 8000, duration: 200 },
      high: { frequency: 4000, duration: 300 }
    };

    const config = intensityConfig[intensity];

    const triggerGlitch = () => {
      setGlitchActive(true);
      setTimeout(() => setGlitchActive(false), config.duration);
    };

    const interval = setInterval(() => {
      if (Math.random() > 0.7) {
        triggerGlitch();
      }
    }, config.frequency);

    return () => clearInterval(interval);
  }, [enabled, intensity]);

  if (!enabled) return null;

  return (
    <>
      <style>{`
        @keyframes glitch-anim {
          0% {
            clip-path: inset(40% 0 61% 0);
            transform: translate(-2px, 2px);
          }
          20% {
            clip-path: inset(92% 0 1% 0);
            transform: translate(2px, -2px);
          }
          40% {
            clip-path: inset(43% 0 1% 0);
            transform: translate(-2px, 2px);
          }
          60% {
            clip-path: inset(25% 0 58% 0);
            transform: translate(2px, -2px);
          }
          80% {
            clip-path: inset(54% 0 7% 0);
            transform: translate(-2px, 2px);
          }
          100% {
            clip-path: inset(58% 0 43% 0);
            transform: translate(2px, -2px);
          }
        }

        @keyframes glitch-color {
          0% {
            filter: hue-rotate(0deg);
          }
          50% {
            filter: hue-rotate(20deg);
          }
          100% {
            filter: hue-rotate(0deg);
          }
        }

        @keyframes scanline-move {
          0% {
            transform: translateY(-100%);
          }
          100% {
            transform: translateY(100vh);
          }
        }

        .glitch-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          pointer-events: none;
          z-index: 9999;
        }

        .glitch-active::before {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: linear-gradient(
            transparent 0%,
            rgba(0, 255, 65, 0.03) 50%,
            transparent 100%
          );
          animation: glitch-anim 0.2s infinite;
        }

        .glitch-active::after {
          content: '';
          position: absolute;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          background: rgba(0, 245, 255, 0.02);
          animation: glitch-color 0.3s infinite;
        }

        .scanlines {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          pointer-events: none;
          z-index: 9998;
          background: repeating-linear-gradient(
            0deg,
            transparent,
            transparent 2px,
            rgba(0, 0, 0, 0.1) 2px,
            rgba(0, 0, 0, 0.1) 4px
          );
        }

        .scan-bar {
          position: absolute;
          left: 0;
          right: 0;
          height: 4px;
          background: linear-gradient(
            transparent,
            rgba(0, 245, 255, 0.1),
            transparent
          );
          animation: scanline-move 8s linear infinite;
        }

        .noise-overlay {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          pointer-events: none;
          z-index: 9997;
          opacity: 0.02;
          background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
        }

        .vignette {
          position: fixed;
          top: 0;
          left: 0;
          right: 0;
          bottom: 0;
          pointer-events: none;
          z-index: 9996;
          background: radial-gradient(
            ellipse at center,
            transparent 50%,
            rgba(0, 0, 0, 0.3) 100%
          );
        }
      `}</style>

      {/* Vignette effect */}
      <div className="vignette" />

      {/* Noise texture */}
      <div className="noise-overlay" />

      {/* Scanlines */}
      {scanlines && (
        <div className="scanlines">
          <div className="scan-bar" />
        </div>
      )}

      {/* Glitch overlay */}
      <div className={`glitch-overlay ${glitchActive ? 'glitch-active' : ''}`} />
    </>
  );
}

