import React, { useState, useEffect } from 'react';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Slider } from '@/components/ui/slider';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Bell, AlertTriangle, CloudRain, Droplets, Globe, Save, X, Plus } from 'lucide-react';
import { toast } from 'sonner';

export default function FutureWarsAlertSettings({ 
  userProfile, 
  onSave, 
  onClose,
  isOpen 
}) {
  const [thresholds, setThresholds] = useState({
    conflict_probability_threshold: 60,
    climate_impact_threshold: 70,
    resource_scarcity_threshold: 70,
    monitored_regions: [],
    monitored_conflict_types: [],
    enabled: true
  });

  const [newRegion, setNewRegion] = useState('');
  const [newConflictType, setNewConflictType] = useState('');

  useEffect(() => {
    if (userProfile?.future_wars_alert_thresholds) {
      setThresholds({
        ...thresholds,
        ...userProfile.future_wars_alert_thresholds
      });
    }
  }, [userProfile]);

  const handleSave = () => {
    onSave(thresholds);
    toast.success('Alert thresholds saved successfully');
  };

  const addRegion = () => {
    if (newRegion.trim() && !thresholds.monitored_regions.includes(newRegion.trim())) {
      setThresholds({
        ...thresholds,
        monitored_regions: [...thresholds.monitored_regions, newRegion.trim()]
      });
      setNewRegion('');
    }
  };

  const removeRegion = (region) => {
    setThresholds({
      ...thresholds,
      monitored_regions: thresholds.monitored_regions.filter(r => r !== region)
    });
  };

  const addConflictType = () => {
    if (newConflictType.trim() && !thresholds.monitored_conflict_types.includes(newConflictType.trim())) {
      setThresholds({
        ...thresholds,
        monitored_conflict_types: [...thresholds.monitored_conflict_types, newConflictType.trim()]
      });
      setNewConflictType('');
    }
  };

  const removeConflictType = (type) => {
    setThresholds({
      ...thresholds,
      monitored_conflict_types: thresholds.monitored_conflict_types.filter(t => t !== type)
    });
  };

  if (!isOpen) return null;

  return (
    <Card className="bg-slate-950/95 backdrop-blur-xl border-purple-500/30 p-6 mb-6">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Bell className="w-6 h-6 text-purple-400" />
          <div>
            <h3 className="text-xl font-bold text-purple-400 font-mono">
              FUTURE WARS ALERT THRESHOLDS
            </h3>
            <p className="text-slate-400 font-mono text-xs">
              Set custom thresholds for predictive conflict alerts
            </p>
          </div>
        </div>
        <Button variant="ghost" size="icon" onClick={onClose}>
          <X className="w-5 h-5 text-slate-400" />
        </Button>
      </div>

      <div className="space-y-6">
        {/* Master Enable/Disable */}
        <div className="flex items-center justify-between p-4 bg-slate-900/50 rounded-lg border border-slate-700/50">
          <div className="flex items-center gap-3">
            <AlertTriangle className="w-5 h-5 text-yellow-400" />
            <div>
              <Label className="text-slate-200 font-mono">Enable Predictive Alerts</Label>
              <p className="text-xs text-slate-400 font-mono">Toggle all future wars alerts</p>
            </div>
          </div>
          <Switch
            checked={thresholds.enabled}
            onCheckedChange={(checked) => setThresholds({ ...thresholds, enabled: checked })}
          />
        </div>

        {thresholds.enabled && (
          <>
            <div className="grid md:grid-cols-3 gap-6">
              {/* Conflict Probability Threshold */}
              <div className="p-4 bg-red-950/20 rounded-lg border border-red-500/30">
                <div className="flex items-center gap-2 mb-4">
                  <AlertTriangle className="w-5 h-5 text-red-400" />
                  <Label className="text-red-400 font-mono font-bold text-sm">Conflict Probability</Label>
                </div>
                <div className="space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-slate-400 font-mono text-xs">Alert when exceeds:</span>
                    <Badge className="bg-red-500/20 text-red-400 border-red-500/30 font-mono">
                      {thresholds.conflict_probability_threshold}%
                    </Badge>
                  </div>
                  <Slider
                    value={[thresholds.conflict_probability_threshold]}
                    onValueChange={(v) => setThresholds({ ...thresholds, conflict_probability_threshold: v[0] })}
                    min={10}
                    max={100}
                    step={5}
                    className="py-2"
                  />
                </div>
              </div>

              {/* Climate Impact Threshold */}
              <div className="p-4 bg-blue-950/20 rounded-lg border border-blue-500/30">
                <div className="flex items-center gap-2 mb-4">
                  <CloudRain className="w-5 h-5 text-blue-400" />
                  <Label className="text-blue-400 font-mono font-bold text-sm">Climate Impact</Label>
                </div>
                <div className="space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-slate-400 font-mono text-xs">Alert when exceeds:</span>
                    <Badge className="bg-blue-500/20 text-blue-400 border-blue-500/30 font-mono">
                      {thresholds.climate_impact_threshold}/100
                    </Badge>
                  </div>
                  <Slider
                    value={[thresholds.climate_impact_threshold]}
                    onValueChange={(v) => setThresholds({ ...thresholds, climate_impact_threshold: v[0] })}
                    min={10}
                    max={100}
                    step={5}
                    className="py-2"
                  />
                </div>
              </div>

              {/* Resource Scarcity Threshold */}
              <div className="p-4 bg-orange-950/20 rounded-lg border border-orange-500/30">
                <div className="flex items-center gap-2 mb-4">
                  <Droplets className="w-5 h-5 text-orange-400" />
                  <Label className="text-orange-400 font-mono font-bold text-sm">Resource Scarcity</Label>
                </div>
                <div className="space-y-3">
                  <div className="flex justify-between items-center">
                    <span className="text-slate-400 font-mono text-xs">Alert when exceeds:</span>
                    <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/30 font-mono">
                      {thresholds.resource_scarcity_threshold}/100
                    </Badge>
                  </div>
                  <Slider
                    value={[thresholds.resource_scarcity_threshold]}
                    onValueChange={(v) => setThresholds({ ...thresholds, resource_scarcity_threshold: v[0] })}
                    min={10}
                    max={100}
                    step={5}
                    className="py-2"
                  />
                </div>
              </div>
            </div>

            {/* Monitored Regions */}
            <div className="p-4 bg-cyan-950/20 rounded-lg border border-cyan-500/30">
              <div className="flex items-center gap-2 mb-4">
                <Globe className="w-5 h-5 text-cyan-400" />
                <Label className="text-cyan-400 font-mono font-bold">Monitored Regions</Label>
              </div>
              <div className="flex gap-2 mb-3">
                <Input
                  value={newRegion}
                  onChange={(e) => setNewRegion(e.target.value)}
                  placeholder="Add region (e.g., Middle East, South Asia...)"
                  className="bg-slate-900/50 border-cyan-500/30 text-slate-200 font-mono text-sm"
                  onKeyPress={(e) => e.key === 'Enter' && addRegion()}
                />
                <Button onClick={addRegion} variant="outline" className="border-cyan-500/30 text-cyan-400">
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                {thresholds.monitored_regions.map((region, idx) => (
                  <Badge 
                    key={idx}
                    className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 font-mono text-xs cursor-pointer hover:bg-red-500/20"
                    onClick={() => removeRegion(region)}
                  >
                    {region} ×
                  </Badge>
                ))}
                {thresholds.monitored_regions.length === 0 && (
                  <span className="text-slate-500 font-mono text-xs">No regions added (all regions monitored)</span>
                )}
              </div>
            </div>

            {/* Monitored Conflict Types */}
            <div className="p-4 bg-purple-950/20 rounded-lg border border-purple-500/30">
              <div className="flex items-center gap-2 mb-4">
                <AlertTriangle className="w-5 h-5 text-purple-400" />
                <Label className="text-purple-400 font-mono font-bold">Monitored Conflict Types</Label>
              </div>
              <div className="flex gap-2 mb-3">
                <Input
                  value={newConflictType}
                  onChange={(e) => setNewConflictType(e.target.value)}
                  placeholder="Add type (e.g., territorial, economic, climate...)"
                  className="bg-slate-900/50 border-purple-500/30 text-slate-200 font-mono text-sm"
                  onKeyPress={(e) => e.key === 'Enter' && addConflictType()}
                />
                <Button onClick={addConflictType} variant="outline" className="border-purple-500/30 text-purple-400">
                  <Plus className="w-4 h-4" />
                </Button>
              </div>
              <div className="flex flex-wrap gap-2">
                {thresholds.monitored_conflict_types.map((type, idx) => (
                  <Badge 
                    key={idx}
                    className="bg-purple-500/20 text-purple-400 border-purple-500/30 font-mono text-xs cursor-pointer hover:bg-red-500/20"
                    onClick={() => removeConflictType(type)}
                  >
                    {type} ×
                  </Badge>
                ))}
                {thresholds.monitored_conflict_types.length === 0 && (
                  <span className="text-slate-500 font-mono text-xs">No types added (all types monitored)</span>
                )}
              </div>
            </div>
          </>
        )}

        <Button
          onClick={handleSave}
          className="w-full bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white font-mono py-4"
        >
          <Save className="w-5 h-5 mr-2" />
          SAVE ALERT THRESHOLDS
        </Button>
      </div>
    </Card>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { RotateCcw, ZoomIn, ZoomOut, Layers, AlertTriangle } from 'lucide-react';

export default function Interactive3DGlobe({ conflicts = [], riskData = [], onConflictSelect }) {
  const containerRef = useRef(null);
  const sceneRef = useRef(null);
  const cameraRef = useRef(null);
  const rendererRef = useRef(null);
  const globeRef = useRef(null);
  const markersRef = useRef([]);
  const [selectedConflict, setSelectedConflict] = useState(null);
  const [isRotating, setIsRotating] = useState(true);
  const [showRiskOverlay, setShowRiskOverlay] = useState(false);

  useEffect(() => {
    if (!containerRef.current) return;

    // Scene setup
    const scene = new THREE.Scene();
    sceneRef.current = scene;

    // Camera
    const camera = new THREE.PerspectiveCamera(
      45,
      containerRef.current.clientWidth / containerRef.current.clientHeight,
      0.1,
      1000
    );
    camera.position.z = 3;
    cameraRef.current = camera;

    // Renderer
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
    renderer.setClearColor(0x000000, 0);
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Globe geometry
    const geometry = new THREE.SphereGeometry(1, 64, 64);

    // Create gradient material for globe
    const material = new THREE.MeshPhongMaterial({
      color: 0x1a365d,
      emissive: 0x0a1628,
      specular: 0x00ff41,
      shininess: 10,
      transparent: true,
      opacity: 0.9,
      wireframe: false
    });

    const globe = new THREE.Mesh(geometry, material);
    scene.add(globe);
    globeRef.current = globe;

    // Wireframe overlay
    const wireframeMaterial = new THREE.MeshBasicMaterial({
      color: 0x00ff41,
      wireframe: true,
      transparent: true,
      opacity: 0.15
    });
    const wireframe = new THREE.Mesh(geometry, wireframeMaterial);
    wireframe.scale.set(1.01, 1.01, 1.01);
    scene.add(wireframe);

    // Atmosphere glow
    const atmosphereGeometry = new THREE.SphereGeometry(1.15, 64, 64);
    const atmosphereMaterial = new THREE.MeshBasicMaterial({
      color: 0x00f5ff,
      transparent: true,
      opacity: 0.1,
      side: THREE.BackSide
    });
    const atmosphere = new THREE.Mesh(atmosphereGeometry, atmosphereMaterial);
    scene.add(atmosphere);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x404040, 0.5);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0x00ff41, 1);
    directionalLight.position.set(5, 3, 5);
    scene.add(directionalLight);

    const pointLight = new THREE.PointLight(0x00f5ff, 0.5);
    pointLight.position.set(-5, -3, -5);
    scene.add(pointLight);

    // Stars background
    const starsGeometry = new THREE.BufferGeometry();
    const starsMaterial = new THREE.PointsMaterial({
      color: 0xffffff,
      size: 0.02,
      transparent: true,
      opacity: 0.8
    });

    const starsVertices = [];
    for (let i = 0; i < 2000; i++) {
      const x = (Math.random() - 0.5) * 100;
      const y = (Math.random() - 0.5) * 100;
      const z = (Math.random() - 0.5) * 100;
      starsVertices.push(x, y, z);
    }
    starsGeometry.setAttribute('position', new THREE.Float32BufferAttribute(starsVertices, 3));
    const stars = new THREE.Points(starsGeometry, starsMaterial);
    scene.add(stars);

    // Add conflict markers
    const addMarkers = () => {
      // Clear existing markers
      markersRef.current.forEach(marker => scene.remove(marker));
      markersRef.current = [];

      conflicts.forEach((conflict, index) => {
        if (conflict.countries_data) {
          conflict.countries_data.forEach(country => {
            if (country.latitude && country.longitude) {
              const markerGeometry = new THREE.SphereGeometry(0.02, 16, 16);
              const markerMaterial = new THREE.MeshBasicMaterial({
                color: conflict.status === 'ongoing' ? 0xff0000 : 
                       conflict.status === 'predicted' ? 0xffaa00 : 0x00ff00,
                transparent: true,
                opacity: 0.9
              });
              const marker = new THREE.Mesh(markerGeometry, markerMaterial);

              // Convert lat/long to 3D position
              const phi = (90 - country.latitude) * (Math.PI / 180);
              const theta = (country.longitude + 180) * (Math.PI / 180);
              marker.position.x = -1.02 * Math.sin(phi) * Math.cos(theta);
              marker.position.y = 1.02 * Math.cos(phi);
              marker.position.z = 1.02 * Math.sin(phi) * Math.sin(theta);

              marker.userData = { conflict, country };
              scene.add(marker);
              markersRef.current.push(marker);

              // Pulsing ring for active conflicts
              if (conflict.status === 'ongoing') {
                const ringGeometry = new THREE.RingGeometry(0.03, 0.05, 32);
                const ringMaterial = new THREE.MeshBasicMaterial({
                  color: 0xff0000,
                  transparent: true,
                  opacity: 0.5,
                  side: THREE.DoubleSide
                });
                const ring = new THREE.Mesh(ringGeometry, ringMaterial);
                ring.position.copy(marker.position);
                ring.lookAt(0, 0, 0);
                scene.add(ring);
                markersRef.current.push(ring);
              }
            }
          });
        }
      });
    };

    addMarkers();

    // Animation loop
    let animationId;
    const animate = () => {
      animationId = requestAnimationFrame(animate);

      if (isRotating && globeRef.current) {
        globeRef.current.rotation.y += 0.002;
        wireframe.rotation.y += 0.002;
      }

      // Pulse markers
      markersRef.current.forEach((marker, i) => {
        if (marker.geometry.type === 'RingGeometry') {
          marker.material.opacity = 0.3 + Math.sin(Date.now() * 0.005 + i) * 0.2;
        }
      });

      renderer.render(scene, camera);
    };
    animate();

    // Handle resize
    const handleResize = () => {
      if (!containerRef.current) return;
      camera.aspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
    };
    window.addEventListener('resize', handleResize);

    // Mouse interaction
    let isDragging = false;
    let previousMousePosition = { x: 0, y: 0 };

    const onMouseDown = (e) => {
      isDragging = true;
      setIsRotating(false);
    };

    const onMouseMove = (e) => {
      if (isDragging && globeRef.current) {
        const deltaMove = {
          x: e.clientX - previousMousePosition.x,
          y: e.clientY - previousMousePosition.y
        };
        globeRef.current.rotation.y += deltaMove.x * 0.005;
        globeRef.current.rotation.x += deltaMove.y * 0.005;
      }
      previousMousePosition = { x: e.clientX, y: e.clientY };
    };

    const onMouseUp = () => {
      isDragging = false;
    };

    const onWheel = (e) => {
      e.preventDefault();
      camera.position.z += e.deltaY * 0.001;
      camera.position.z = Math.max(1.5, Math.min(5, camera.position.z));
    };

    renderer.domElement.addEventListener('mousedown', onMouseDown);
    renderer.domElement.addEventListener('mousemove', onMouseMove);
    renderer.domElement.addEventListener('mouseup', onMouseUp);
    renderer.domElement.addEventListener('wheel', onWheel, { passive: false });

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('resize', handleResize);
      renderer.domElement.removeEventListener('mousedown', onMouseDown);
      renderer.domElement.removeEventListener('mousemove', onMouseMove);
      renderer.domElement.removeEventListener('mouseup', onMouseUp);
      renderer.domElement.removeEventListener('wheel', onWheel);
      if (containerRef.current && renderer.domElement) {
        containerRef.current.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, [conflicts, isRotating]);

  const handleZoom = (direction) => {
    if (cameraRef.current) {
      cameraRef.current.position.z += direction * 0.3;
      cameraRef.current.position.z = Math.max(1.5, Math.min(5, cameraRef.current.position.z));
    }
  };

  const handleReset = () => {
    if (cameraRef.current && globeRef.current) {
      cameraRef.current.position.z = 3;
      globeRef.current.rotation.x = 0;
      globeRef.current.rotation.y = 0;
      setIsRotating(true);
    }
  };

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-4 relative overflow-hidden">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-lg font-bold text-cyan-400 glow-text font-mono">3D GLOBAL THEATER</h3>
        <div className="flex items-center gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={() => setShowRiskOverlay(!showRiskOverlay)}
            className={`font-mono text-xs ${showRiskOverlay ? 'bg-purple-500/20 text-purple-400 border-purple-500/30' : 'border-slate-600/30 text-slate-400'}`}
          >
            <Layers className="w-3 h-3 mr-1" />
            RISK OVERLAY
          </Button>
          <Button size="icon" variant="ghost" onClick={() => handleZoom(-1)} className="text-cyan-400">
            <ZoomIn className="w-4 h-4" />
          </Button>
          <Button size="icon" variant="ghost" onClick={() => handleZoom(1)} className="text-cyan-400">
            <ZoomOut className="w-4 h-4" />
          </Button>
          <Button size="icon" variant="ghost" onClick={handleReset} className="text-cyan-400">
            <RotateCcw className="w-4 h-4" />
          </Button>
        </div>
      </div>

      <div 
        ref={containerRef} 
        className="w-full h-[400px] rounded-lg overflow-hidden cursor-grab active:cursor-grabbing"
        style={{ background: 'radial-gradient(circle at center, #0a1628 0%, #000510 100%)' }}
      />

      {/* Legend */}
      <div className="absolute bottom-8 left-8 bg-slate-950/80 backdrop-blur-sm cyber-border rounded-lg p-3">
        <div className="text-xs font-mono text-slate-400 mb-2">CONFLICT STATUS</div>
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-red-500 animate-pulse"></div>
            <span className="text-xs font-mono text-red-400">Active Conflict</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-orange-500"></div>
            <span className="text-xs font-mono text-orange-400">Predicted</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-3 h-3 rounded-full bg-green-500"></div>
            <span className="text-xs font-mono text-green-400">Resolved</span>
          </div>
        </div>
      </div>

      {/* Selected conflict info */}
      {selectedConflict && (
        <div className="absolute top-20 right-8 bg-slate-950/90 backdrop-blur-sm cyber-border rounded-lg p-4 max-w-xs">
          <div className="flex items-center gap-2 mb-2">
            <AlertTriangle className="w-4 h-4 text-red-400" />
            <span className="text-sm font-bold text-green-400 font-mono">{selectedConflict.name}</span>
          </div>
          <p className="text-xs text-slate-400 font-mono">{selectedConflict.description}</p>
        </div>
      )}
    </Card>
  );
}

