import React, { useState } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { 
  History, Loader2, GitBranch, Sparkles, ArrowRight, 
  Clock, Globe, Users, Swords, ChevronRight
} from 'lucide-react';
import { toast } from 'sonner';

export default function HistoricalWhatIfAnalysis({ selectedWar }) {
  const [divergencePoint, setDivergencePoint] = useState('');
  const [divergenceType, setDivergenceType] = useState('battle');
  const [customDivergence, setCustomDivergence] = useState('');
  const [analysisResult, setAnalysisResult] = useState(null);

  const divergenceTypes = [
    { id: 'battle', name: 'Battle Outcome', description: 'Change the result of a key battle' },
    { id: 'diplomatic', name: 'Diplomatic Decision', description: 'Alter a diplomatic choice or treaty' },
    { id: 'leadership', name: 'Leadership Change', description: 'Change a leader\'s decision or fate' },
    { id: 'technology', name: 'Technology', description: 'Alter technological availability' },
    { id: 'alliance', name: 'Alliance Shift', description: 'Change alliance structures' },
    { id: 'resource', name: 'Resource Availability', description: 'Modify resource access' }
  ];

  const analyzeWhatIfMutation = useMutation({
    mutationFn: async () => {
      const warContext = selectedWar ? `
Historical Conflict: ${selectedWar.name}
Period: ${selectedWar.start_date} - ${selectedWar.end_date || 'Ongoing'}
Belligerents: ${selectedWar.countries_involved?.join(', ')}
Actual Outcome: ${selectedWar.description}
` : '';

      const response = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a counterfactual historian specializing in alternate history analysis. Analyze the following "What-If" scenario and project how history might have unfolded differently.

${warContext}

DIVERGENCE POINT: ${divergencePoint}
DIVERGENCE TYPE: ${divergenceType}
SPECIFIC CHANGE: ${customDivergence}

Provide a comprehensive alternate history analysis including:

1. IMMEDIATE CONSEQUENCES (Days to Weeks)
   - Direct military/political impact
   - Reaction of key actors
   - Chain of events triggered

2. SHORT-TERM EFFECTS (Months to 1 Year)
   - Strategic shifts
   - Alliance changes
   - Economic impacts

3. LONG-TERM DIVERGENCE (Years to Decades)
   - How would the war have ended differently?
   - Territorial changes
   - Political systems affected
   - Technology development paths

4. BUTTERFLY EFFECTS
   - What other historical events would be changed?
   - How would the modern world look different?

5. PROBABILITY ASSESSMENT
   - How likely was this alternate path?
   - What factors would have needed to align?

Be historically rigorous while exploring creative possibilities.`,
        response_json_schema: {
          type: 'object',
          properties: {
            scenario_title: { type: 'string' },
            divergence_summary: { type: 'string' },
            plausibility_score: { type: 'number' },
            immediate_consequences: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  event: { type: 'string' },
                  timeframe: { type: 'string' },
                  impact: { type: 'string' }
                }
              }
            },
            short_term_effects: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  category: { type: 'string' },
                  description: { type: 'string' },
                  affected_parties: { type: 'array', items: { type: 'string' } }
                }
              }
            },
            long_term_divergence: {
              type: 'object',
              properties: {
                alternate_war_outcome: { type: 'string' },
                territorial_changes: { type: 'array', items: { type: 'string' } },
                political_shifts: { type: 'array', items: { type: 'string' } },
                technology_paths: { type: 'array', items: { type: 'string' } }
              }
            },
            butterfly_effects: {
              type: 'array',
              items: {
                type: 'object',
                properties: {
                  original_event: { type: 'string' },
                  altered_outcome: { type: 'string' },
                  significance: { type: 'string' }
                }
              }
            },
            modern_world_differences: { type: 'array', items: { type: 'string' } },
            key_factors_required: { type: 'array', items: { type: 'string' } },
            historian_notes: { type: 'string' }
          }
        },
        add_context_from_internet: true
      });

      return response;
    },
    onSuccess: (data) => {
      setAnalysisResult(data);
      toast.success('Alternate history analysis complete');
    }
  });

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl border border-sky-900/40 p-6">
      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 rounded-lg bg-amber-500/20 border border-amber-500/30">
          <History className="w-6 h-6 text-amber-400" />
        </div>
        <div>
          <h3 className="text-xl font-bold text-amber-400 glow-text font-mono">
            HISTORICAL "WHAT-IF" ANALYSIS
          </h3>
          <p className="text-xs text-slate-400 font-mono">Explore alternate history divergences</p>
        </div>
      </div>

      <div className="space-y-4">
        {/* War Context */}
        {selectedWar && (
          <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-3">
            <div className="text-xs text-amber-400 font-mono mb-1">ANALYZING CONFLICT</div>
            <div className="text-lg font-bold text-green-400 font-mono">{selectedWar.name}</div>
            <div className="text-slate-400 font-mono text-xs">{selectedWar.start_date} - {selectedWar.end_date || 'Ongoing'}</div>
          </div>
        )}

        {/* Divergence Type */}
        <div>
          <label className="text-amber-400 font-mono text-xs mb-2 block">DIVERGENCE TYPE</label>
          <div className="grid grid-cols-3 gap-2">
            {divergenceTypes.map((type) => (
              <Button
                key={type.id}
                onClick={() => setDivergenceType(type.id)}
                className={`flex flex-col items-start p-3 h-auto text-left ${
                  divergenceType === type.id
                    ? 'bg-amber-500/20 text-amber-400 border-amber-500/30'
                    : 'bg-slate-800/50 text-slate-400 border-slate-600/30'
                } border`}
              >
                <span className="text-xs font-mono font-bold">{type.name}</span>
                <span className="text-[10px] font-mono opacity-70">{type.description}</span>
              </Button>
            ))}
          </div>
        </div>

        {/* Divergence Point */}
        <div>
          <label className="text-amber-400 font-mono text-xs mb-1 block">DIVERGENCE POINT</label>
          <Input
            value={divergencePoint}
            onChange={(e) => setDivergencePoint(e.target.value)}
            placeholder="e.g., Battle of Stalingrad, 1942"
            className="bg-slate-900/50 border-amber-500/30 text-slate-200 font-mono"
          />
        </div>

        {/* Custom Divergence */}
        <div>
          <label className="text-amber-400 font-mono text-xs mb-1 block">WHAT IF...</label>
          <Textarea
            value={customDivergence}
            onChange={(e) => setCustomDivergence(e.target.value)}
            placeholder="Describe the specific change... e.g., 'What if Germany had won the Battle of Stalingrad?'"
            className="bg-slate-900/50 border-amber-500/30 text-slate-200 font-mono h-20"
          />
        </div>

        <Button
          onClick={() => analyzeWhatIfMutation.mutate()}
          disabled={analyzeWhatIfMutation.isPending || !divergencePoint || !customDivergence}
          className="w-full bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600 text-white font-mono"
        >
          {analyzeWhatIfMutation.isPending ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              ANALYZING DIVERGENCE...
            </>
          ) : (
            <>
              <GitBranch className="w-4 h-4 mr-2" />
              ANALYZE ALTERNATE HISTORY
            </>
          )}
        </Button>

        {/* Results */}
        {analysisResult && (
          <div className="space-y-4 mt-6">
            {/* Header */}
            <div className="bg-amber-500/10 border border-amber-500/30 rounded-lg p-4">
              <div className="flex items-center justify-between mb-2">
                <h4 className="text-xl font-bold text-amber-400 font-mono">{analysisResult.scenario_title}</h4>
                <Badge className="bg-amber-500/20 text-amber-400 border-amber-500/30 font-mono">
                  {analysisResult.plausibility_score}% Plausible
                </Badge>
              </div>
              <p className="text-slate-300 font-mono text-sm">{analysisResult.divergence_summary}</p>
            </div>

            {/* Immediate Consequences */}
            {analysisResult.immediate_consequences?.length > 0 && (
              <div className="bg-slate-900/50 border border-sky-800/30 rounded-lg p-4">
                <h5 className="text-red-400 font-mono font-bold text-sm mb-3 flex items-center gap-2">
                  <Clock className="w-4 h-4" />
                  IMMEDIATE CONSEQUENCES
                </h5>
                <div className="space-y-2">
                  {analysisResult.immediate_consequences.map((cons, i) => (
                    <div key={i} className="bg-red-500/10 border border-red-500/20 rounded p-2">
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-red-400 font-mono text-xs font-bold">{cons.event}</span>
                        <Badge className="bg-slate-700/50 text-slate-300 font-mono text-[10px]">
                          {cons.timeframe}
                        </Badge>
                      </div>
                      <p className="text-slate-400 font-mono text-xs">{cons.impact}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Long-term Divergence */}
            {analysisResult.long_term_divergence && (
              <div className="bg-slate-900/50 border border-sky-800/30 rounded-lg p-4">
                <h5 className="text-purple-400 font-mono font-bold text-sm mb-3 flex items-center gap-2">
                  <Globe className="w-4 h-4" />
                  LONG-TERM DIVERGENCE
                </h5>
                <div className="space-y-3">
                  <div className="bg-purple-500/10 border border-purple-500/20 rounded p-3">
                    <div className="text-xs text-purple-400 font-mono mb-1">ALTERNATE WAR OUTCOME</div>
                    <p className="text-slate-300 font-mono text-sm">{analysisResult.long_term_divergence.alternate_war_outcome}</p>
                  </div>

                  {analysisResult.long_term_divergence.territorial_changes?.length > 0 && (
                    <div>
                      <div className="text-xs text-cyan-400 font-mono mb-1">TERRITORIAL CHANGES</div>
                      <ul className="space-y-1">
                        {analysisResult.long_term_divergence.territorial_changes.map((change, i) => (
                          <li key={i} className="text-slate-400 font-mono text-xs flex items-start gap-2">
                            <ChevronRight className="w-3 h-3 mt-0.5 text-cyan-400" />
                            {change}
                          </li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>
              </div>
            )}

            {/* Butterfly Effects */}
            {analysisResult.butterfly_effects?.length > 0 && (
              <div className="bg-slate-900/50 border border-sky-800/30 rounded-lg p-4">
                <h5 className="text-pink-400 font-mono font-bold text-sm mb-3 flex items-center gap-2">
                  <Sparkles className="w-4 h-4" />
                  BUTTERFLY EFFECTS
                </h5>
                <div className="space-y-2">
                  {analysisResult.butterfly_effects.map((effect, i) => (
                    <div key={i} className="bg-pink-500/10 border border-pink-500/20 rounded p-2">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="text-slate-400 font-mono text-xs">{effect.original_event}</span>
                        <ArrowRight className="w-3 h-3 text-pink-400" />
                        <span className="text-pink-400 font-mono text-xs font-bold">{effect.altered_outcome}</span>
                      </div>
                      <p className="text-slate-500 font-mono text-[10px]">{effect.significance}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Modern World Differences */}
            {analysisResult.modern_world_differences?.length > 0 && (
              <div className="bg-green-500/10 border border-green-500/30 rounded-lg p-4">
                <h5 className="text-green-400 font-mono font-bold text-sm mb-3">HOW WOULD TODAY BE DIFFERENT?</h5>
                <ul className="space-y-1">
                  {analysisResult.modern_world_differences.map((diff, i) => (
                    <li key={i} className="text-slate-300 font-mono text-xs flex items-start gap-2">
                      <ChevronRight className="w-3 h-3 mt-0.5 text-green-400" />
                      {diff}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* Historian Notes */}
            {analysisResult.historian_notes && (
              <div className="bg-slate-800/50 rounded-lg p-4">
                <div className="text-xs text-slate-500 font-mono mb-2">HISTORIAN'S NOTES</div>
                <p className="text-slate-400 font-mono text-sm italic">"{analysisResult.historian_notes}"</p>
              </div>
            )}
          </div>
        )}
      </div>
    </Card>
  );
}

src/components/intel/ThreatIntelligenceF:
import React, { useState, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { 
  Shield, 
  AlertTriangle, 
  Radio, 
  Filter, 
  Bell, 
  Loader2,
  Globe,
  TrendingUp
} from 'lucide-react';

export default function ThreatIntelligenceFeed({ subscriptions = [], onSubscriptionChange }) {
  const [feeds, setFeeds] = useState(null);
  const [selectedRegions, setSelectedRegions] = useState(subscriptions.regions || []);
  const [selectedThreatTypes, setSelectedThreatTypes] = useState(subscriptions.types || []);
  const [alertThreshold, setAlertThreshold] = useState(subscriptions.threshold || 'medium');

  const fetchThreatIntelMutation = useMutation({
    mutationFn: async () => {
      const result = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a threat intelligence analyst aggregating data from OSINT (Open Source Intelligence) sources and geopolitical risk providers.

Fetch real-time threat intelligence covering:

1. GEOPOLITICAL THREATS
   - State-level tensions and diplomatic incidents
   - Military movements and exercises
   - Border disputes and territorial claims
   - Alliance shifts and treaty developments

2. TERRORISM & NON-STATE ACTORS
   - Terrorist group activities
   - Insurgent movements
   - Militia operations
   - Cyberattack groups

3. ECONOMIC THREATS
   - Sanctions and trade restrictions
   - Supply chain disruptions
   - Currency crises
   - Resource monopolization

4. CYBER THREATS
   - State-sponsored cyber operations
   - Critical infrastructure targeting
   - Espionage campaigns
   - Disinformation operations

5. HUMANITARIAN CRISES
   - Refugee movements
   - Food insecurity hotspots
   - Disease outbreaks in conflict zones
   - Climate-induced displacement

For EACH threat, provide:
- Threat ID and classification
- Source credibility (high/medium/low)
- Severity level (critical/high/medium/low)
- Geographic region and specific location
- Affected parties
- Timeline and urgency
- Potential escalation pathways
- Recommended monitoring actions
- Related threats (IDs)

Use current real-world data. Be specific with locations, actors, and timeframes.`,
        response_json_schema: {
          type: "object",
          properties: {
            timestamp: { type: "string" },
            feed_summary: { type: "string" },
            threats: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  threat_id: { type: "string" },
                  category: { type: "string" },
                  title: { type: "string" },
                  description: { type: "string" },
                  severity: { type: "string" },
                  source: { type: "string" },
                  source_credibility: { type: "string" },
                  region: { type: "string" },
                  location: { type: "string" },
                  affected_parties: { type: "array", items: { type: "string" } },
                  timeline: { type: "string" },
                  urgency: { type: "string" },
                  escalation_pathways: { type: "array", items: { type: "string" } },
                  monitoring_actions: { type: "array", items: { type: "string" } },
                  related_threats: { type: "array", items: { type: "string" } },
                  confidence_score: { type: "number" }
                }
              }
            },
            regional_breakdown: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  region: { type: "string" },
                  threat_count: { type: "number" },
                  highest_severity: { type: "string" }
                }
              }
            },
            alerts: {
              type: "array",
              items: {
                type: "object",
                properties: {
                  alert_type: { type: "string" },
                  message: { type: "string" },
                  urgency: { type: "string" }
                }
              }
            }
          }
        },
        add_context_from_internet: true
      });

      setFeeds(result);
      return result;
    }
  });

  useEffect(() => {
    fetchThreatIntelMutation.mutate();

    // Auto-refresh every 5 minutes
    const interval = setInterval(() => {
      fetchThreatIntelMutation.mutate();
    }, 5 * 60 * 1000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (onSubscriptionChange) {
      onSubscriptionChange({
        regions: selectedRegions,
        types: selectedThreatTypes,
        threshold: alertThreshold
      });
    }
  }, [selectedRegions, selectedThreatTypes, alertThreshold]);

  const filterThreats = (threats) => {
    if (!threats) return [];

    return threats.filter(threat => {
      const regionMatch = selectedRegions.length === 0 || selectedRegions.includes(threat.region);
      const typeMatch = selectedThreatTypes.length === 0 || selectedThreatTypes.includes(threat.category);

      const severityLevels = { critical: 4, high: 3, medium: 2, low: 1 };
      const thresholdLevels = { critical: 4, high: 3, medium: 2, low: 1 };
      const severityMatch = severityLevels[threat.severity?.toLowerCase()] >= thresholdLevels[alertThreshold];

      return regionMatch && typeMatch && severityMatch;
    });
  };

  const filteredThreats = filterThreats(feeds?.threats);

  const getSeverityColor = (severity) => {
    const colors = {
      critical: 'red',
      high: 'orange',
      medium: 'yellow',
      low: 'green'
    };
    return colors[severity?.toLowerCase()] || 'slate';
  };

  const availableRegions = [...new Set(feeds?.threats?.map(t => t.region) || [])];
  const availableTypes = [...new Set(feeds?.threats?.map(t => t.category) || [])];

  return (
    <div className="space-y-4">
      <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center gap-3">
            <Shield className="w-6 h-6 text-cyan-400" />
            <div>
              <h3 className="text-xl font-bold text-cyan-400 glow-text font-mono">
                THREAT INTELLIGENCE FEED
              </h3>
              <p className="text-slate-400 text-xs font-mono mt-1">
                OSINT aggregation • Real-time monitoring • Multi-source verification
              </p>
            </div>
          </div>
          <Button
            onClick={() => fetchThreatIntelMutation.mutate()}
            disabled={fetchThreatIntelMutation.isPending}
            size="sm"
            className="bg-cyan-500/20 hover:bg-cyan-500/30 text-cyan-400 border border-cyan-500/30 font-mono"
          >
            {fetchThreatIntelMutation.isPending ? (
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
            ) : (
              <Radio className="w-4 h-4 mr-2 animate-pulse" />
            )}
            REFRESH
          </Button>
        </div>

        {feeds && (
          <div className="mb-4 p-3 bg-blue-950/20 cyber-border rounded">
            <p className="text-slate-300 font-mono text-sm">{feeds.feed_summary}</p>
            <div className="text-xs text-slate-500 font-mono mt-1">
              Last updated: {new Date(feeds.timestamp).toLocaleTimeString()}
            </div>
          </div>
        )}

        {/* Subscription Controls */}
        <div className="mb-4 p-4 bg-slate-900/50 cyber-border rounded">
          <div className="flex items-center gap-2 mb-3">
            <Filter className="w-4 h-4 text-purple-400" />
            <h4 className="text-sm font-bold text-purple-400 font-mono">SUBSCRIPTION FILTERS</h4>
          </div>

          <div className="grid md:grid-cols-3 gap-4">
            <div>
              <label className="text-xs text-slate-400 font-mono mb-2 block">Regions</label>
              <div className="flex flex-wrap gap-1">
                {availableRegions.map((region, idx) => (
                  <Badge
                    key={idx}
                    onClick={() => {
                      if (selectedRegions.includes(region)) {
                        setSelectedRegions(selectedRegions.filter(r => r !== region));
                      } else {
                        setSelectedRegions([...selectedRegions, region]);
                      }
                    }}
                    className={`cursor-pointer font-mono text-xs ${
                      selectedRegions.includes(region)
                        ? 'bg-cyan-500/30 text-cyan-400 border-cyan-500/50'
                        : 'bg-slate-800/50 text-slate-400 border-slate-600/30'
                    }`}
                  >
                    {region}
                  </Badge>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs text-slate-400 font-mono mb-2 block">Threat Types</label>
              <div className="flex flex-wrap gap-1">
                {availableTypes.map((type, idx) => (
                  <Badge
                    key={idx}
                    onClick={() => {
                      if (selectedThreatTypes.includes(type)) {
                        setSelectedThreatTypes(selectedThreatTypes.filter(t => t !== type));
                      } else {
                        setSelectedThreatTypes([...selectedThreatTypes, type]);
                      }
                    }}
                    className={`cursor-pointer font-mono text-xs ${
                      selectedThreatTypes.includes(type)
                        ? 'bg-purple-500/30 text-purple-400 border-purple-500/50'
                        : 'bg-slate-800/50 text-slate-400 border-slate-600/30'
                    }`}
                  >
                    {type}
                  </Badge>
                ))}
              </div>
            </div>

            <div>
              <label className="text-xs text-slate-400 font-mono mb-2 block">Alert Threshold</label>
              <div className="flex gap-1">
                {['low', 'medium', 'high', 'critical'].map((level) => (
                  <Badge
                    key={level}
                    onClick={() => setAlertThreshold(level)}
                    className={`cursor-pointer font-mono text-xs ${
                      alertThreshold === level
                        ? `bg-${getSeverityColor(level)}-500/30 text-${getSeverityColor(level)}-400 border-${getSeverityColor(level)}-500/50`
                        : 'bg-slate-800/50 text-slate-400 border-slate-600/30'
                    }`}
                  >
                    {level.toUpperCase()}
                  </Badge>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Active Alerts */}
        {feeds?.alerts && feeds.alerts.length > 0 && (
          <div className="mb-4 space-y-2">
            {feeds.alerts.map((alert, idx) => (
              <div key={idx} className={`p-3 bg-${getSeverityColor(alert.urgency)}-950/20 cyber-border rounded flex items-start gap-2`}>
                <Bell className={`w-4 h-4 text-${getSeverityColor(alert.urgency)}-400 mt-0.5 animate-pulse`} />
                <div className="flex-1">
                  <Badge className={`bg-${getSeverityColor(alert.urgency)}-500/20 text-${getSeverityColor(alert.urgency)}-400 border-${getSeverityColor(alert.urgency)}-500/30 font-mono text-xs mb-1`}>
                    {alert.alert_type}
                  </Badge>
                  <p className="text-slate-300 font-mono text-xs">{alert.message}</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>

      {/* Threat Feed */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h4 className="text-md font-bold text-cyan-400 font-mono">
            ACTIVE THREATS ({filteredThreats?.length || 0})
          </h4>
        </div>

        {filteredThreats?.map((threat, idx) => (
          <Card key={idx} className={`bg-slate-950/80 backdrop-blur-xl cyber-border p-4 border-l-4 border-${getSeverityColor(threat.severity)}-500`}>
            <div className="flex items-start justify-between mb-3">
              <div className="flex-1">
                <div className="flex items-center gap-2 mb-2">
                  <Badge className={`bg-${getSeverityColor(threat.severity)}-500/20 text-${getSeverityColor(threat.severity)}-400 border-${getSeverityColor(threat.severity)}-500/30 font-mono text-xs`}>
                    {threat.severity?.toUpperCase()}
                  </Badge>
                  <Badge variant="outline" className="border-purple-500/30 text-purple-400 font-mono text-xs">
                    {threat.category}
                  </Badge>
                  <Badge variant="outline" className="border-slate-500/30 text-slate-400 font-mono text-xs">
                    {threat.threat_id}
                  </Badge>
                </div>
                <h4 className="text-lg font-bold text-cyan-400 font-mono mb-1">{threat.title}</h4>
                <p className="text-slate-400 font-mono text-sm mb-2">{threat.description}</p>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-3 mb-3">
              <div className="p-2 bg-slate-900/50 cyber-border rounded">
                <div className="text-xs text-slate-500 font-mono mb-1">Location</div>
                <div className="flex items-center gap-1">
                  <Globe className="w-3 h-3 text-cyan-400" />
                  <span className="text-cyan-400 font-mono text-sm">{threat.location}</span>
                </div>
              </div>

              <div className="p-2 bg-slate-900/50 cyber-border rounded">
                <div className="text-xs text-slate-500 font-mono mb-1">Timeline</div>
                <span className="text-yellow-400 font-mono text-sm">{threat.timeline}</span>
              </div>

              <div className="p-2 bg-slate-900/50 cyber-border rounded">
                <div className="text-xs text-slate-500 font-mono mb-1">Source</div>
                <div className="flex items-center gap-2">
                  <span className="text-slate-300 font-mono text-sm">{threat.source}</span>
                  <Badge className={`${
                    threat.source_credibility === 'high' ? 'bg-green-500/20 text-green-400 border-green-500/30' :
                    threat.source_credibility === 'medium' ? 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30' :
                    'bg-red-500/20 text-red-400 border-red-500/30'
                  } font-mono text-xs`}>
                    {threat.source_credibility}
                  </Badge>
                </div>
              </div>

              <div className="p-2 bg-slate-900/50 cyber-border rounded">
                <div className="text-xs text-slate-500 font-mono mb-1">Confidence</div>
                <div className="flex items-center gap-2">
                  <div className="flex-1 bg-slate-800 rounded-full h-2">
                    <div 
                      className={`bg-${getSeverityColor(threat.severity)}-400 h-2 rounded-full`}
                      style={{ width: `${threat.confidence_score}%` }}
                    ></div>
                  </div>
                  <span className="text-slate-300 font-mono text-xs">{threat.confidence_score}%</span>
                </div>
              </div>
            </div>

            {threat.affected_parties?.length > 0 && (
              <div className="mb-3">
                <div className="text-xs text-slate-500 font-mono mb-1">Affected Parties</div>
                <div className="flex flex-wrap gap-1">
                  {threat.affected_parties.map((party, i) => (
                    <Badge key={i} variant="outline" className="border-orange-500/30 text-orange-400 font-mono text-xs">
                      {party}
                    </Badge>
                  ))}
                </div>
              </div>
            )}

            {threat.escalation_pathways?.length > 0 && (
              <div className="mb-3 p-2 bg-red-950/20 cyber-border rounded">
                <div className="text-xs font-bold text-red-400 font-mono mb-1 flex items-center gap-1">
                  <TrendingUp className="w-3 h-3" />
                  Escalation Pathways
                </div>
                <ul className="space-y-1">
                  {threat.escalation_pathways.map((pathway, i) => (
                    <li key={i} className="text-slate-400 font-mono text-xs flex items-start gap-2">
                      <span className="text-red-400">▸</span>
                      {pathway}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {threat.monitoring_actions?.length > 0 && (
              <div className="p-2 bg-green-950/20 cyber-border rounded">
                <div className="text-xs font-bold text-green-400 font-mono mb-1">Recommended Actions</div>
                <ul className="space-y-1">
                  {threat.monitoring_actions.map((action, i) => (
                    <li key={i} className="text-slate-400 font-mono text-xs flex items-start gap-2">
                      <span className="text-green-400">✓</span>
                      {action}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </Card>
        ))}
      </div>

      {/* Regional Breakdown */}
      {feeds?.regional_breakdown && (
        <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-4">
          <h4 className="text-md font-bold text-purple-400 font-mono mb-3">REGIONAL THREAT DISTRIBUTION</h4>
          <div className="grid md:grid-cols-3 gap-3">
            {feeds.regional_breakdown.map((region, idx) => (
              <div key={idx} className="p-3 bg-slate-900/50 cyber-border rounded">
                <div className="text-cyan-400 font-mono font-bold mb-1">{region.region}</div>
                <div className="flex items-center justify-between text-xs font-mono">
                  <span className="text-slate-400">{region.threat_count} threats</span>
                  <Badge className={`bg-${getSeverityColor(region.highest_severity)}-500/20 text-${getSeverityColor(region.highest_severity)}-400 border-${getSeverityColor(region.highest_severity)}-500/30 text-xs`}>
                    {region.highest_severity}
                  </Badge>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}
    </div>
  );
}

src/components/map/DynamicGeopoliticalMa:
import React, { useState } from 'react';
import { MapContainer, TileLayer, Circle, Popup, Polyline, LayersControl, GeoJSON } from 'react-leaflet';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { Slider } from '@/components/ui/slider';
import { AlertTriangle, Shield, TrendingDown, TrendingUp, Radio, Satellite, Users } from 'lucide-react';
import 'leaflet/dist/leaflet.css';

export default function DynamicGeopoliticalMap({ 
  conflictZones = [], 
  troopMovements = [], 
  stabilityData = [],
  allianceData = [],
  timelineData = null 
}) {
  const [activeLayer, setActiveLayer] = useState({
    conflicts: true,
    troops: true,
    stability: true,
    alliances: true
  });
  const [timeIndex, setTimeIndex] = useState(0);
  const [heatmapIntensity, setHeatmapIntensity] = useState(50);

  const getStabilityColor = (score) => {
    if (score >= 80) return '#22c55e';
    if (score >= 60) return '#eab308';
    if (score >= 40) return '#f97316';
    return '#ef4444';
  };

  const getThreatColor = (level) => {
    const colors = {
      'CRITICAL': '#ef4444',
      'HIGH': '#f97316',
      'MEDIUM': '#eab308',
      'LOW': '#22c55e'
    };
    return colors[level] || '#94a3b8';
  };

  const currentData = timelineData?.length > 0 ? timelineData[timeIndex] : null;

  return (
    <div className="relative w-full h-full rounded-xl overflow-hidden cyber-border">
      {/* Layer Controls */}
      <div className="absolute top-4 left-4 z-[1000] space-y-2">
        <Card className="bg-slate-950/95 backdrop-blur-xl cyber-border p-4">
          <h3 className="text-sm font-bold text-cyan-400 font-mono mb-3">MAP LAYERS</h3>
          <div className="space-y-2">
            <div className="flex items-center justify-between gap-3">
              <Label className="text-xs text-slate-300 font-mono">Conflict Zones</Label>
              <Switch
                checked={activeLayer.conflicts}
                onCheckedChange={(checked) => setActiveLayer({ ...activeLayer, conflicts: checked })}
                className="data-[state=checked]:bg-red-500"
              />
            </div>
            <div className="flex items-center justify-between gap-3">
              <Label className="text-xs text-slate-300 font-mono">Troop Movements</Label>
              <Switch
                checked={activeLayer.troops}
                onCheckedChange={(checked) => setActiveLayer({ ...activeLayer, troops: checked })}
                className="data-[state=checked]:bg-orange-500"
              />
            </div>
            <div className="flex items-center justify-between gap-3">
              <Label className="text-xs text-slate-300 font-mono">Stability Zones</Label>
              <Switch
                checked={activeLayer.stability}
                onCheckedChange={(checked) => setActiveLayer({ ...activeLayer, stability: checked })}
                className="data-[state=checked]:bg-green-500"
              />
            </div>
            <div className="flex items-center justify-between gap-3">
              <Label className="text-xs text-slate-300 font-mono">Alliance Lines</Label>
              <Switch
                checked={activeLayer.alliances}
                onCheckedChange={(checked) => setActiveLayer({ ...activeLayer, alliances: checked })}
                className="data-[state=checked]:bg-cyan-500"
              />
            </div>
          </div>
        </Card>

        {/* Heatmap Intensity */}
        <Card className="bg-slate-950/95 backdrop-blur-xl cyber-border p-4">
          <h3 className="text-sm font-bold text-purple-400 font-mono mb-3">INTENSITY</h3>
          <Slider
            value={[heatmapIntensity]}
            onValueChange={(value) => setHeatmapIntensity(value[0])}
            min={0}
            max={100}
            step={10}
            className="w-full"
          />
          <div className="text-xs text-slate-400 font-mono mt-2 text-center">
            {heatmapIntensity}%
          </div>
        </Card>
      </div>

      {/* Timeline Controls */}
      {timelineData && timelineData.length > 1 && (
        <div className="absolute bottom-4 left-1/2 transform -translate-x-1/2 z-[1000] w-[500px]">
          <Card className="bg-slate-950/95 backdrop-blur-xl cyber-border p-4">
            <div className="flex items-center gap-3 mb-3">
              <Radio className="w-4 h-4 text-green-400 animate-pulse" />
              <h3 className="text-sm font-bold text-green-400 font-mono">TIME SLIDER</h3>
              <Badge className="bg-cyan-500/20 text-cyan-400 border-cyan-500/30 font-mono text-xs ml-auto">
                {currentData?.date || `T+${timeIndex}`}
              </Badge>
            </div>
            <Slider
              value={[timeIndex]}
              onValueChange={(value) => setTimeIndex(value[0])}
              min={0}
              max={timelineData.length - 1}
              step={1}
              className="w-full"
            />
            <div className="flex justify-between text-xs font-mono text-slate-500 mt-2">
              <span>{timelineData[0]?.date || 'Start'}</span>
              <span>{timelineData[timelineData.length - 1]?.date || 'End'}</span>
            </div>
          </Card>
        </div>
      )}

      {/* Legend */}
      <div className="absolute bottom-4 right-4 z-[1000]">
        <Card className="bg-slate-950/95 backdrop-blur-xl cyber-border p-4">
          <h3 className="text-xs font-bold text-green-400 font-mono mb-3 glow-text">LEGEND</h3>
          <div className="space-y-2 text-xs font-mono">
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-red-500"></div>
              <span className="text-slate-300">Active Conflict</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-orange-500 animate-pulse"></div>
              <span className="text-slate-300">Troop Movement</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-3 h-3 rounded-full bg-green-500"></div>
              <span className="text-slate-300">Stable Region</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-1 h-3 bg-cyan-500"></div>
              <span className="text-slate-300">Alliance Link</span>
            </div>
          </div>
        </Card>
      </div>

      {/* Map */}
      <MapContainer
        center={[20, 0]}
        zoom={2}
        style={{ height: '100%', width: '100%', background: '#0a0e27' }}
        className="z-10"
      >
        <TileLayer
          url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
        />

        {/* Conflict Zones */}
        {activeLayer.conflicts && conflictZones.map((zone, idx) => (
          zone.coordinates && (
            <Circle
              key={`conflict-${idx}`}
              center={[zone.coordinates.latitude, zone.coordinates.longitude]}
              radius={zone.radius || 100000}
              pathOptions={{
                fillColor: getThreatColor(zone.threat_level),
                fillOpacity: (heatmapIntensity / 100) * 0.4,
                color: getThreatColor(zone.threat_level),
                weight: 2
              }}
            >
              <Popup className="cyber-popup">
                <Card className="bg-slate-900/95 border-red-500/30 p-3 min-w-[250px]">
                  <div className="flex items-center gap-2 mb-2">
                    <AlertTriangle className="w-4 h-4 text-red-400" />
                    <h4 className="text-sm font-bold text-red-400 font-mono">{zone.name}</h4>
                  </div>
                  <Badge className={`mb-2 ${zone.threat_level === 'CRITICAL' ? 'bg-red-500/20 text-red-400 border-red-500/30' : 'bg-orange-500/20 text-orange-400 border-orange-500/30'} font-mono text-xs`}>
                    {zone.threat_level} THREAT
                  </Badge>
                  <p className="text-slate-400 font-mono text-xs mb-2">{zone.description}</p>
                  {zone.active_units && (
                    <div className="flex items-center gap-2 text-xs font-mono">
                      <Users className="w-3 h-3 text-cyan-400" />
                      <span className="text-cyan-400">{zone.active_units.toLocaleString()} troops</span>
                    </div>
                  )}
                </Card>
              </Popup>
            </Circle>
          )
        ))}

        {/* Troop Movements */}
        {activeLayer.troops && troopMovements.map((movement, idx) => (
          movement.path && movement.path.length >= 2 && (
            <React.Fragment key={`troop-${idx}`}>
              <Polyline
                positions={movement.path.map(p => [p.latitude, p.longitude])}
                pathOptions={{
                  color: '#f97316',
                  weight: 3,
                  opacity: 0.8,
                  dashArray: '10, 10'
                }}
                className="animate-pulse"
              >
                <Popup className="cyber-popup">
                  <Card className="bg-slate-900/95 border-orange-500/30 p-3">
                    <div className="flex items-center gap-2 mb-2">
                      <Satellite className="w-4 h-4 text-orange-400" />
                      <h4 className="text-sm font-bold text-orange-400 font-mono">
                        TROOP MOVEMENT
                      </h4>
                    </div>
                    <div className="space-y-1 text-xs font-mono">
                      <div><span className="text-slate-500">Unit:</span> <span className="text-slate-300">{movement.unit}</span></div>
                      <div><span className="text-slate-500">Size:</span> <span className="text-cyan-400">{movement.size.toLocaleString()}</span></div>
                      <div><span className="text-slate-500">Direction:</span> <span className="text-slate-300">{movement.direction}</span></div>
                      <div><span className="text-slate-500">Speed:</span> <span className="text-green-400">{movement.speed}</span></div>
                    </div>
                  </Card>
                </Popup>
              </Polyline>
              {/* End marker */}
              <Circle
                center={[movement.path[movement.path.length - 1].latitude, movement.path[movement.path.length - 1].longitude]}
                radius={30000}
                pathOptions={{
                  fillColor: '#f97316',
                  fillOpacity: 0.8,
                  color: '#ffffff',
                  weight: 2
                }}
                className="animate-pulse"
              />
            </React.Fragment>
          )
        ))}

        {/* Stability Zones */}
        {activeLayer.stability && stabilityData.map((region, idx) => (
          region.coordinates && (
            <Circle
              key={`stability-${idx}`}
              center={[region.coordinates.latitude, region.coordinates.longitude]}
              radius={region.radius || 150000}
              pathOptions={{
                fillColor: getStabilityColor(region.stability_score),
                fillOpacity: (heatmapIntensity / 100) * 0.3,
                color: getStabilityColor(region.stability_score),
                weight: 2,
                dashArray: '5, 5'
              }}
            >
              <Popup className="cyber-popup">
                <Card className="bg-slate-900/95 border-green-500/30 p-3">
                  <div className="flex items-center gap-2 mb-2">
                    <Shield className="w-4 h-4 text-green-400" />
                    <h4 className="text-sm font-bold text-green-400 font-mono">{region.name}</h4>
                  </div>
                  <div className="space-y-2">
                    <div className="flex items-center justify-between">
                      <span className="text-xs text-slate-500 font-mono">Stability:</span>
                      <div className="flex items-center gap-2">
                        <span className="text-sm font-bold font-mono" style={{ color: getStabilityColor(region.stability_score) }}>
                          {region.stability_score}/100
                        </span>
                        {region.trend === 'improving' ? (
                          <TrendingUp className="w-3 h-3 text-green-400" />
                        ) : (
                          <TrendingDown className="w-3 h-3 text-red-400" />
                        )}
                      </div>
                    </div>
                    <p className="text-slate-400 font-mono text-xs">{region.analysis}</p>
                  </div>
                </Card>
              </Popup>
            </Circle>
          )
        ))}

        {/* Alliance Lines */}
        {activeLayer.alliances && allianceData.map((alliance, idx) => (
          alliance.countries && alliance.countries.length >= 2 && (
            <Polyline
              key={`alliance-${idx}`}
              positions={alliance.countries.map(c => [c.latitude, c.longitude])}
              pathOptions={{
                color: '#06b6d4',
                weight: 2,
                opacity: 0.6,
                dashArray: '5, 10'
              }}
            >
              <Popup className="cyber-popup">
                <Card className="bg-slate-900/95 border-cyan-500/30 p-3">
                  <div className="flex items-center gap-2 mb-2">
                    <Shield className="w-4 h-4 text-cyan-400" />
                    <h4 className="text-sm font-bold text-cyan-400 font-mono">{alliance.name}</h4>
                  </div>
                  <div className="text-xs font-mono">
                    <div className="mb-2">
                      <span className="text-slate-500">Type:</span> <span className="text-slate-300">{alliance.type}</span>
                    </div>
                    <div className="mb-2">
                      <span className="text-slate-500">Members:</span>
                    </div>
                    <div className="flex flex-wrap gap-1">
                      {alliance.countries.map((country, i) => (
                        <Badge key={i} variant="outline" className="border-cyan-500/30 text-cyan-400 text-xs">
                          {country.name}
                        </Badge>
                      ))}
                    </div>
                  </div>
                </Card>
              </Popup>
            </Polyline>
          )
        ))}
      </MapContainer>
    </div>
  );
}

