import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, CircleMarker, Popup, useMap } from 'react-leaflet';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import { 
  Layers, CloudRain, Droplets, Wheat, Flame, 
  TrendingUp, AlertTriangle, Shield
} from 'lucide-react';

// Risk data generator (in production, this would come from external APIs)
const generateRiskData = () => {
  const regions = [
    { name: 'Middle East', lat: 29.3117, lng: 47.4818, climate: 85, water: 90, food: 70, political: 88 },
    { name: 'Central Africa', lat: 4.3947, lng: 18.5582, climate: 75, water: 80, food: 85, political: 82 },
    { name: 'South Asia', lat: 20.5937, lng: 78.9629, climate: 70, water: 75, food: 65, political: 60 },
    { name: 'Eastern Europe', lat: 48.3794, lng: 31.1656, climate: 45, water: 40, food: 35, political: 85 },
    { name: 'Southeast Asia', lat: 12.8797, lng: 121.7740, climate: 80, water: 55, food: 50, political: 55 },
    { name: 'North Africa', lat: 26.8206, lng: 30.8025, climate: 82, water: 88, food: 72, political: 70 },
    { name: 'Central Asia', lat: 41.3775, lng: 64.5853, climate: 60, water: 78, food: 55, political: 65 },
    { name: 'Horn of Africa', lat: 8.6195, lng: 46.1996, climate: 88, water: 92, food: 90, political: 85 },
    { name: 'Caribbean', lat: 21.4691, lng: -78.6569, climate: 75, water: 45, food: 40, political: 45 },
    { name: 'Amazon Basin', lat: -3.4653, lng: -62.2159, climate: 70, water: 35, food: 45, political: 50 }
  ];
  return regions;
};

function MapLegend({ layers }) {
  return (
    <div className="absolute bottom-4 left-4 z-[1000] bg-slate-950/90 backdrop-blur-sm cyber-border rounded-lg p-3">
      <div className="text-xs font-mono text-slate-400 mb-2">RISK LEVELS</div>
      <div className="space-y-1">
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full bg-red-500"></div>
          <span className="text-xs font-mono text-red-400">Critical (80-100)</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full bg-orange-500"></div>
          <span className="text-xs font-mono text-orange-400">High (60-79)</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full bg-yellow-500"></div>
          <span className="text-xs font-mono text-yellow-400">Medium (40-59)</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full bg-green-500"></div>
          <span className="text-xs font-mono text-green-400">Low (0-39)</span>
        </div>
      </div>
    </div>
  );
}

export default function GeospatialRiskOverlay() {
  const [riskData, setRiskData] = useState([]);
  const [layers, setLayers] = useState({
    climate: true,
    water: false,
    food: false,
    political: false
  });

  useEffect(() => {
    setRiskData(generateRiskData());
  }, []);

  const getRiskColor = (value) => {
    if (value >= 80) return '#ef4444';
    if (value >= 60) return '#f97316';
    if (value >= 40) return '#eab308';
    return '#22c55e';
  };

  const getActiveRiskValue = (region) => {
    if (layers.climate) return region.climate;
    if (layers.water) return region.water;
    if (layers.food) return region.food;
    if (layers.political) return region.political;
    return 0;
  };

  const getActiveLayerName = () => {
    if (layers.climate) return 'Climate Vulnerability';
    if (layers.water) return 'Water Scarcity';
    if (layers.food) return 'Food Security Risk';
    if (layers.political) return 'Political Instability';
    return 'No Layer Selected';
  };

  const toggleLayer = (layer) => {
    setLayers({
      climate: layer === 'climate',
      water: layer === 'water',
      food: layer === 'food',
      political: layer === 'political'
    });
  };

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg bg-orange-500/20 border border-orange-500/30">
            <Layers className="w-6 h-6 text-orange-400" />
          </div>
          <div>
            <h3 className="text-xl font-bold text-orange-400 glow-text font-mono">
              GEOSPATIAL RISK OVERLAY
            </h3>
            <p className="text-xs text-slate-400 font-mono">Multi-Factor Risk Visualization</p>
          </div>
        </div>
        <Badge className="bg-orange-500/20 text-orange-400 border-orange-500/30 font-mono">
          {getActiveLayerName().toUpperCase()}
        </Badge>
      </div>

      {/* Layer Controls */}
      <div className="flex flex-wrap gap-2 mb-4">
        <Button
          size="sm"
          onClick={() => toggleLayer('climate')}
          className={`font-mono text-xs ${layers.climate ? 'bg-red-500/20 text-red-400 border-red-500/30' : 'bg-slate-800/50 text-slate-400 border-slate-600/30'}`}
        >
          <CloudRain className="w-3 h-3 mr-1" />
          CLIMATE
        </Button>
        <Button
          size="sm"
          onClick={() => toggleLayer('water')}
          className={`font-mono text-xs ${layers.water ? 'bg-blue-500/20 text-blue-400 border-blue-500/30' : 'bg-slate-800/50 text-slate-400 border-slate-600/30'}`}
        >
          <Droplets className="w-3 h-3 mr-1" />
          WATER
        </Button>
        <Button
          size="sm"
          onClick={() => toggleLayer('food')}
          className={`font-mono text-xs ${layers.food ? 'bg-yellow-500/20 text-yellow-400 border-yellow-500/30' : 'bg-slate-800/50 text-slate-400 border-slate-600/30'}`}
        >
          <Wheat className="w-3 h-3 mr-1" />
          FOOD
        </Button>
        <Button
          size="sm"
          onClick={() => toggleLayer('political')}
          className={`font-mono text-xs ${layers.political ? 'bg-purple-500/20 text-purple-400 border-purple-500/30' : 'bg-slate-800/50 text-slate-400 border-slate-600/30'}`}
        >
          <Shield className="w-3 h-3 mr-1" />
          POLITICAL
        </Button>
      </div>

      {/* Map */}
      <div className="relative h-[400px] rounded-lg overflow-hidden cyber-border">
        <MapContainer
          center={[20, 40]}
          zoom={2}
          style={{ height: '100%', width: '100%', background: '#0a0e27' }}
          zoomControl={false}
        >
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
          />

          {riskData.map((region, idx) => {
            const riskValue = getActiveRiskValue(region);
            const color = getRiskColor(riskValue);

            return (
              <CircleMarker
                key={idx}
                center={[region.lat, region.lng]}
                radius={Math.max(15, riskValue / 3)}
                pathOptions={{
                  color: color,
                  fillColor: color,
                  fillOpacity: 0.4,
                  weight: 2
                }}
              >
                <Popup className="risk-popup">
                  <div className="bg-slate-950 p-3 rounded-lg min-w-[200px]">
                    <div className="text-green-400 font-mono font-bold mb-2">{region.name}</div>
                    <div className="space-y-2">
                      <div className="flex items-center justify-between">
                        <span className="text-slate-400 font-mono text-xs">Climate Risk:</span>
                        <Badge className={`${region.climate >= 70 ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'} font-mono text-xs`}>
                          {region.climate}%
                        </Badge>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-slate-400 font-mono text-xs">Water Scarcity:</span>
                        <Badge className={`${region.water >= 70 ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'} font-mono text-xs`}>
                          {region.water}%
                        </Badge>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-slate-400 font-mono text-xs">Food Risk:</span>
                        <Badge className={`${region.food >= 70 ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'} font-mono text-xs`}>
                          {region.food}%
                        </Badge>
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-slate-400 font-mono text-xs">Political Risk:</span>
                        <Badge className={`${region.political >= 70 ? 'bg-red-500/20 text-red-400' : 'bg-green-500/20 text-green-400'} font-mono text-xs`}>
                          {region.political}%
                        </Badge>
                      </div>
                    </div>
                  </div>
                </Popup>
              </CircleMarker>
            );
          })}
        </MapContainer>

        <MapLegend layers={layers} />
      </div>

      {/* Risk Summary */}
      <div className="grid grid-cols-4 gap-3 mt-4">
        {['climate', 'water', 'food', 'political'].map(type => {
          const avgRisk = Math.round(riskData.reduce((acc, r) => acc + r[type], 0) / riskData.length);
          const icons = { climate: CloudRain, water: Droplets, food: Wheat, political: Shield };
          const Icon = icons[type];

          return (
            <div key={type} className="bg-slate-900/50 cyber-border rounded-lg p-3 text-center">
              <Icon className="w-5 h-5 mx-auto mb-2 text-slate-400" />
              <div className="text-xs text-slate-400 font-mono uppercase mb-1">{type}</div>
              <div className={`text-lg font-bold font-mono ${avgRisk >= 70 ? 'text-red-400' : avgRisk >= 50 ? 'text-yellow-400' : 'text-green-400'}`}>
                {avgRisk}%
              </div>
            </div>
          );
        })}
      </div>
    </Card>
  );
}

src/components/map/InteractiveRegionDraw:
import React, { useState, useRef } from 'react';
import { base44 } from '@/api/base44Client';
import { useMutation } from '@tanstack/react-query';
import { Card } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { 
  Map, Loader2, Pencil, Trash2, Target, Zap, 
  Save, Square, Circle, Triangle
} from 'lucide-react';
import { toast } from 'sonner';
import { MapContainer, TileLayer, Polygon, useMapEvents, Marker, Popup } from 'react-leaflet';

// Draw handler component
function DrawHandler({ isDrawing, onPointAdd }) {
  useMapEvents({
    click: (e) => {
      if (isDrawing) {
        onPointAdd([e.latlng.lat, e.latlng.lng]);
      }
    }
  });
  return null;
}

export default function InteractiveRegionDrawer({ onRegionAnalyzed }) {
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentPoints, setCurrentPoints] = useState([]);
  const [savedRegions, setSavedRegions] = useState(() => {
    const saved = localStorage.getItem('warMatrixCustomRegions');
    return saved ? JSON.parse(saved) : [];
  });
  const [regionName, setRegionName] = useState('');
  const [selectedRegion, setSelectedRegion] = useState(null);
  const [analysisResult, setAnalysisResult] = useState(null);

  const addPoint = (point) => {
    setCurrentPoints([...currentPoints, point]);
  };

  const finishDrawing = () => {
    if (currentPoints.length < 3) {
      toast.error('Need at least 3 points to create a region');
      return;
    }
    setIsDrawing(false);
  };

  const saveRegion = () => {
    if (!regionName.trim() || currentPoints.length < 3) {
      toast.error('Please provide a name and at least 3 points');
      return;
    }

    const region = {
      id: Date.now().toString(),
      name: regionName,
      points: currentPoints,
      createdAt: new Date().toISOString(),
      color: `hsl(${Math.random() * 360}, 70%, 50%)`
    };

    const updated = [...savedRegions, region];
    setSavedRegions(updated);
    localStorage.setItem('warMatrixCustomRegions', JSON.stringify(updated));

    setCurrentPoints([]);
    setRegionName('');
    toast.success('Region saved');
  };

  const deleteRegion = (regionId) => {
    const updated = savedRegions.filter(r => r.id !== regionId);
    setSavedRegions(updated);
    localStorage.setItem('warMatrixCustomRegions', JSON.stringify(updated));
    if (selectedRegion?.id === regionId) {
      setSelectedRegion(null);
    }
    toast.success('Region deleted');
  };

  const analyzeRegionMutation = useMutation({
    mutationFn: async (region) => {
      const centerLat = region.points.reduce((sum, p) => sum + p[0], 0) / region.points.length;
      const centerLng = region.points.reduce((sum, p) => sum + p[1], 0) / region.points.length;

      const response = await base44.integrations.Core.InvokeLLM({
        prompt: `You are a geopolitical analyst. Analyze the following custom region for potential threats and conflict scenarios.

REGION: ${region.name}
CENTER COORDINATES: ${centerLat.toFixed(4)}, ${centerLng.toFixed(4)}
BOUNDARY POINTS: ${region.points.map(p => `[${p[0].toFixed(4)}, ${p[1].toFixed(4)}]`).join(', ')}

Based on these coordinates, identify:
1. The likely geographic area this encompasses
2. Countries/territories within or near this region
3. Current threat assessment for this area
4. Historical conflicts in this region
5. Economic and resource factors
6. Potential flashpoints
7. Recommended monitoring priorities

Provide a comprehensive threat analysis for this custom-defined region.`,
        response_json_schema: {
          type: 'object',
          properties: {
            identified_location: { type: 'string' },
            countries_involved: { type: 'array', items: { type: 'string' } },
            threat_level: { type: 'number' },
            threat_assessment: { type: 'string' },
            historical_conflicts: { type: 'array', items: { type: 'string' } },
            current_tensions: { type: 'array', items: { type: 'string' } },
            economic_factors: { type: 'array', items: { type: 'string' } },
            resource_considerations: { type: 'array', items: { type: 'string' } },
            flashpoints: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, risk_level: { type: 'string' }, description: { type: 'string' } } } },
            monitoring_priorities: { type: 'array', items: { type: 'string' } },
            scenario_recommendations: { type: 'array', items: { type: 'string' } }
          }
        },
        add_context_from_internet: true
      });

      return response;
    },
    onSuccess: (data) => {
      setAnalysisResult(data);
      if (onRegionAnalyzed) {
        onRegionAnalyzed(data);
      }
      toast.success('Region analysis complete');
    }
  });

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl border border-sky-900/40 p-6">
      <div className="flex items-center gap-3 mb-6">
        <div className="p-2 rounded-lg bg-cyan-500/20 border border-cyan-500/30">
          <Map className="w-6 h-6 text-cyan-400" />
        </div>
        <div>
          <h3 className="text-xl font-bold text-cyan-400 glow-text font-mono">
            INTERACTIVE REGION DRAWER
          </h3>
          <p className="text-xs text-slate-400 font-mono">Draw custom regions for AI threat analysis</p>
        </div>
      </div>

      <div className="space-y-4">
        {/* Drawing Controls */}
        <div className="flex items-center gap-2">
          <Button
            onClick={() => {
              setIsDrawing(!isDrawing);
              if (!isDrawing) setCurrentPoints([]);
            }}
            className={`font-mono text-xs ${
              isDrawing 
                ? 'bg-red-500/20 text-red-400 border-red-500/30' 
                : 'bg-cyan-500/20 text-cyan-400 border-cyan-500/30'
            } border`}
          >
            <Pencil className="w-4 h-4 mr-2" />
            {isDrawing ? 'CANCEL DRAWING' : 'START DRAWING'}
          </Button>

          {isDrawing && currentPoints.length >= 3 && (
            <Button
              onClick={finishDrawing}
              className="bg-green-500/20 text-green-400 border border-green-500/30 font-mono text-xs"
            >
              FINISH ({currentPoints.length} points)
            </Button>
          )}

          {!isDrawing && currentPoints.length >= 3 && (
            <>
              <Input
                value={regionName}
                onChange={(e) => setRegionName(e.target.value)}
                placeholder="Region name..."
                className="bg-slate-900/50 border-cyan-500/30 text-slate-200 font-mono w-48"
              />
              <Button
                onClick={saveRegion}
                className="bg-green-500/20 text-green-400 border border-green-500/30 font-mono text-xs"
              >
                <Save className="w-4 h-4 mr-2" />
                SAVE
              </Button>
            </>
          )}
        </div>

        {isDrawing && (
          <div className="bg-cyan-500/10 border border-cyan-500/30 rounded-lg p-3">
            <p className="text-cyan-400 font-mono text-xs">
              Click on the map to add points. Need at least 3 points to create a region.
              Points added: {currentPoints.length}
            </p>
          </div>
        )}

        {/* Map */}
        <div className="h-[400px] rounded-lg overflow-hidden border border-sky-800/30">
          <MapContainer
            center={[20, 0]}
            zoom={2}
            style={{ height: '100%', width: '100%' }}
            className="z-0"
          >
            <TileLayer
              url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
              attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
            />

            <DrawHandler isDrawing={isDrawing} onPointAdd={addPoint} />

            {/* Current drawing */}
            {currentPoints.length >= 3 && (
              <Polygon
                positions={currentPoints}
                pathOptions={{ color: '#06b6d4', fillColor: '#06b6d4', fillOpacity: 0.3 }}
              />
            )}

            {/* Saved regions */}
            {savedRegions.map((region) => (
              <Polygon
                key={region.id}
                positions={region.points}
                pathOptions={{ 
                  color: selectedRegion?.id === region.id ? '#22c55e' : region.color, 
                  fillColor: region.color, 
                  fillOpacity: 0.3 
                }}
                eventHandlers={{
                  click: () => setSelectedRegion(region)
                }}
              >
                <Popup>
                  <div className="font-mono">
                    <div className="font-bold">{region.name}</div>
                    <div className="text-xs">{region.points.length} points</div>
                  </div>
                </Popup>
              </Polygon>
            ))}
          </MapContainer>
        </div>

        {/* Saved Regions List */}
        {savedRegions.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-cyan-400 font-mono font-bold text-sm">SAVED REGIONS</h4>
            {savedRegions.map((region) => (
              <div
                key={region.id}
                className={`bg-slate-900/50 border rounded-lg p-3 cursor-pointer ${
                  selectedRegion?.id === region.id ? 'border-green-500/50' : 'border-sky-800/30'
                }`}
                onClick={() => setSelectedRegion(region)}
              >
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div 
                      className="w-4 h-4 rounded" 
                      style={{ backgroundColor: region.color }}
                    />
                    <span className="text-green-400 font-mono font-bold text-sm">{region.name}</span>
                    <Badge className="bg-slate-700/50 text-slate-400 font-mono text-[10px]">
                      {region.points.length} points
                    </Badge>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        analyzeRegionMutation.mutate(region);
                      }}
                      disabled={analyzeRegionMutation.isPending}
                      className="bg-purple-500/20 text-purple-400 border border-purple-500/30 font-mono text-xs"
                    >
                      {analyzeRegionMutation.isPending ? (
                        <Loader2 className="w-3 h-3 animate-spin" />
                      ) : (
                        <>
                          <Target className="w-3 h-3 mr-1" />
                          ANALYZE
                        </>
                      )}
                    </Button>
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={(e) => {
                        e.stopPropagation();
                        deleteRegion(region.id);
                      }}
                      className="text-red-400 hover:text-red-300 hover:bg-red-500/10"
                    >
                      <Trash2 className="w-3 h-3" />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Analysis Results */}
        {analysisResult && (
          <Card className="bg-purple-500/10 border border-purple-500/30 p-4 space-y-4">
            <div className="flex items-center justify-between">
              <h4 className="text-purple-400 font-mono font-bold">REGION ANALYSIS</h4>
              <Badge className={`font-mono ${
                analysisResult.threat_level >= 70 ? 'bg-red-500/20 text-red-400' :
                analysisResult.threat_level >= 40 ? 'bg-orange-500/20 text-orange-400' :
                'bg-green-500/20 text-green-400'
              }`}>
                Threat: {analysisResult.threat_level}/100
              </Badge>
            </div>

            <div className="bg-slate-800/50 rounded p-3">
              <div className="text-xs text-slate-500 font-mono mb-1">IDENTIFIED LOCATION</div>
              <div className="text-cyan-400 font-mono text-sm">{analysisResult.identified_location}</div>
            </div>

            <div className="bg-slate-800/50 rounded p-3">
              <div className="text-xs text-slate-500 font-mono mb-1">THREAT ASSESSMENT</div>
              <p className="text-slate-300 font-mono text-xs">{analysisResult.threat_assessment}</p>
            </div>

            {analysisResult.flashpoints?.length > 0 && (
              <div>
                <div className="text-xs text-red-400 font-mono mb-2">FLASHPOINTS</div>
                <div className="space-y-2">
                  {analysisResult.flashpoints.map((fp, i) => (
                    <div key={i} className="bg-red-500/10 border border-red-500/20 rounded p-2">
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-red-400 font-mono text-xs font-bold">{fp.name}</span>
                        <Badge className="bg-red-500/20 text-red-400 font-mono text-[10px]">
                          {fp.risk_level}
                        </Badge>
                      </div>
                      <p className="text-slate-400 font-mono text-[10px]">{fp.description}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {analysisResult.monitoring_priorities?.length > 0 && (
              <div>
                <div className="text-xs text-cyan-400 font-mono mb-2">MONITORING PRIORITIES</div>
                <ul className="space-y-1">
                  {analysisResult.monitoring_priorities.map((priority, i) => (
                    <li key={i} className="text-slate-300 font-mono text-xs flex items-start gap-2">
                      <Target className="w-3 h-3 mt-0.5 text-cyan-400 flex-shrink-0" />
                      {priority}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </Card>
        )}
      </div>
    </Card>
  );
}

