        >
          <TileLayer
            url="https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png"
            attribution='&copy; OpenStreetMap'
          />

          {data.map((point) => {
            const Icon = getTypeIcon(point.type);
            return (
              <React.Fragment key={point.id}>
                <Circle
