                              )}
                            </div>
                          ))}
                        </div>
                      )}
                    </Card>
                  </Popup>
                </Marker>
              </React.Fragment>
            );
          })}
        </MapContainer>

        {/* Legend */}
        <div className="absolute bottom-4 right-4 bg-slate-950/90 backdrop-blur-xl cyber-border rounded-lg p-3 z-[1000] font-mono text-xs max-w-[200px]">
