import React, { useState } from 'react';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { 
  ScatterChart, 
  Scatter, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  Legend, 
  ResponsiveContainer,
  ZAxis,
  Cell,
  ReferenceLine
} from 'recharts';
import { AlertTriangle, TrendingUp } from 'lucide-react';

export default function EnhancedClimateConflictChart({ conflicts }) {
  const [highlightedPoint, setHighlightedPoint] = useState(null);

  const chartData = conflicts?.map(c => ({
    name: c.name,
    climate: c.climate_impact_score,
    resources: c.resource_scarcity_score,
    probability: c.probability,
    socioEconomic: c.socio_economic_score,
    region: c.region
  })) || [];

  // Calculate anomalies (high risk but low attention)
  const anomalies = chartData.filter(d => 
    (d.climate > 70 || d.resources > 70) && d.probability < 60
  );

  const CustomTooltip = ({ active, payload }) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      return (
        <Card className="bg-slate-950/95 backdrop-blur-xl cyber-border p-4">
          <h4 className="text-cyan-400 font-mono text-sm font-bold mb-2">{data.name}</h4>
          <div className="space-y-1 text-xs font-mono">
            <div className="flex justify-between gap-4">
              <span className="text-slate-400">Climate Impact:</span>
              <span className="text-blue-400 font-bold">{data.climate}/100</span>
            </div>
            <div className="flex justify-between gap-4">
              <span className="text-slate-400">Resource Scarcity:</span>
              <span className="text-orange-400 font-bold">{data.resources}/100</span>
            </div>
            <div className="flex justify-between gap-4">
              <span className="text-slate-400">Probability:</span>
              <span className="text-purple-400 font-bold">{data.probability}%</span>
            </div>
            <div className="flex justify-between gap-4">
              <span className="text-slate-400">Socio-Economic:</span>
              <span className="text-red-400 font-bold">{data.socioEconomic}/100</span>
            </div>
          </div>
          {anomalies.some(a => a.name === data.name) && (
            <Badge className="mt-2 bg-red-500/20 text-red-400 border-red-500/30 font-mono text-xs">
              ⚠ HIGH-RISK ANOMALY
            </Badge>
          )}
        </Card>
      );
    }
    return null;
  };

  const getPointColor = (data) => {
    // High risk = red, medium = yellow, low = green
    const avgRisk = (data.climate + data.resources + data.socioEconomic) / 3;
    if (avgRisk > 70) return '#ef4444';
    if (avgRisk > 50) return '#f97316';
    if (avgRisk > 30) return '#eab308';
    return '#22c55e';
  };

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <div className="flex items-start justify-between mb-4">
        <div>
          <h3 className="text-xl font-bold text-purple-400 glow-text font-mono mb-2">
            CLIMATE-RESOURCE-CONFLICT INTERPLAY
          </h3>
          <p className="text-slate-400 font-mono text-xs">
            Bubble size = conflict probability • Color = risk level
          </p>
        </div>
        {anomalies.length > 0 && (
          <Badge className="bg-red-500/20 text-red-400 border-red-500/30 font-mono flex items-center gap-2">
            <AlertTriangle className="w-3 h-3" />
            {anomalies.length} Anomalies Detected
          </Badge>
        )}
      </div>

      <div className="h-[400px]">
        <ResponsiveContainer width="100%" height="100%">
          <ScatterChart margin={{ top: 20, right: 20, bottom: 20, left: 20 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" />
            <XAxis 
              type="number" 
              dataKey="climate" 
              name="Climate Impact" 
              domain={[0, 100]}
              stroke="#94a3b8"
              style={{ fontFamily: 'monospace', fontSize: '11px' }}
              label={{ value: 'Climate Impact Score', position: 'insideBottom', offset: -10, fill: '#94a3b8', fontFamily: 'monospace' }}
            />
            <YAxis 
              type="number" 
              dataKey="resources" 
              name="Resource Scarcity"
              domain={[0, 100]}
              stroke="#94a3b8"
              style={{ fontFamily: 'monospace', fontSize: '11px' }}
              label={{ value: 'Resource Scarcity Score', angle: -90, position: 'insideLeft', fill: '#94a3b8', fontFamily: 'monospace' }}
            />
            <ZAxis type="number" dataKey="probability" range={[50, 400]} name="Probability" />
            <Tooltip content={<CustomTooltip />} />
            <Legend wrapperStyle={{ fontFamily: 'monospace', fontSize: '12px' }} />

            {/* Reference lines for high-risk thresholds */}
            <ReferenceLine x={70} stroke="#ef4444" strokeDasharray="5 5" opacity={0.3} />
            <ReferenceLine y={70} stroke="#ef4444" strokeDasharray="5 5" opacity={0.3} />

            <Scatter 
              name="Conflicts" 
              data={chartData} 
              onMouseEnter={(data) => setHighlightedPoint(data.name)}
              onMouseLeave={() => setHighlightedPoint(null)}
            >
              {chartData.map((entry, index) => (
                <Cell 
                  key={`cell-${index}`} 
                  fill={getPointColor(entry)}
                  fillOpacity={highlightedPoint === entry.name ? 1 : 0.7}
                  stroke={anomalies.some(a => a.name === entry.name) ? '#ef4444' : 'none'}
                  strokeWidth={anomalies.some(a => a.name === entry.name) ? 3 : 0}
                />
              ))}
            </Scatter>
          </ScatterChart>
        </ResponsiveContainer>
      </div>

      {/* Anomaly List */}
      {anomalies.length > 0 && (
        <div className="mt-4 p-3 bg-red-950/20 cyber-border rounded">
          <h4 className="text-sm font-bold text-red-400 font-mono mb-2 flex items-center gap-2">
            <TrendingUp className="w-4 h-4" />
            HIGH-RISK ANOMALIES (High Impact, Lower Probability)
          </h4>
          <div className="flex flex-wrap gap-2">
            {anomalies.map((anomaly, i) => (
              <Badge key={i} variant="outline" className="border-red-500/30 text-red-400 font-mono text-xs">
                {anomaly.name} ({anomaly.probability}%)
              </Badge>
            ))}
          </div>
        </div>
      )}
    </Card>
  );
}

src/components/visualizations/Geopolitic:
import React, { useState, useEffect, useRef } from 'react';
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Network, Shield, Zap } from 'lucide-react';

export default function GeopoliticalActorNetwork({ conflictData }) {
  const canvasRef = useRef(null);
  const [hoveredNode, setHoveredNode] = useState(null);
  const [nodes, setNodes] = useState([]);
  const [edges, setEdges] = useState([]);

  useEffect(() => {
    if (!conflictData || conflictData.length === 0) return;

    // Extract actors and their relationships
    const actorMap = new Map();
    const edgeList = [];

    conflictData.forEach(conflict => {
      const regions = conflict.affected_regions || [];

      regions.forEach(region => {
        if (!actorMap.has(region)) {
          actorMap.set(region, {
            id: region,
            name: region,
            conflicts: [],
            totalRisk: 0,
            resourceDependencies: []
          });
        }

        const actor = actorMap.get(region);
        actor.conflicts.push(conflict);
        actor.totalRisk += conflict.probability || 0;
      });

      // Create edges between co-involved regions
      for (let i = 0; i < regions.length; i++) {
        for (let j = i + 1; j < regions.length; j++) {
          edgeList.push({
            source: regions[i],
            target: regions[j],
            conflict: conflict.name,
            strength: conflict.probability || 50
          });
        }
      }
    });

    // Convert to array and position nodes
    const nodeArray = Array.from(actorMap.values()).map((actor, idx) => ({
      ...actor,
      x: 400 + Math.cos(idx * 2 * Math.PI / actorMap.size) * 200,
      y: 300 + Math.sin(idx * 2 * Math.PI / actorMap.size) * 200,
      radius: 10 + (actor.totalRisk / 100) * 20
    }));

    setNodes(nodeArray);
    setEdges(edgeList);
  }, [conflictData]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || nodes.length === 0) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // Clear canvas
    ctx.clearRect(0, 0, width, height);

    // Draw edges
    ctx.strokeStyle = 'rgba(0, 255, 65, 0.2)';
    edges.forEach(edge => {
      const source = nodes.find(n => n.id === edge.source);
      const target = nodes.find(n => n.id === edge.target);

      if (source && target) {
        ctx.beginPath();
        ctx.moveTo(source.x, source.y);
        ctx.lineTo(target.x, target.y);
        ctx.lineWidth = edge.strength / 25;
        ctx.stroke();
      }
    });

    // Draw nodes
    nodes.forEach(node => {
      const isHovered = hoveredNode === node.id;

      // Node circle
      ctx.beginPath();
      ctx.arc(node.x, node.y, node.radius, 0, 2 * Math.PI);

      const riskLevel = node.totalRisk / node.conflicts.length;
      if (riskLevel > 70) {
        ctx.fillStyle = isHovered ? '#ff0040' : 'rgba(255, 0, 64, 0.6)';
      } else if (riskLevel > 40) {
        ctx.fillStyle = isHovered ? '#ffaa00' : 'rgba(255, 170, 0, 0.6)';
      } else {
        ctx.fillStyle = isHovered ? '#00ff41' : 'rgba(0, 255, 65, 0.6)';
      }
      ctx.fill();

      ctx.strokeStyle = '#00ff41';
      ctx.lineWidth = isHovered ? 3 : 1;
      ctx.stroke();

      // Node label
      if (isHovered) {
        ctx.fillStyle = '#00ff41';
        ctx.font = '12px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(node.name, node.x, node.y - node.radius - 10);
      }
    });
  }, [nodes, edges, hoveredNode]);

  const handleMouseMove = (e) => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const hoveredNodeFound = nodes.find(node => {
      const dx = x - node.x;
      const dy = y - node.y;
      return Math.sqrt(dx * dx + dy * dy) <= node.radius;
    });

    setHoveredNode(hoveredNodeFound ? hoveredNodeFound.id : null);
  };

  const hoveredNodeData = nodes.find(n => n.id === hoveredNode);

  return (
    <Card className="bg-slate-950/80 backdrop-blur-xl cyber-border p-6">
      <h3 className="text-xl font-bold text-cyan-400 glow-text font-mono mb-4 flex items-center gap-2">
        <Network className="w-6 h-6" />
        GEOPOLITICAL ACTOR NETWORK
      </h3>

      <div className="relative">
        <canvas
          ref={canvasRef}
          width={800}
          height={600}
          className="w-full h-[600px] bg-slate-900/50 rounded-lg cyber-border"
          onMouseMove={handleMouseMove}
          onMouseLeave={() => setHoveredNode(null)}
        />

        {hoveredNodeData && (
          <div className="absolute top-4 right-4 bg-slate-950/95 cyber-border rounded-lg p-4 min-w-[250px]">
            <h4 className="text-lg font-bold text-green-400 font-mono mb-2">
              {hoveredNodeData.name}
            </h4>

            <div className="space-y-2 text-sm font-mono">
              <div className="flex justify-between">
                <span className="text-slate-400">Conflicts:</span>
                <span className="text-cyan-400 font-bold">{hoveredNodeData.conflicts.length}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-slate-400">Avg Risk:</span>
                <span className="text-orange-400 font-bold">
                  {(hoveredNodeData.totalRisk / hoveredNodeData.conflicts.length).toFixed(0)}%
                </span>
              </div>
            </div>

            <div className="mt-3 pt-3 border-t border-green-500/20">
              <div className="text-xs text-slate-500 font-mono mb-2">Involved In:</div>
              <div className="space-y-1">
                {hoveredNodeData.conflicts.slice(0, 3).map((conflict, idx) => (
                  <Badge 
                    key={idx} 
                    variant="outline" 
                    className="text-xs border-purple-500/30 text-purple-400 font-mono block"
                  >
                    {conflict.name}
                  </Badge>
                ))}
                {hoveredNodeData.conflicts.length > 3 && (
                  <div className="text-xs text-slate-500 font-mono">
                    +{hoveredNodeData.conflicts.length - 3} more
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="mt-4 grid md:grid-cols-3 gap-4">
        <div className="p-3 bg-slate-900/50 cyber-border rounded">
          <Shield className="w-5 h-5 text-green-400 mb-2" />
          <div className="text-xs text-slate-400 font-mono">Total Actors</div>
          <div className="text-2xl font-bold text-green-400 font-mono">{nodes.length}</div>
        </div>
        <div className="p-3 bg-slate-900/50 cyber-border rounded">
          <Zap className="w-5 h-5 text-yellow-400 mb-2" />
          <div className="text-xs text-slate-400 font-mono">Connections</div>
          <div className="text-2xl font-bold text-yellow-400 font-mono">{edges.length}</div>
        </div>
        <div className="p-3 bg-slate-900/50 cyber-border rounded">
          <Network className="w-5 h-5 text-purple-400 mb-2" />
          <div className="text-xs text-slate-400 font-mono">Avg Conflicts/Actor</div>
          <div className="text-2xl font-bold text-purple-400 font-mono">
            {nodes.length > 0 ? (nodes.reduce((sum, n) => sum + n.conflicts.length, 0) / nodes.length).toFixed(1) : 0}
          </div>
        </div>
      </div>

      <div className="mt-4 p-3 bg-slate-900/50 cyber-border rounded">
        <div className="text-xs font-bold text-slate-400 font-mono mb-2">NODE COLORS</div>
        <div className="flex gap-4">
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-red-500"></div>
            <span className="text-xs text-slate-300 font-mono">High Risk (70%+)</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-yellow-500"></div>
            <span className="text-xs text-slate-300 font-mono">Medium Risk (40-69%)</span>
          </div>
          <div className="flex items-center gap-2">
            <div className="w-4 h-4 rounded-full bg-green-500"></div>
            <span className="text-xs text-slate-300 font-mono">Low Risk (&lt;40%)</span>
          </div>
        </div>
      </div>
    </Card>
  );
}

