                <div className="mb-3">
                  <h4 className="text-xs font-bold text-cyan-400 font-mono mb-2">INVOLVED PARTIES</h4>
                  <div className="flex flex-wrap gap-2">
                    {flashpoint.involved_parties.map((party, i) => (
