          {selectedWar && (
            <WarDebriefing 
              war={selectedWar} 
              onClose={() => setShowDebriefing(false)} 
            />
          )}
        </DialogContent>
      </Dialog>

      {/* Comparative Analysis */}
      {showComparison && selectedWars.length >= 2 && (
        <ComparativeWarAnalysis selectedWars={selectedWars} />
      )}
    </div>
  );
}

