                  location: { type: "string" },
                  category: { type: "string" }
                }
              }
            },
            sentiment_analysis: {
              type: "object",
              properties: {
                overall_score: { type: "number" },
                sentiment_label: { type: "string" },
                regional_breakdown: {
                  type: "array",
                  items: {
                    type: "object",
                    properties: {
                      region: { type: "string" },
                      score: { type: "number" },
                      trend: { type: "string" }
                    }
                  }
                },
                trending_topics: { type: "array", items: { type: "string" } }
              }
            },
            economic_indicators: {
              type: "object",
              properties: {
                oil_price: {
                  type: "object",
                  properties: {
