                },
                gold_price: {
                  type: "object",
                  properties: {
                    current: { type: "number" },
                    change_30d: { type: "number" },
                    trend: { type: "string" },
                    monthly_history: {
                      type: "array",
                      items: {
                        type: "object",
                        properties: {
