                type: "object",
                properties: {
                  type: { type: "string" },
                  location: { type: "string" },
                  description: { type: "string" },
                  timestamp: { type: "string" },
                  severity: { type: "string" }
                }
              }
            }
          }
        },
        add_context_from_internet: true
      });

      setLiveData(result);
      setLastUpdate(new Date().toISOString());

