                        <p className="text-slate-400 font-mono text-sm mb-2">{intel.description}</p>
                        <div className="text-xs text-slate-500 font-mono">
                          Observed: {intel.timestamp}
                        </div>
                      </div>
                    ))}
                  </div>
                </Card>
              </TabsContent>
            </Tabs>
          )}
        </div>
      </div>
    </div>
  );
}

